function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const fullPhase = safeLoopT / duration;
  const p = sceneProgress;

  // Palette — Petrol Teal, Bright Peach, Soft Ivory
  const TEAL_BG = '#072A33';
  const TEAL_DARK = '#051F26';
  const TEAL_PANEL = '#0D3944';
  const TEAL_MID = '#164F5E';
  const PEACH = '#FF9F7A';
  const IVORY = '#FDF7F0';
  const MUTED = '#9BC4CC';

  const FONT_FAMILY = 'Inter, "Segoe UI", system-ui, -apple-system, sans-serif';
  const CONTOUR_N = 48;

  function clamp(v, a, b) {
    return v < a ? a : v > b ? b : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(x) {
    const u = clamp(x, 0, 1);
    return 1 - Math.pow(1 - u, 3);
  }

  function easeInCubic(x) {
    const u = clamp(x, 0, 1);
    return u * u * u;
  }

  function easeInOutQuart(x) {
    const u = clamp(x, 0, 1);
    return u < 0.5 ? 8 * u * u * u * u : 1 - Math.pow(-2 * u + 2, 4) / 2;
  }

  function hexToRgb(hex) {
    const h = hex.replace('#', '');
    return [
      parseInt(h.slice(0, 2), 16),
      parseInt(h.slice(2, 4), 16),
      parseInt(h.slice(4, 6), 16)
    ];
  }

  function lerpColor(hexA, hexB, u) {
    const k = clamp(u, 0, 1);
    const a = hexToRgb(hexA);
    const b = hexToRgb(hexB);
    const r = Math.round(lerp(a[0], b[0], k));
    const g = Math.round(lerp(a[1], b[1], k));
    const bl = Math.round(lerp(a[2], b[2], k));
    return `rgb(${r}, ${g}, ${bl})`;
  }

  function roundRectPath(x, y, w, h, r) {
    const rr = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0.5 || h <= 0.5) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = `${weight} ${size}px ${FONT_FAMILY}`;
    const m = ctx.measureText(text).width;
    if (m > maxW && m > 0) {
      size = size * (maxW / m);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (drawContent && alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  // Deterministic Clockwise Perimeter Samplers (arc-length aligned, exact N = 48 points, Top-Left Start -3*PI/4)
  function sampleSuperellipse(n, rx, ry, powExp) {
    const dense = n * 10;
    const raw = [];
    const cum = [0];
    let totalLen = 0;
    for (let k = 0; k <= dense; k++) {
      const a = -Math.PI * 0.75 + (k / dense) * Math.PI * 2;
      const ca = Math.cos(a);
      const sa = Math.sin(a);
      const x = Math.sign(ca) * Math.pow(Math.abs(ca), 2 / powExp) * rx;
      const y = Math.sign(sa) * Math.pow(Math.abs(sa), 2 / powExp) * ry;
      raw.push([x, y]);
      if (k > 0) {
        totalLen += Math.hypot(x - raw[k - 1][0], y - raw[k - 1][1]);
        cum.push(totalLen);
      }
    }
    const pts = [];
    let idx = 0;
    for (let i = 0; i < n; i++) {
      const target = (i / n) * totalLen;
      while (idx < dense - 1 && cum[idx + 1] < target) idx++;
      const seg = cum[idx + 1] - cum[idx];
      const u = seg > 0 ? clamp((target - cum[idx]) / seg, 0, 1) : 0;
      pts.push([lerp(raw[idx][0], raw[idx + 1][0], u), lerp(raw[idx][1], raw[idx + 1][1], u)]);
    }
    return pts;
  }

  function samplePolygon(corners, n) {
    const m = corners.length;
    const edges = [];
    let totalLen = 0;
    for (let i = 0; i < m; i++) {
      const p0 = corners[i];
      const p1 = corners[(i + 1) % m];
      const len = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
      edges.push({ p0, p1, len });
      totalLen += len;
    }
    const counts = new Array(m).fill(1);
    let remaining = Math.max(0, n - m);
    const exactExtra = edges.map((e, i) => ({
      i,
      val: totalLen > 0 ? (e.len / totalLen) * remaining : 0
    }));
    let assigned = 0;
    for (let k = 0; k < m; k++) {
      const add = Math.floor(exactExtra[k].val);
      counts[k] += add;
      exactExtra[k].rem = exactExtra[k].val - add;
      assigned += add;
    }
    exactExtra.sort((a, b) => b.rem - a.rem);
    for (let r = 0; r < remaining - assigned; r++) {
      counts[exactExtra[r].i]++;
    }
    const pts = [];
    for (let i = 0; i < m; i++) {
      const cnt = counts[i];
      const e = edges[i];
      for (let j = 0; j < cnt; j++) {
        const u = j / cnt;
        pts.push([lerp(e.p0[0], e.p1[0], u), lerp(e.p0[1], e.p1[1], u)]);
      }
    }
    return pts;
  }

  function hexVertices(rx, ry) {
    const verts = [];
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI * 0.75 + (i / 6) * Math.PI * 2;
      verts.push([Math.cos(a) * rx, Math.sin(a) * ry]);
    }
    return verts;
  }

  function lerpContour(a, b, u) {
    const out = [];
    for (let i = 0; i < a.length; i++) {
      out.push([lerp(a[i][0], b[i][0], u), lerp(a[i][1], b[i][1], u)]);
    }
    return out;
  }

  function traceContour(pts, cx, cy, scale, rotRad) {
    const cosR = Math.cos(rotRad);
    const sinR = Math.sin(rotRad);
    for (let i = 0; i < pts.length; i++) {
      const px = pts[i][0] * scale;
      const py = pts[i][1] * scale;
      const rx = px * cosR - py * sinR + cx;
      const ry = px * sinR + py * cosR + cy;
      if (i === 0) ctx.moveTo(rx, ry);
      else ctx.lineTo(rx, ry);
    }
    ctx.closePath();
  }

  function drawMorphedShape(cx, cy, scale, rotRad, outerPts, fillCol, holePts, holeScale, strokeCol, strokeW) {
    ctx.save();
    ctx.beginPath();
    traceContour(outerPts, cx, cy, scale, rotRad);
    if (holePts && holeScale > 0.04) {
      traceContour(holePts, cx, cy, scale * holeScale, rotRad);
    }
    ctx.fillStyle = fillCol;
    ctx.fill('evenodd');
    if (strokeCol && strokeW > 0.4) {
      ctx.strokeStyle = strokeCol;
      ctx.lineWidth = strokeW;
      ctx.lineJoin = 'round';
      ctx.stroke();
    }
    ctx.restore();
  }

  // Normalized Vector Primitives & Bold Swiss Glyph Contours
  const SHAPE_CIRCLE = sampleSuperellipse(CONTOUR_N, 0.88, 0.88, 2.0);
  const SHAPE_SQUIRCLE = sampleSuperellipse(CONTOUR_N, 0.88, 0.88, 4.4);
  const SHAPE_HEX = samplePolygon(hexVertices(0.92, 0.92), CONTOUR_N);
  const SHAPE_CAPSULE = sampleSuperellipse(CONTOUR_N, 2.2, 0.62, 5.0);
  const SHAPE_SMALL_CAPSULE = sampleSuperellipse(CONTOUR_N, 0.84, 0.54, 4.6);

  const GLYPH_H = samplePolygon([
    [-0.78, -0.96], [-0.30, -0.96], [-0.30, -0.20], [0.30, -0.20],
    [0.30, -0.96], [0.78, -0.96], [0.78, 0.96], [0.30, 0.96],
    [0.30, 0.20], [-0.30, 0.20], [-0.30, 0.96], [-0.78, 0.96]
  ], CONTOUR_N);

  const GLYPH_O_OUTER = sampleSuperellipse(CONTOUR_N, 0.84, 0.96, 4.2);
  const GLYPH_O_HOLE = sampleSuperellipse(24, 0.34, 0.50, 3.6);

  const GLYPH_T = samplePolygon([
    [-0.84, -0.96], [0.84, -0.96], [0.84, -0.52], [0.25, -0.52],
    [0.25, 0.96], [-0.25, 0.96], [-0.25, -0.52], [-0.84, -0.52]
  ], CONTOUR_N);

  const GLYPH_5 = samplePolygon([
    [-0.72, -0.96], [0.74, -0.96], [0.74, -0.58], [-0.30, -0.58],
    [-0.30, -0.16], [0.76, -0.16], [0.76, 0.96], [-0.74, 0.96],
    [-0.74, 0.58], [0.32, 0.58], [0.32, 0.20], [-0.72, 0.20]
  ], CONTOUR_N);

  const GLYPH_0_OUTER = sampleSuperellipse(CONTOUR_N, 0.78, 0.96, 4.2);
  const GLYPH_0_HOLE = sampleSuperellipse(24, 0.31, 0.50, 3.6);

  // 1. Clean Petrol Teal Background (Strictly Zero Glow, Zero Outer Edge Border Strokes, Zero Corner Frames)
  ctx.fillStyle = TEAL_BG;
  ctx.fillRect(0, 0, width, height);

  const safeX = width * 0.05;
  const stageW = width - safeX * 2;
  const topBarY = height * 0.044;
  const topBarH = minSide * 0.05;
  const botBarH = minSide * 0.05;
  const botBarY = height - height * 0.044 - botBarH;
  const stageTop = topBarY + topBarH + height * 0.032;
  const stageBot = botBarY - height * 0.032;
  const stageH = stageBot - stageTop;
  const gap = minSide * 0.024;
  const cardR = minSide * 0.02;

  // Interior architectural subtle geometric dot grid
  ctx.fillStyle = '#0B3742';
  const gCols = 14;
  const gRows = 6;
  for (let r = 0; r < gRows; r++) {
    const gy = lerp(stageTop + minSide * 0.02, stageBot - minSide * 0.02, r / (gRows - 1));
    for (let c = 0; c < gCols; c++) {
      const gx = lerp(safeX + minSide * 0.02, safeX + stageW - minSide * 0.02, c / (gCols - 1));
      ctx.beginPath();
      ctx.arc(gx, gy, minSide * 0.0022, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 2. Persistent Top Telemetry Header Bar
  drawClippedCard(safeX, topBarY, stageW, topBarH, topBarH * 0.36, TEAL_PANEL, (hx, hy, hw, hh) => {
    const pad = minSide * 0.022;
    const icoR = hh * 0.30;
    const icoX = hx + pad + icoR;
    const icoY = hy + hh * 0.5;

    // Rotating 3-node Vector Orbit Emblem (1 integer cycle over 20s)
    ctx.save();
    ctx.beginPath();
    ctx.arc(icoX, icoY, icoR, 0, Math.PI * 2);
    ctx.strokeStyle = TEAL_MID;
    ctx.lineWidth = Math.max(1.5, minSide * 0.002);
    ctx.stroke();
    for (let d = 0; d < 3; d++) {
      const da = fullPhase * Math.PI * 2 + (d / 3) * Math.PI * 2;
      ctx.beginPath();
      ctx.arc(icoX + Math.cos(da) * icoR, icoY + Math.sin(da) * icoR, icoR * 0.24, 0, Math.PI * 2);
      ctx.fillStyle = d === 0 ? PEACH : IVORY;
      ctx.fill();
    }
    ctx.restore();

    const titleStr = 'GEO-MORPH VECTOR  •  FLASH OFFER';
    const tFs = fitFontSize(titleStr, hw * 0.48, hh * 0.52, minSide * 0.022, 800);
    ctx.font = `800 ${tFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = IVORY;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(titleStr, icoX + icoR + pad * 0.8, hy + hh * 0.52);

    const pillW = hw * 0.17;
    const pillH = hh * 0.64;
    const px = hx + hw - pad - pillW;
    const py = hy + (hh - pillH) * 0.5;
    fillRoundRect(px, py, pillW, pillH, pillH * 0.5, PEACH);
    const pFs = fitFontSize('50% SAVINGS', pillW * 0.82, pillH * 0.56, minSide * 0.02, 900);
    ctx.font = `900 ${pFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = TEAL_BG;
    ctx.textAlign = 'center';
    ctx.fillText('50% SAVINGS', px + pillW * 0.5, py + pillH * 0.52);
  });

  // 3. Persistent Bottom Seamless Vector Marquee Bar
  drawClippedCard(safeX, botBarY, stageW, botBarH, botBarH * 0.36, TEAL_PANEL, (bx, by, bw, bh) => {
    const pad = minSide * 0.022;
    const badgeW = bw * 0.16;
    const badgeH = bh * 0.64;
    fillRoundRect(bx + pad, by + (bh - badgeH) * 0.5, badgeW, badgeH, badgeH * 0.5, TEAL_DARK);
    const bFs = fitFontSize('VECTOR DROP', badgeW * 0.82, badgeH * 0.56, minSide * 0.019, 800);
    ctx.font = `800 ${bFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = PEACH;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('VECTOR DROP', bx + pad + badgeW * 0.5, by + bh * 0.52);

    const clipX = bx + pad * 2 + badgeW;
    const clipW = bw - (pad * 3 + badgeW);
    const mFs = fitFontSize('M', clipW, bh * 0.44, minSide * 0.021, 800);
    ctx.font = `800 ${mFs}px ${FONT_FAMILY}`;
    const str = 'FLASH OFFER  •  50% DISCOUNT  •  VECTOR MORPH  •  LIMITED RELEASE  •  ';
    const segW = ctx.measureText(str).width;
    const offset = (fullPhase * 3 * segW) % segW;

    ctx.save();
    ctx.beginPath();
    ctx.rect(clipX, by, clipW, bh);
    ctx.clip();
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = MUTED;
    let cx = clipX - offset;
    while (cx < clipX + clipW + segW) {
      ctx.fillText(str, cx, by + bh * 0.52);
      cx += segW;
    }
    ctx.restore();
  });

  // 4. Main Layout: Grounded Center Morph Stage Card (top 68%) + Bottom Dual Telemetry Cards (32%)
  const heroH = stageH * 0.67;
  const botRowH = stageH - heroH - gap;
  const heroY = stageTop;
  const botRowY = heroY + heroH + gap;

  // Auxiliary bottom card envelope (smooth enter/exit within each scene, 0 at boundaries)
  function subCardEnv(enterDelay, exitDelay) {
    const inU = easeOutCubic(clamp((p - enterDelay) / 0.16, 0, 1));
    const outU = easeInCubic(clamp((p - (0.81 - exitDelay)) / 0.16, 0, 1));
    return clamp(inU * (1 - outU), 0, 1);
  }

  function subInnerAlpha(env) {
    return easeOutCubic(clamp((env - 0.80) / 0.18, 0, 1));
  }

  // Persistent Grounded Hero Stage Card (Seamless morphing stage across all 20s)
  drawClippedCard(safeX, heroY, stageW, heroH, cardR, TEAL_DARK, (hx, hy, hw, hh) => {
    const centerX = hx + hw * 0.5;
    const centerY = hy + hh * 0.5;
    const glyphSize = minSide * 0.115;
    const slotSpread = hw * 0.175;
    const x0 = centerX - slotSpread;
    const x1 = centerX;
    const x2 = centerX + slotSpread;

    // Subtle crisp connecting vector axis line cleanly behind shapes inside stage pad
    ctx.save();
    ctx.strokeStyle = TEAL_PANEL;
    ctx.lineWidth = Math.max(2, minSide * 0.003);
    ctx.beginPath();
    ctx.moveTo(hx + hw * 0.08, centerY);
    ctx.lineTo(hx + hw * 0.92, centerY);
    ctx.stroke();
    ctx.restore();

    // =========================================================================
    // SCENE 0 (0 - 5s): Three Peach Geometric Primitives -> Morph "HOT" -> Capsule Merge
    // =========================================================================
    if (currentScene === 0) {
      // Phase A (0 - 0.78): Circle/Squircle/Hex spin + radial burst ticks -> morph to H, O, T
      // Phase B (0.78 - 0.98): H, O, T gather smoothly into compact pill at center, then expand to unified Peach Capsule
      const rotU = easeOutCubic(clamp(p / 0.36, 0, 1));
      const morphU = easeInOutQuart(clamp((p - 0.16) / 0.32, 0, 1));
      const gatherU = easeInOutQuart(clamp((p - 0.78) / 0.14, 0, 1));
      const stretchU = easeInOutQuart(clamp((p - 0.87) / 0.11, 0, 1));

      // Subtle clean outer radial ticks strictly outside letter clearance zone
      const burstIn = easeOutCubic(clamp((p - 0.10) / 0.16, 0, 1));
      const burstOut = 1 - easeInCubic(clamp((p - 0.34) / 0.14, 0, 1));
      const burstVis = clamp(burstIn * burstOut, 0, 1);
      if (burstVis > 0.01 && gatherU < 0.2) {
        const slotXs = [x0, x1, x2];
        ctx.save();
        ctx.strokeStyle = PEACH;
        ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
        ctx.lineCap = 'round';
        ctx.globalAlpha *= burstVis * 0.72;
        for (let s = 0; s < 3; s++) {
          for (let k = 0; k < 8; k++) {
            const ang = (k / 8) * Math.PI * 2 + rotU * Math.PI * 0.5;
            const r0 = glyphSize * lerp(1.16, 1.30, burstIn);
            const r1 = r0 + glyphSize * 0.18;
            ctx.beginPath();
            ctx.moveTo(slotXs[s] + Math.cos(ang) * r0, centerY + Math.sin(ang) * r0);
            ctx.lineTo(slotXs[s] + Math.cos(ang) * r1, centerY + Math.sin(ang) * r1);
            ctx.stroke();
          }
        }
        ctx.restore();
      }

      if (gatherU <= 0.001) {
        const rotAng = rotU * Math.PI * 2;
        const col = lerpColor(PEACH, IVORY, morphU);
        const holeScale = easeOutCubic(clamp((morphU - 0.14) / 0.72, 0, 1));

        const shapeH = lerpContour(SHAPE_CIRCLE, GLYPH_H, morphU);
        const shapeO = lerpContour(SHAPE_SQUIRCLE, GLYPH_O_OUTER, morphU);
        const shapeT = lerpContour(SHAPE_HEX, GLYPH_T, morphU);

        drawMorphedShape(x0, centerY, glyphSize, rotAng, shapeH, col);
        drawMorphedShape(x1, centerY, glyphSize, rotAng, shapeO, col, GLYPH_O_HOLE, holeScale);
        drawMorphedShape(x2, centerY, glyphSize, rotAng, shapeT, col);
      } else {
        // Phase 1: H, O, T gather smoothly into centered compact pill; Phase 2: expand to wide Peach Capsule
        const gx0 = lerp(x0, centerX, gatherU);
        const gx2 = lerp(x2, centerX, gatherU);
        const col = lerpColor(IVORY, PEACH, gatherU);
        const hShrink = clamp(1 - gatherU * 1.4, 0, 1);

        const capTarget = lerpContour(SHAPE_SMALL_CAPSULE, SHAPE_CAPSULE, stretchU);
        const shapeH = lerpContour(GLYPH_H, capTarget, gatherU);
        const shapeO = lerpContour(GLYPH_O_OUTER, capTarget, gatherU);
        const shapeT = lerpContour(GLYPH_T, capTarget, gatherU);

        drawMorphedShape(gx0, centerY, glyphSize, 0, shapeH, col);
        drawMorphedShape(centerX, centerY, glyphSize, 0, shapeO, col, GLYPH_O_HOLE, hShrink);
        drawMorphedShape(gx2, centerY, glyphSize, 0, shapeT, col);
      }

      // Crisp clean subtitle below morph area once locked
      const subA = easeOutCubic(clamp((p - 0.44) / 0.14, 0, 1)) * (1 - easeInCubic(clamp((p - 0.76) / 0.08, 0, 1)));
      if (subA > 0.01) {
        ctx.save();
        ctx.globalAlpha *= subA;
        const subFs = fitFontSize('SEASON HIGHLIGHT OFFER', hw * 0.6, minSide * 0.032, minSide * 0.023, 800);
        ctx.font = `800 ${subFs}px ${FONT_FAMILY}`;
        ctx.fillStyle = PEACH;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SEASON HIGHLIGHT OFFER', centerX, hy + hh * 0.85);
        ctx.restore();
      }
    }

    // =========================================================================
    // SCENE 1 (5 - 10s): Unified Capsule Splits -> "50% OFF" Over Moving Soft Ivory Ribbon
    // =========================================================================
    else if (currentScene === 1) {
      const splitU = easeInOutQuart(clamp(p / 0.24, 0, 1));
      const morphU = easeInOutQuart(clamp((p - 0.22) / 0.26, 0, 1));
      const exitU = easeInCubic(clamp((p - 0.80) / 0.17, 0, 1));

      // Moving Soft Ivory Horizontal Ribbon Expanding cleanly outward from behind split capsules
      const ribIn = easeOutCubic(clamp((p - 0.08) / 0.18, 0, 1));
      const ribOut = 1 - easeInCubic(clamp((p - 0.80) / 0.17, 0, 1));
      const ribAlpha = easeOutCubic(clamp((p - 0.08) / 0.06, 0, 1)) * ribOut;
      if (ribAlpha > 0.005) {
        const rw = lerp(glyphSize * 4.3, hw * 0.88, ribIn) * ribOut;
        const rh = lerp(glyphSize * 1.22, hh * 0.62, ribIn) * lerp(0.72, 1.0, ribOut);
        const rr = lerp(glyphSize * 0.52, rh * 0.22, ribIn);
        const driftX = Math.sin(p * Math.PI * 2) * hw * 0.012;
        ctx.save();
        ctx.globalAlpha *= ribAlpha;
        fillRoundRect(centerX - rw * 0.5 + driftX, centerY - rh * 0.5, rw, rh, rr, IVORY);
        ctx.restore();
      }

      const contentAlpha = 1 - exitU;
      if (contentAlpha > 0.005) {
        const shrinkScale = 1 - exitU * 0.28;
        const splitScale = glyphSize * lerp(1.0, 0.94, splitU) * shrinkScale;

        // Starts seamlessly from exact Scene 0 end-state SHAPE_CAPSULE at centerX, scale = glyphSize
        const lx = lerp(centerX, centerX - hw * 0.222, splitU);
        const cxMid = lerp(centerX, centerX - hw * 0.072, splitU);
        const rx = lerp(centerX, centerX + hw * 0.155, splitU);

        const baseCap = lerpContour(SHAPE_CAPSULE, SHAPE_SMALL_CAPSULE, splitU);
        const shape5 = lerpContour(baseCap, GLYPH_5, morphU);
        const shape0 = lerpContour(baseCap, GLYPH_0_OUTER, morphU);
        const colGlyph = lerpColor(PEACH, TEAL_BG, clamp((morphU - 0.15) / 0.65, 0, 1));
        const zeroHole = easeOutCubic(clamp((morphU - 0.18) / 0.68, 0, 1));

        ctx.save();
        ctx.globalAlpha *= contentAlpha;

        drawMorphedShape(lx, centerY, splitScale, 0, shape5, colGlyph);
        drawMorphedShape(cxMid, centerY, splitScale, 0, shape0, colGlyph, GLYPH_0_HOLE, zeroHole);

        // Crisp Geometric "%" + "OFF" evolving from Right split capsule cleanly inside Ivory ribbon
        const capFade = 1 - easeInCubic(clamp((morphU - 0.18) / 0.45, 0, 1));
        if (capFade > 0.01) {
          ctx.save();
          ctx.globalAlpha *= capFade;
          drawMorphedShape(rx, centerY, splitScale, 0, baseCap, PEACH);
          ctx.restore();
        }

        const textMorphIn = easeOutCubic(clamp((morphU - 0.22) / 0.55, 0, 1));
        if (textMorphIn > 0.01) {
          ctx.save();
          ctx.globalAlpha *= textMorphIn;
          const unitScale = lerp(1.0, 0.94, splitU) * shrinkScale;
          // Crisp "%" vector circles & diagonal bar next to "0"
          const pctX = centerX + hw * 0.060;
          const pr = glyphSize * 0.20 * unitScale;
          ctx.fillStyle = PEACH;
          ctx.beginPath();
          ctx.arc(pctX - pr * 1.1, centerY - pr * 1.85, pr * 0.85, 0, Math.PI * 2);
          ctx.arc(pctX + pr * 1.1, centerY + pr * 1.85, pr * 0.85, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = TEAL_BG;
          ctx.lineWidth = pr * 0.72;
          ctx.lineCap = 'round';
          ctx.beginPath();
          ctx.moveTo(pctX - pr * 1.3, centerY + pr * 2.1);
          ctx.lineTo(pctX + pr * 1.3, centerY - pr * 2.1);
          ctx.stroke();

          // Bold "OFF" pill text on right inside Ivory ribbon
          const offFs = fitFontSize('OFF', hw * 0.28, hh * 0.45, minSide * 0.14, 900) * shrinkScale;
          ctx.font = `900 ${offFs}px ${FONT_FAMILY}`;
          ctx.fillStyle = TEAL_BG;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText('OFF', centerX + hw * 0.123, centerY + offFs * 0.04);
          ctx.restore();
        }

        ctx.restore();
      }
    }

    // =========================================================================
    // SCENE 2 (10 - 15s): Diagonal Stepped Waves + Dynamic Stroke-Weight "FLASH OFFER"
    // =========================================================================
    else if (currentScene === 2) {
      const waveIn = easeOutCubic(clamp(p / 0.22, 0, 1));
      const waveOut = 1 - easeInCubic(clamp((p - 0.82) / 0.17, 0, 1));
      const waveVis = clamp(waveIn * waveOut, 0, 1);

      // Diagonal Stepped Geometric Wave Ribbons strictly in Top & Bottom corner zones (clear of center text)
      if (waveVis > 0.01) {
        const steps = 6;
        const stepW = hw * 0.085;
        const stepH = hh * 0.055;
        const slideD = (1 - waveIn) * hw * 0.12;
        ctx.save();
        ctx.globalAlpha *= waveVis;
        for (let i = 0; i < steps; i++) {
          const drift = Math.sin(p * Math.PI * 2 + i * 0.45) * minSide * 0.006;
          // Bottom-left staircase wave
          fillRoundRect(
            hx + i * stepW * 0.72 - slideD,
            hy + hh - (steps - i) * stepH * 0.65 + drift,
            stepW,
            stepH * 0.6,
            stepH * 0.2,
            i % 2 === 0 ? TEAL_MID : PEACH
          );
          // Top-right staircase wave
          fillRoundRect(
            hx + hw - stepW - i * stepW * 0.72 + slideD,
            hy + (steps - 1 - i) * stepH * 0.65 - drift,
            stepW,
            stepH * 0.6,
            stepH * 0.2,
            i % 2 === 0 ? PEACH : IVORY
          );
        }
        ctx.restore();
      }

      // Dynamic Varying-Stroke-Thickness Text Morph: "FLASH" / "OFFER"
      const enterU = easeOutCubic(clamp((p - 0.06) / 0.30, 0, 1));
      const flashOutU = easeInCubic(clamp((p - 0.68) / 0.14, 0, 1));
      const textVis = enterU * (1 - flashOutU);
      const handU = easeInOutQuart(clamp((p - 0.80) / 0.17, 0, 1));

      if (textVis > 0.005) {
        const fSize = fitFontSize('FLASH OFFER', hw * 0.76, hh * 0.34, minSide * 0.115, 900);
        ctx.font = `900 ${fSize}px ${FONT_FAMILY}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        // Oscillating smooth stroke width + clean solid fill lock-in
        const strokeWave = (0.5 + 0.5 * Math.sin(p * Math.PI * 6)) * (1 - clamp((p - 0.60) / 0.14, 0, 1));
        const strokeW = Math.max(2, minSide * (0.003 + strokeWave * 0.008));
        const fillAlpha = easeOutCubic(clamp((p - 0.18) / 0.26, 0, 1));
        const yOff = (1 - enterU) * hh * 0.06 - flashOutU * hh * 0.04;

        // Top Word: "FLASH"
        ctx.save();
        ctx.globalAlpha *= textVis;
        ctx.lineWidth = strokeW;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = PEACH;
        ctx.strokeText('FLASH', centerX, centerY - hh * 0.15 + yOff);
        if (fillAlpha > 0.01) {
          ctx.globalAlpha *= fillAlpha;
          ctx.fillStyle = IVORY;
          ctx.fillText('FLASH', centerX, centerY - hh * 0.15 + yOff);
        }
        ctx.restore();

        // Bottom Word: "OFFER"
        ctx.save();
        ctx.globalAlpha *= textVis;
        ctx.lineWidth = strokeW;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = IVORY;
        ctx.strokeText('OFFER', centerX, centerY + hh * 0.16 - yOff);
        if (fillAlpha > 0.01) {
          ctx.globalAlpha *= fillAlpha;
          ctx.fillStyle = PEACH;
          ctx.fillText('OFFER', centerX, centerY + hh * 0.16 - yOff);
        }
        ctx.restore();
      }

      if (handU > 0.005) {
        // Bloom cleanly into crisp "HOT" glyph contours ready at Scene 3 start (p = 0)
        const sScale = glyphSize * handU;
        if (sScale > 1) {
          ctx.save();
          ctx.globalAlpha *= handU;
          drawMorphedShape(x0, centerY, sScale, 0, GLYPH_H, IVORY);
          drawMorphedShape(x1, centerY, sScale, 0, GLYPH_O_OUTER, IVORY, GLYPH_O_HOLE, 1);
          drawMorphedShape(x2, centerY, sScale, 0, GLYPH_T, IVORY);
          ctx.restore();
        }
      }
    }

    // =========================================================================
    // SCENE 3 (15 - 20s): "HOT" -> Dissolve Morph Back to Three Primitives Locked at t=0
    // =========================================================================
    else {
      // Phase A (0 - 0.36): Hold crisp "HOT" + dynamic highlight pulse
      // Phase B (0.36 - 0.78): Smooth contour morph back H/O/T -> Circle/Squircle/Hexagon
      // Phase C (0.78 - 0.97): Precision rotation settle to angle = 0 (exact t=0 parity!)
      const unMorphU = easeInOutQuart(clamp((p - 0.38) / 0.40, 0, 1));
      const rotBackU = easeOutCubic(clamp((p - 0.38) / 0.58, 0, 1));
      const rotAng = rotBackU * Math.PI * 2;
      const col = lerpColor(IVORY, PEACH, unMorphU);
      const holeScale = 1 - easeInCubic(clamp(unMorphU / 0.85, 0, 1));

      const shapeH = lerpContour(GLYPH_H, SHAPE_CIRCLE, unMorphU);
      const shapeO = lerpContour(GLYPH_O_OUTER, SHAPE_SQUIRCLE, unMorphU);
      const shapeT = lerpContour(GLYPH_T, SHAPE_HEX, unMorphU);

      drawMorphedShape(x0, centerY, glyphSize, rotAng, shapeH, col);
      drawMorphedShape(x1, centerY, glyphSize, rotAng, shapeO, col, GLYPH_O_HOLE, holeScale);
      drawMorphedShape(x2, centerY, glyphSize, rotAng, shapeT, col);

      const ctaVis = easeOutCubic(clamp((p - 0.04) / 0.12, 0, 1)) * (1 - easeInCubic(clamp((p - 0.26) / 0.12, 0, 1)));
      if (ctaVis > 0.01) {
        ctx.save();
        ctx.globalAlpha *= ctaVis;
        const btnH = hh * 0.15;
        const btnW = Math.min(hw * 0.36, btnH * 4.4);
        fillRoundRect(centerX - btnW * 0.5, hy + hh * 0.87 - btnH * 0.5, btnW, btnH, btnH * 0.5, PEACH);
        const cFs = fitFontSize('CLAIM 50% OFFER', btnW * 0.82, btnH * 0.52, minSide * 0.022, 900);
        ctx.font = `900 ${cFs}px ${FONT_FAMILY}`;
        ctx.fillStyle = TEAL_BG;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('CLAIM 50% OFFER', centerX, hy + hh * 0.87 + cFs * 0.03);
        ctx.restore();
      }
    }
  });

  // 5. Lower Auxiliary Dual Info Cards (Smooth enter & exit per scene, invisible at t=0 and t=20)
  const leftW = stageW * 0.58 - gap * 0.5;
  const rightW = stageW - leftW - gap;
  const rightX = safeX + leftW + gap;

  const envL = subCardEnv(0.04, 0.02);
  const envR = subCardEnv(0.08, 0.0);

  const stageLabels = [
    { badge: '01  •  CONTOUR MORPH', title: 'GEOMETRIC TRANSITION ACTIVE', metric: 'HOT DROP' },
    { badge: '02  •  RIBBON SPLIT', title: '50% AUTOMATIC MARKDOWN', metric: '50% OFF' },
    { badge: '03  •  DYNAMIC STROKE', title: 'FLASH OFFER COLLECTION', metric: 'LIMITED' },
    { badge: '04  •  SHAPE LOCK', title: 'SEAMLESS OFFER RESET', metric: 'GET NOW' }
  ];
  const meta = stageLabels[currentScene];

  if (envL > 0.01) {
    drawClippedCard(safeX, botRowY, leftW * envL, botRowH, cardR, TEAL_PANEL, (cx, cy, cw, ch) => {
      const pad = minSide * 0.026;
      const pillH = ch * 0.28;
      const pillW = leftW * 0.44;
      fillRoundRect(safeX + pad, cy + pad * 0.85, pillW, pillH, pillH * 0.5, TEAL_DARK);
      const bFs = fitFontSize(meta.badge, pillW * 0.86, pillH * 0.54, minSide * 0.019, 800);
      ctx.font = `800 ${bFs}px ${FONT_FAMILY}`;
      ctx.fillStyle = PEACH;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(meta.badge, safeX + pad + pillW * 0.5, cy + pad * 0.85 + pillH * 0.52);

      const tFs = fitFontSize(meta.title, leftW - pad * 2, ch * 0.28, minSide * 0.032, 900);
      ctx.font = `900 ${tFs}px ${FONT_FAMILY}`;
      ctx.fillStyle = IVORY;
      ctx.textAlign = 'left';
      ctx.fillText(meta.title, safeX + pad, cy + ch * 0.72);
    }, subInnerAlpha(envL));
  }

  if (envR > 0.01) {
    const rw = rightW * envR;
    drawClippedCard(rightX, botRowY, rw, botRowH, cardR, TEAL_PANEL, () => {
      const pad = minSide * 0.026;
      // Dedicated Clean Orbital Particle Track Widget inside Right Card (Zero text collision!)
      const orbR = Math.min(botRowH * 0.30, rightW * 0.16);
      const orbX = rightX + pad + orbR;
      const orbY = botRowY + botRowH * 0.5;

      ctx.beginPath();
      ctx.arc(orbX, orbY, orbR, 0, Math.PI * 2);
      ctx.strokeStyle = TEAL_MID;
      ctx.lineWidth = Math.max(2, minSide * 0.0028);
      ctx.stroke();

      const dots = 6;
      for (let d = 0; d < dots; d++) {
        const ang = p * Math.PI * 2 + (d / dots) * Math.PI * 2;
        ctx.beginPath();
        ctx.arc(orbX + Math.cos(ang) * orbR, orbY + Math.sin(ang) * orbR, orbR * (d % 2 === 0 ? 0.18 : 0.12), 0, Math.PI * 2);
        ctx.fillStyle = d % 2 === 0 ? PEACH : IVORY;
        ctx.fill();
      }

      const txtX = orbX + orbR + pad;
      const availW = rightX + rightW - pad - txtX;
      const mFs = fitFontSize(meta.metric, availW, botRowH * 0.36, minSide * 0.044, 900);
      ctx.font = `900 ${mFs}px ${FONT_FAMILY}`;
      ctx.fillStyle = PEACH;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillText(meta.metric, txtX, botRowY + botRowH * 0.42);

      const sFs = fitFontSize('VECTOR OFFER SERIES', availW, botRowH * 0.22, minSide * 0.019, 700);
      ctx.font = `700 ${sFs}px ${FONT_FAMILY}`;
      ctx.fillStyle = MUTED;
      ctx.fillText('VECTOR OFFER SERIES', txtX, botRowY + botRowH * 0.72);
    }, subInnerAlpha(envR));
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const fullPhase = safeLoopT / duration;
  const p = sceneProgress;

  // Palette — Espresso Cocoa, Warm Cream, Copper Amber
  const COCOA_BG = '#1B110E';
  const COCOA_PANEL = '#261914';
  const COCOA_TILE = '#140C0A';
  const COCOA_HINGE = '#3B2821';
  const CREAM = '#FFF3E2';
  const CREAM_MUTED = '#BFA995';
  const COPPER = '#F28C28';
  const COPPER_DEEP = '#A85814';

  const FONT_FAMILY = 'Inter, "Segoe UI", system-ui, -apple-system, sans-serif';
  const FLAP_ALPHA = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789%.-';

  function clamp(v, a, b) {
    return v < a ? a : v > b ? b : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(x) {
    const u = clamp(x, 0, 1);
    return 1 - Math.pow(1 - u, 3);
  }

  function easeInOutCubic(x) {
    const u = clamp(x, 0, 1);
    return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rr = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0.5 || h <= 0.5) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = `${weight} ${size}px ${FONT_FAMILY}`;
    const m = ctx.measureText(text).width;
    if (m > maxW && m > 0) {
      size = size * (maxW / m);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    if (drawContent) {
      drawContent(x, y, w, h);
    }
    ctx.restore();
  }

  // Flat 2D Mechanical Split-Flap Tile with Smooth Folding Half-Flaps
  function drawSplitFlapTile(x, y, w, h, charFrom, charTo, progress, steps, isCopperAccent) {
    const tileBg = isCopperAccent ? COPPER : COCOA_TILE;
    const txtColor = isCopperAccent ? COCOA_BG : CREAM;
    const r = Math.max(3, minSide * 0.008);
    const cy = y + h * 0.5;
    const gap = Math.max(1.5, h * 0.028);
    const glyphFs = fitFontSize('W', w * 0.72, h * 0.64, h * 0.62, 900);

    function drawTileHalf(ch, isTop, scaleY, shadeAlpha) {
      const halfY = isTop ? y : cy + gap * 0.5;
      const halfH = h * 0.5 - gap * 0.5;
      if (halfH <= 0.5 || scaleY <= 0.01) return;

      ctx.save();
      ctx.beginPath();
      roundRectPath(x, y, w, h, r);
      ctx.clip();

      ctx.translate(x + w * 0.5, cy);
      ctx.scale(1, scaleY);
      ctx.translate(-(x + w * 0.5), -cy);

      ctx.beginPath();
      if (isTop) {
        ctx.rect(x, y, w, h * 0.5 - gap * 0.5);
      } else {
        ctx.rect(x, cy + gap * 0.5, w, h * 0.5 - gap * 0.5);
      }
      ctx.clip();

      ctx.fillStyle = tileBg;
      ctx.fillRect(x, y, w, h);

      if (ch && ch !== ' ') {
        ctx.font = `900 ${glyphFs}px ${FONT_FAMILY}`;
        ctx.fillStyle = txtColor;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(ch, x + w * 0.5, cy + glyphFs * 0.03);
      }

      if (shadeAlpha > 0.01) {
        ctx.fillStyle = COCOA_BG;
        ctx.globalAlpha *= shadeAlpha;
        ctx.fillRect(x, y, w, h);
      }
      ctx.restore();
    }

    // Tile housing shadow backdrop
    fillRoundRect(x, y, w, h, r, COCOA_BG);

    const u = clamp(progress, 0, 1);
    const flipSteps = Math.max(1, steps);

    if (charFrom === charTo || u <= 0.001) {
      drawTileHalf(charFrom, true, 1, 0);
      drawTileHalf(charFrom, false, 1, 0);
    } else if (u >= 0.999) {
      drawTileHalf(charTo, true, 1, 0);
      drawTileHalf(charTo, false, 1, 0);
    } else {
      const idx0 = Math.max(0, FLAP_ALPHA.indexOf(charFrom));
      const scaled = u * flipSteps;
      const stepIdx = Math.min(flipSteps - 1, Math.floor(scaled));
      const subU = scaled - stepIdx;

      const curPrev = stepIdx === 0
        ? charFrom
        : FLAP_ALPHA[(idx0 + stepIdx * 3) % FLAP_ALPHA.length];
      const curNext = stepIdx === flipSteps - 1
        ? charTo
        : FLAP_ALPHA[(idx0 + (stepIdx + 1) * 3) % FLAP_ALPHA.length];

      // Stationary underlying halves
      drawTileHalf(curNext, true, 1, 0);
      drawTileHalf(curPrev, false, 1, 0);

      // Moving split flap
      if (subU < 0.5) {
        const foldRatio = clamp(Math.cos(subU * Math.PI), 0, 1);
        drawTileHalf(curPrev, true, foldRatio, (1 - foldRatio) * 0.34);
      } else {
        const openRatio = clamp(Math.abs(Math.cos(subU * Math.PI)), 0, 1);
        drawTileHalf(curNext, false, openRatio, (1 - openRatio) * 0.28);
      }
    }

    // Crisp side hinge pins purely inside tile margins (no outer border stroke)
    const pinW = Math.max(2, w * 0.055);
    const pinH = Math.max(3, h * 0.11);
    const pinCol = isCopperAccent ? COPPER_DEEP : COCOA_HINGE;
    fillRoundRect(x + w * 0.04, cy - pinH * 0.5, pinW, pinH, pinW * 0.4, pinCol);
    fillRoundRect(x + w - w * 0.04 - pinW, cy - pinH * 0.5, pinW, pinH, pinW * 0.4, pinCol);
  }

  function drawFlipRow(x, y, w, h, strFrom, strTo, baseProgress, staggerRatio, steps, accentFromRanges, accentToRanges) {
    const cols = strTo.length;
    const tileGap = Math.max(4, minSide * 0.011);
    const tileW = (w - tileGap * (cols - 1)) / cols;
    const totalStagger = staggerRatio;
    const tileWin = Math.max(0.2, 1 - totalStagger);

    function inRanges(idx, ranges) {
      if (!ranges) return false;
      for (let r = 0; r < ranges.length; r++) {
        if (idx >= ranges[r][0] && idx < ranges[r][1]) return true;
      }
      return false;
    }

    for (let i = 0; i < cols; i++) {
      const tx = x + i * (tileW + tileGap);
      const d = (i / Math.max(1, cols - 1)) * totalStagger;
      const localU = easeInOutCubic(clamp((baseProgress - d) / tileWin, 0, 1));
      const isCopper = inRanges(i, localU >= 0.5 ? accentToRanges : accentFromRanges);
      drawSplitFlapTile(tx, y, tileW, h, strFrom[i] || ' ', strTo[i] || ' ', localU, steps, isCopper);
    }
  }

  function drawClockDial(cx, cy, radius, angleRad) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fillStyle = COCOA_TILE;
    ctx.fill();

    // Clean interior minute ticks
    for (let k = 0; k < 12; k++) {
      const a = (k / 12) * Math.PI * 2;
      const r0 = radius * 0.72;
      const r1 = radius * 0.86;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
      ctx.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
      ctx.strokeStyle = k % 3 === 0 ? COPPER : COCOA_HINGE;
      ctx.lineWidth = Math.max(1.5, radius * 0.09);
      ctx.lineCap = 'round';
      ctx.stroke();
    }

    // Rotating Copper Indicator Hand (1 exact full revolution over 20s)
    const handA = -Math.PI * 0.5 + angleRad;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(handA) * radius * 0.64, cy + Math.sin(handA) * radius * 0.64);
    ctx.strokeStyle = COPPER;
    ctx.lineWidth = Math.max(2, radius * 0.14);
    ctx.lineCap = 'round';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.16, 0, Math.PI * 2);
    ctx.fillStyle = CREAM;
    ctx.fill();
    ctx.restore();
  }

  // 1. Clean Espresso Cocoa Background (Zero Glow, Zero Border Strokes, Zero Corner Frames)
  ctx.fillStyle = COCOA_BG;
  ctx.fillRect(0, 0, width, height);

  // Subtle flat interior matrix dots strictly inside safe bounds
  const safeX = width * 0.05;
  const stageW = width - safeX * 2;
  const topBarY = height * 0.044;
  const topBarH = minSide * 0.052;
  const botBarH = minSide * 0.052;
  const botBarY = height - height * 0.044 - botBarH;
  const stageTop = topBarY + topBarH + height * 0.032;
  const stageBot = botBarY - height * 0.032;
  const stageH = stageBot - stageTop;
  const gap = minSide * 0.024;
  const panelR = minSide * 0.02;

  ctx.fillStyle = '#241713';
  const dotCols = 14;
  const dotRows = 6;
  for (let r = 0; r < dotRows; r++) {
    const dy = lerp(stageTop + minSide * 0.02, stageBot - minSide * 0.02, r / (dotRows - 1));
    for (let c = 0; c < dotCols; c++) {
      const dx = lerp(safeX + minSide * 0.02, safeX + stageW - minSide * 0.02, c / (dotCols - 1));
      ctx.beginPath();
      ctx.arc(dx, dy, minSide * 0.0022, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 2. Top Departure Telemetry Header (Persistent across all 3 scenes, synced seamlessly)
  drawClippedCard(safeX, topBarY, stageW, topBarH, topBarH * 0.36, COCOA_PANEL, (hx, hy, hw, hh) => {
    const pad = minSide * 0.022;
    const dialR = hh * 0.34;
    drawClockDial(hx + pad + dialR, hy + hh * 0.5, dialR, fullPhase * Math.PI * 2);

    const brandStr = 'DEPARTURE DEALS  •  LIVE PROMO BOARD';
    const bSize = fitFontSize(brandStr, hw * 0.42, hh * 0.5, minSide * 0.023, 800);
    ctx.font = `800 ${bSize}px ${FONT_FAMILY}`;
    ctx.fillStyle = CREAM;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(brandStr, hx + pad + dialR * 2 + pad * 0.85, hy + hh * 0.52);

    // Copper Category Badge on Right
    const catW = hw * 0.16;
    const catH = hh * 0.64;
    const catX = hx + hw - pad - catW;
    const catY = hy + (hh - catH) * 0.5;
    fillRoundRect(catX, catY, catW, catH, catH * 0.5, COPPER);
    const cSize = fitFontSize('24H ONLY', catW * 0.82, catH * 0.56, minSide * 0.021, 900);
    ctx.font = `900 ${cSize}px ${FONT_FAMILY}`;
    ctx.fillStyle = COCOA_BG;
    ctx.textAlign = 'center';
    ctx.fillText('24H ONLY', catX + catW * 0.5, catY + catH * 0.52);

    // 3-Step Departure Gate Status Dots next to badge
    const gates = 3;
    const gGap = minSide * 0.012;
    const dotS = hh * 0.22;
    const gateRight = catX - pad * 1.1;
    // Active gate highlight moves cleanly to gate 0 -> 1 -> 2, and resets neatly in Scene 2 tail
    const activeGate = currentScene === 2 && p > 0.72 ? 0 : currentScene;
    for (let g = 0; g < gates; g++) {
      const gx = gateRight - (gates - 1 - g) * (dotS + gGap) - dotS * 0.5;
      ctx.beginPath();
      ctx.arc(gx, hy + hh * 0.5, dotS * 0.5, 0, Math.PI * 2);
      ctx.fillStyle = g === activeGate ? COPPER : COCOA_HINGE;
      ctx.fill();
    }
  });

  // 3. Bottom Worldwide Continuous Ticker Bar (Exact 3 integer cycles over 20s)
  drawClippedCard(safeX, botBarY, stageW, botBarH, botBarH * 0.36, COCOA_PANEL, (bx, by, bw, bh) => {
    const pad = minSide * 0.022;
    const pillW = bw * 0.17;
    const pillH = bh * 0.64;
    fillRoundRect(bx + pad, by + (bh - pillH) * 0.5, pillW, pillH, pillH * 0.5, COCOA_TILE);
    const pFs = fitFontSize('WORLDWIDE', pillW * 0.82, pillH * 0.56, minSide * 0.02, 900);
    ctx.font = `900 ${pFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = COPPER;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WORLDWIDE', bx + pad + pillW * 0.5, by + bh * 0.52);

    const clipX = bx + pad * 2 + pillW;
    const clipW = bw - (pad * 3 + pillW);
    const tickerFs = fitFontSize('M', clipW, bh * 0.44, minSide * 0.022, 800);
    ctx.font = `800 ${tickerFs}px ${FONT_FAMILY}`;
    const tickerStr = 'WORLDWIDE  •  ALL ORDERS  •  WEEKEND SALE  •  FREE SHIPPING  •  40% OFF NOW  •  ';
    const segW = ctx.measureText(tickerStr).width;
    const travel = (fullPhase * 3 * segW) % segW;

    ctx.save();
    ctx.beginPath();
    ctx.rect(clipX, by, clipW, bh);
    ctx.clip();

    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = CREAM_MUTED;
    let curX = clipX - travel;
    while (curX < clipX + clipW + segW) {
      ctx.fillText(tickerStr, curX, by + bh * 0.52);
      curX += segW;
    }
    ctx.restore();
  });

  // 4. Main Center Mechanical Departure Board Assembly (Continuous Non-Overlapping Rows)
  const mainBoardH = stageH * 0.56;
  const subRowH = stageH - mainBoardH - gap;
  const mainBoardY = stageTop;
  const subRowY = mainBoardY + mainBoardH + gap;

  // Determine exact seamless character transitions across all 3 scenes
  // Opening / Closing loop state at t=0 and t=20: Main='  24H DEALS  ' (13 chars), Sub=' 24H ONLY ' (10 chars)
  const INIT_MAIN = '  24H DEALS  ';
  const INIT_SUB = ' 24H ONLY ';

  let mainFrom = INIT_MAIN;
  let mainTo = INIT_MAIN;
  let mainProg = 0;
  let mainSteps = 2;
  let mainAccentFrom = [[2, 5]];
  let mainAccentTo = [[2, 5]];

  let subFrom = INIT_SUB;
  let subTo = INIT_SUB;
  let subProg = 0;
  let subAccentFrom = [[1, 4]];
  let subAccentTo = [[1, 4]];

  let sceneTag = 'GATE 01  •  WEEKEND PROMO';
  let statusMetric = 'WEEKEND DROP ACTIVE';
  const sceneMetaAlpha = easeOutCubic(clamp(p / 0.08, 0, 1)) * (1 - easeInOutCubic(clamp((p - 0.91) / 0.08, 0, 1)));
  const cycleBar = easeOutCubic(clamp((p - 0.05) / 0.56, 0, 1)) * (1 - easeInOutCubic(clamp((p - 0.80) / 0.17, 0, 1)));
  let barProg = cycleBar;

  if (currentScene === 0) {
    // SCENE 0 (0 - 6.67s): Flip cascade into "WEEKEND  SALE" + "UP TO 40% "
    mainFrom = INIT_MAIN;
    mainTo = 'WEEKEND  SALE';
    mainProg = clamp((p - 0.05) / 0.42, 0, 1);
    mainSteps = 2;
    mainAccentFrom = [[2, 5]];
    mainAccentTo = [[9, 13]];

    subFrom = INIT_SUB;
    subTo = 'UP TO 40% ';
    subProg = clamp((p - 0.14) / 0.40, 0, 1);
    subAccentFrom = [[1, 4]];
    subAccentTo = [[6, 9]];

    sceneTag = 'GATE 01  •  WEEKEND PROMO';
    statusMetric = 'WEEKEND DROP ACTIVE';
  } else if (currentScene === 1) {
    // SCENE 1 (6.67 - 13.33s): Main row flips into "FREE SHIPPING", sub flips into "ALL ORDERS"
    mainFrom = 'WEEKEND  SALE';
    mainTo = 'FREE SHIPPING';
    mainProg = clamp((p - 0.06) / 0.42, 0, 1);
    mainSteps = 2;
    mainAccentFrom = [[9, 13]];
    mainAccentTo = [[0, 4]];

    subFrom = 'UP TO 40% ';
    subTo = 'ALL ORDERS';
    subProg = clamp((p - 0.14) / 0.40, 0, 1);
    subAccentFrom = [[6, 9]];
    subAccentTo = [[0, 3]];

    sceneTag = 'GATE 02  •  WORLDWIDE DISPATCH';
    statusMetric = 'ZERO SHIPPING FEE';
  } else {
    // SCENE 2 (13.33 - 20s): Fast flip to " 40% OFF NOW ", then clean reverse cascade back to INIT by p=0.96
    sceneTag = 'GATE 03  •  FINAL BOARDING';
    statusMetric = 'APPLY AUTOMATICALLY';

    if (p < 0.70) {
      mainFrom = 'FREE SHIPPING';
      mainTo = ' 40% OFF NOW ';
      mainProg = clamp((p - 0.05) / 0.36, 0, 1);
      mainSteps = 3;
      mainAccentFrom = [[0, 4]];
      mainAccentTo = [[1, 4], [9, 12]];

      subFrom = 'ALL ORDERS';
      subTo = 'BOOK NOW  ';
      subProg = clamp((p - 0.12) / 0.34, 0, 1);
      subAccentFrom = [[0, 3]];
      subAccentTo = [[5, 8]];
      barProg = easeOutCubic(clamp((p - 0.05) / 0.48, 0, 1)) * (1 - easeInOutCubic(clamp((p - 0.56) / 0.13, 0, 1)));
    } else {
      mainFrom = ' 40% OFF NOW ';
      mainTo = INIT_MAIN;
      mainProg = clamp((p - 0.70) / 0.26, 0, 1);
      mainSteps = 2;
      mainAccentFrom = [[1, 4], [9, 12]];
      mainAccentTo = [[2, 5]];

      subFrom = 'BOOK NOW  ';
      subTo = INIT_SUB;
      subProg = clamp((p - 0.70) / 0.26, 0, 1);
      subAccentFrom = [[5, 8]];
      subAccentTo = [[1, 4]];
      barProg = 0;
    }
  }

  // Primary Split-Flap Main Board Panel
  drawClippedCard(safeX, mainBoardY, stageW, mainBoardH, panelR, COCOA_PANEL, (bx, by, bw, bh) => {
    const pad = minSide * 0.03;

    // Top Micro-Label Row inside Main Board (clean crossfade at gate transitions)
    ctx.save();
    ctx.globalAlpha *= sceneMetaAlpha;
    const tagFs = fitFontSize(sceneTag, bw * 0.55, minSide * 0.032, minSide * 0.022, 800);
    ctx.font = `800 ${tagFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = COPPER;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(sceneTag, bx + pad, by + bh * 0.14);

    const metFs = fitFontSize(statusMetric, bw * 0.36, minSide * 0.03, minSide * 0.021, 700);
    ctx.font = `700 ${metFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = CREAM_MUTED;
    ctx.textAlign = 'right';
    ctx.fillText(statusMetric, bx + bw - pad, by + bh * 0.14);
    ctx.restore();

    // 13-Tile Hero Split-Flap Array
    const rowY = by + bh * 0.26;
    const rowH = bh * 0.56;
    drawFlipRow(bx + pad, rowY, bw - pad * 2, rowH, mainFrom, mainTo, mainProg, 0.34, mainSteps, mainAccentFrom, mainAccentTo);

    // Bottom Mechanical Timeline Track inside Main Board
    const trackY = by + bh * 0.895;
    const trackH = Math.max(4, minSide * 0.007);
    const trackW = bw - pad * 2;
    fillRoundRect(bx + pad, trackY, trackW, trackH, trackH * 0.5, COCOA_TILE);
    fillRoundRect(bx + pad, trackY, Math.max(trackH, trackW * barProg), trackH, trackH * 0.5, COPPER);
  });

  // Lower Twin Split Panels (Left: 10-Tile Sub-Flip Row, Right: Promo Schedule & Speed Telemetry)
  const leftSubW = stageW * 0.62 - gap * 0.5;
  const rightSubW = stageW - leftSubW - gap;
  const rightSubX = safeX + leftSubW + gap;

  drawClippedCard(safeX, subRowY, leftSubW, subRowH, panelR, COCOA_PANEL, (bx, by, bw, bh) => {
    const pad = minSide * 0.026;
    const lblFs = fitFontSize('CATEGORY DISPATCH', bw * 0.5, minSide * 0.024, minSide * 0.019, 800);
    ctx.font = `800 ${lblFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = CREAM_MUTED;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText('CATEGORY DISPATCH', bx + pad, by + pad * 0.7);

    const tileRowY = by + bh * 0.29;
    const tileRowH = bh * 0.57;
    drawFlipRow(bx + pad, tileRowY, bw - pad * 2, tileRowH, subFrom, subTo, subProg, 0.30, 2, subAccentFrom, subAccentTo);
  });

  drawClippedCard(rightSubX, subRowY, rightSubW, subRowH, panelR, COCOA_PANEL, (bx, by, bw, bh) => {
    const pad = minSide * 0.026;
    const pillH = bh * 0.23;
    const pillW = bw * 0.46;
    fillRoundRect(bx + pad, by + pad * 0.8, pillW, pillH, pillH * 0.5, COCOA_TILE);
    const badgeTxt = 'LIMITED OFFER';
    const bFs = fitFontSize(badgeTxt, pillW * 0.82, pillH * 0.55, minSide * 0.019, 800);
    ctx.font = `800 ${bFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = COPPER;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(badgeTxt, bx + pad + pillW * 0.5, by + pad * 0.8 + pillH * 0.52);

    const descTxt = currentScene === 0 ? '40% MAX SAVINGS' : currentScene === 1 ? 'GLOBAL EXPRESS' : 'OFFER ENDING SOON';
    ctx.save();
    ctx.globalAlpha *= sceneMetaAlpha;
    const dFs = fitFontSize(descTxt, bw - pad * 2, bh * 0.24, minSide * 0.034, 900);
    ctx.font = `900 ${dFs}px ${FONT_FAMILY}`;
    ctx.fillStyle = CREAM;
    ctx.textAlign = 'left';
    ctx.fillText(descTxt, bx + pad, by + bh * 0.56);
    ctx.restore();

    // Clean Multi-Segment Copper Schedule Gauge
    const segCount = 6;
    const segGap = minSide * 0.01;
    const segW = (bw - pad * 2 - segGap * (segCount - 1)) / segCount;
    const segH = Math.max(5, bh * 0.09);
    const segY = by + bh * 0.78;
    const activeCount = Math.ceil(clamp(barProg, 0, 1) * segCount);
    for (let s = 0; s < segCount; s++) {
      const sx = bx + pad + s * (segW + segGap);
      fillRoundRect(sx, segY, segW, segH, segH * 0.5, s < activeCount ? COPPER : COCOA_TILE);
    }
  });
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const fullPhase = loopT / duration;
  const p = sceneProgress;

  // Color Palette — Void Charcoal, Neon Magenta, Laser Violet, Crisp Foreground Cyan Split
  const VOID_BG = '#09090E';
  const SURFACE_DARK = '#12121D';
  const SURFACE_MID = '#161526';
  const SURFACE_ELEV = '#1D1B30';
  const MAGENTA = '#FF1EC8';
  const VIOLET = '#7B42FF';
  const CYAN_SPLIT = '#18E8FF';
  const WHITE = '#F7F5FF';
  const MUTED = '#9C94BD';
  const RULE_DARK = '#25233D';

  const FONT_FAMILY = 'Inter, "Segoe UI", system-ui, -apple-system, sans-serif';

  function clamp(v, a, b) {
    return v < a ? a : v > b ? b : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(x) {
    const u = clamp(x, 0, 1);
    return 1 - Math.pow(1 - u, 3);
  }

  function easeInCubic(x) {
    const u = clamp(x, 0, 1);
    return u * u * u;
  }

  function easeOutQuint(x) {
    const u = clamp(x, 0, 1);
    return 1 - Math.pow(1 - u, 5);
  }

  function easeInOutQuart(x) {
    const u = clamp(x, 0, 1);
    return u < 0.5 ? 8 * u * u * u * u : 1 - Math.pow(-2 * u + 2, 4) / 2;
  }

  function bandBell(u, center, halfWidth) {
    const d = Math.abs(u - center) / Math.max(0.0001, halfWidth);
    if (d >= 1) return 0;
    return Math.pow(0.5 * (1 + Math.cos(Math.PI * d)), 1.5);
  }

  function roundRectPath(x, y, w, h, r) {
    const rr = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function parallelogramPath(x, y, w, h, skew) {
    ctx.beginPath();
    ctx.moveTo(x + skew, y);
    ctx.lineTo(x + w + skew, y);
    ctx.lineTo(x + w - skew, y + h);
    ctx.lineTo(x - skew, y + h);
    ctx.closePath();
  }

  function fitFontSize(text, maxW, targetSize, weight) {
    let size = targetSize;
    ctx.font = `${weight} ${size}px ${FONT_FAMILY}`;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = Math.floor(size * (maxW / measured));
    }
    return Math.max(10, size);
  }

  function drawClippedCard(x, y, w, h, r, bg, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bg;
    ctx.fill();
    ctx.clip();
    const contentAlpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (drawContent && contentAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha *= contentAlpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawPillBadge(cx, cy, h, label, bg, fg, maxW) {
    const padX = h * 0.55;
    const baseSize = h * 0.44;
    const fSize = fitFontSize(label, Math.max(20, (maxW || width) - padX * 2), baseSize, 700);
    ctx.font = `700 ${fSize}px ${FONT_FAMILY}`;
    const tw = ctx.measureText(label).width;
    const pw = Math.min(maxW || width, tw + padX * 2);
    roundRectPath(cx - pw * 0.5, cy - h * 0.5, pw, h, h * 0.5);
    ctx.fillStyle = bg;
    ctx.fill();
    ctx.fillStyle = fg;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, cx, cy + fSize * 0.03);
  }

  function drawPillBadgeLeft(x, cy, h, label, bg, fg, maxW) {
    const padX = h * 0.52;
    const baseSize = h * 0.44;
    const fSize = fitFontSize(label, Math.max(20, (maxW || width) - padX * 2), baseSize, 700);
    ctx.font = `700 ${fSize}px ${FONT_FAMILY}`;
    const tw = ctx.measureText(label).width;
    const pw = Math.min(maxW || width, tw + padX * 2);
    roundRectPath(x, cy - h * 0.5, pw, h, h * 0.5);
    ctx.fillStyle = bg;
    ctx.fill();
    ctx.fillStyle = fg;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, x + pw * 0.5, cy + fSize * 0.03);
    return pw;
  }

  function drawSlicedWord(text, cx, cy, targetFontSize, weight, baseColor, maxWidth, opts) {
    const o = opts || {};
    const bands = o.bands || 10;
    const settleU = o.settleU === undefined ? 1 : clamp(o.settleU, 0, 1);
    const maxSlide = o.maxSlide === undefined ? minSide * 0.14 : o.maxSlide;
    const splitPx = o.splitPx || 0;
    const bandStagger = o.bandStagger === undefined ? 0.035 : o.bandStagger;
    const align = o.align || 'center';
    const splitLeftColor = o.splitLeftColor || CYAN_SPLIT;
    const splitRightColor = o.splitRightColor || MAGENTA;
    const exiting = !!o.exiting;

    const fSize = fitFontSize(text, maxWidth, targetFontSize, weight);
    ctx.font = `${weight} ${fSize}px ${FONT_FAMILY}`;
    ctx.textAlign = align;
    ctx.textBaseline = 'middle';
    const textW = ctx.measureText(text).width;

    // Fast crisp single pass when fully locked and chromatic split is settled
    if (settleU >= 0.998 && Math.abs(splitPx) <= 0.15 && !exiting) {
      ctx.fillStyle = baseColor;
      ctx.fillText(text, cx, cy);
      return { fontSize: fSize, width: textW };
    }

    const boxH = fSize * 1.24;
    const topY = cy - boxH * 0.5;
    const spanW = textW + maxSlide * 2.4 + Math.abs(splitPx) * 2.4 + fSize * 0.4;
    const clipX = align === 'left'
      ? cx - maxSlide * 1.2 - Math.abs(splitPx) * 1.2 - fSize * 0.1
      : align === 'right'
        ? cx - textW - maxSlide * 1.2 - Math.abs(splitPx) * 1.2 - fSize * 0.1
        : cx - spanW * 0.5;

    const totalStagger = (bands - 1) * bandStagger;
    const bandWindow = Math.max(0.25, 1 - totalStagger);
    const bandStates = [];

    for (let i = 0; i < bands; i++) {
      const y0 = Math.round(topY + (boxH * i) / bands);
      const y1 = Math.round(topY + (boxH * (i + 1)) / bands);
      const bandH = y1 - y0;
      if (bandH <= 0) continue;
      const dir = i % 2 === 0 ? 1 : -1;

      const localU = clamp((settleU - i * bandStagger) / bandWindow, 0, 1);
      let dx;
      let bandAlpha = 1;
      if (!exiting) {
        const eased = easeOutQuint(localU);
        dx = dir * maxSlide * (1 - eased);
        bandAlpha = clamp(localU / 0.16, 0, 1);
      } else {
        const eased = easeInCubic(localU);
        dx = -dir * maxSlide * eased;
        bandAlpha = clamp(1 - Math.max(0, localU - 0.55) / 0.45, 0, 1);
      }
      if (bandAlpha <= 0.01) continue;

      const phaseSign = (i % 3 === 0 ? 1 : -1);
      const bandSplit = splitPx * phaseSign * (0.65 + 0.35 * ((i % 2 === 0) ? 1 : -1));
      bandStates.push({ y0, bandH, dx, bandAlpha, bandSplit });
    }

    // Pass 1: Crisp Chromatic Split Layers inside exact integer band rects
    for (let i = 0; i < bandStates.length; i++) {
      const b = bandStates[i];
      if (Math.abs(b.bandSplit) <= 0.25) continue;
      ctx.save();
      ctx.globalAlpha *= b.bandAlpha * 0.78;
      ctx.beginPath();
      ctx.rect(clipX, b.y0, spanW, b.bandH);
      ctx.clip();
      ctx.fillStyle = splitLeftColor;
      ctx.fillText(text, cx + b.dx - Math.abs(b.bandSplit), cy);
      ctx.fillStyle = splitRightColor;
      ctx.fillText(text, cx + b.dx + Math.abs(b.bandSplit), cy);
      ctx.restore();
    }

    // Pass 2: Razor-Sharp Foreground Text Slices On Top (Zero tint overlap across seams)
    for (let i = 0; i < bandStates.length; i++) {
      const b = bandStates[i];
      ctx.save();
      ctx.globalAlpha *= b.bandAlpha;
      ctx.beginPath();
      ctx.rect(clipX, b.y0, spanW, b.bandH);
      ctx.clip();
      ctx.fillStyle = baseColor;
      ctx.fillText(text, cx + b.dx, cy);
      ctx.restore();
    }

    return { fontSize: fSize, width: textW };
  }

  function drawCleanSpectrumTrack(x, y, w, h, barCount, phaseRad, fillRatio, colorA, colorB) {
    const gapRatio = 0.38;
    const step = w / (barCount - gapRatio);
    const barW = Math.max(2, step * (1 - gapRatio));
    const maxBarH = Math.max(4, h * 0.92);
    const baseY = y + h * 0.96;

    for (let i = 0; i < barCount; i++) {
      const norm = i / Math.max(1, barCount - 1);
      const wave1 = 0.5 + 0.5 * Math.sin(phaseRad * 2 + i * 0.55);
      const wave2 = 0.5 + 0.5 * Math.cos(phaseRad * 4 - i * 0.92);
      const env = 0.28 + 0.72 * (0.62 * wave1 + 0.38 * wave2);
      const rawH = Math.max(barW, maxBarH * env * clamp(fillRatio, 0, 1));
      const bx = x + i * step;
      const by = baseY - rawH;

      ctx.fillStyle = i % 3 === 0 ? colorA : i % 2 === 0 ? colorB : WHITE;
      ctx.globalAlpha = i % 5 === 0 ? 0.95 : 0.78;
      roundRectPath(bx, by, barW, rawH, barW * 0.5);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawArrowIcon(cx, cy, size, color) {
    const s = size * 0.5;
    ctx.beginPath();
    ctx.moveTo(cx - s * 0.9, cy);
    ctx.lineTo(cx + s * 0.55, cy);
    ctx.moveTo(cx + s * 0.1, cy - s * 0.52);
    ctx.lineTo(cx + s * 0.65, cy);
    ctx.lineTo(cx + s * 0.1, cy + s * 0.52);
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(2, size * 0.14);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
  }

  // 1. Clean Void Charcoal Background (NO glow, NO corner frames, NO outer strokes)
  ctx.fillStyle = VOID_BG;
  ctx.fillRect(0, 0, width, height);

  // Crisp subtle interior architectural grid + seamless traveling horizontal signal ticks
  const safeX = width * 0.05;
  const safeW = width - safeX * 2;
  const topBarH = minSide * 0.044;
  const botBarH = minSide * 0.044;
  const topBarY = height * 0.04;
  const botBarY = height - height * 0.04 - botBarH;
  const stageTop = topBarY + topBarH + height * 0.032;
  const stageBot = botBarY - height * 0.032;
  const stageH = stageBot - stageTop;
  const stageW = safeW;
  const gap = minSide * 0.024;
  const cardR = minSide * 0.018;

  // Interior subtle structural columns (strictly inside stage area, low contrast flat lines)
  ctx.save();
  ctx.strokeStyle = '#141422';
  ctx.lineWidth = Math.max(1, minSide * 0.0012);
  const cols = 12;
  const rows = 6;
  for (let c = 1; c < cols; c++) {
    const gx = safeX + (stageW * c) / cols;
    ctx.beginPath();
    ctx.moveTo(gx, stageTop);
    ctx.lineTo(gx, stageBot);
    ctx.stroke();
  }
  for (let r = 1; r < rows; r++) {
    const gy = stageTop + (stageH * r) / rows;
    ctx.beginPath();
    ctx.moveTo(safeX, gy);
    ctx.lineTo(safeX + stageW, gy);
    ctx.stroke();
  }
  ctx.restore();

  // Persistent Top & Bottom Inset Marquee Ticker Bars (seamless over 20s)
  function drawMarqueeBar(barY, barH, reverse, labelStr, pillBg) {
    drawClippedCard(safeX, barY, stageW, barH, barH * 0.34, SURFACE_DARK, (bx, by, bw, bh) => {
      const fSize = clamp(bh * 0.44, 11, bh * 0.5);
      ctx.font = `700 ${fSize}px ${FONT_FAMILY}`;
      ctx.textBaseline = 'middle';
      ctx.textAlign = 'left';

      const segW = ctx.measureText(labelStr).width;
      const offset = (fullPhase * 4 * segW) % segW;
      const startX = reverse ? bx + offset - segW : bx - offset;

      // Clean accent pill cap on left inside bar + generous clip inset clearance
      const capW = bh * 0.22;
      ctx.fillStyle = pillBg;
      ctx.fillRect(bx, by, capW, bh);

      const padLeft = bh * 0.65;
      ctx.save();
      ctx.beginPath();
      ctx.rect(bx + padLeft, by, bw - padLeft * 1.4, bh);
      ctx.clip();

      const midY = by + bh * 0.52;
      let cursor = startX;
      while (cursor < bx + bw + segW) {
        ctx.fillStyle = MUTED;
        ctx.fillText(labelStr, cursor, midY);
        cursor += segW;
      }
      ctx.restore();
    });
  }

  drawMarqueeBar(topBarY, topBarH, false, 'MIDNIGHT DROP  •  UP TO 90% OFF  •  LIMITED ACCESS  •  FLASH EVENT  •  ', MAGENTA);
  drawMarqueeBar(botBarY, botBarH, true, 'DO NOT MISS  •  TONIGHT ONLY  •  EXCLUSIVE DEAL  •  CHECKOUT OPEN  •  ', VIOLET);

  // Scene-level enter / exit envelope helper (complete cleanly by p = 0.97)
  function sceneCardEnvelope(enterDelay, exitDelay) {
    const inU = easeOutCubic(clamp((p - enterDelay) / 0.17, 0, 1));
    const outU = easeInCubic(clamp((p - (0.80 - exitDelay)) / 0.17, 0, 1));
    return clamp(inU * (1 - outU), 0, 1);
  }

  function innerFade(env) {
    return easeOutCubic(clamp((env - 0.35) / 0.45, 0, 1));
  }

  // ============================================================================
  // SCENE 0 (0s - 5s): "MIDNIGHT" Slice Lock-In & Signal Rail Launch
  // ============================================================================
  if (currentScene === 0) {
    const headH = stageH * 0.14;
    const heroH = stageH * 0.56;
    const botH = stageH - headH - heroH - gap * 2;

    const headY = stageTop;
    const heroY = headY + headH + gap;
    const botY = heroY + heroH + gap;

    // 1. Header Strip
    const env0 = sceneCardEnvelope(0.0, 0.04);
    const hw = stageW * env0;
    const hx = safeX + (stageW - hw) * 0.5;
    drawClippedCard(hx, headY, hw, headH, cardR, SURFACE_DARK, (cx, cy, cw, ch) => {
      const innerPad = minSide * 0.025;
      drawPillBadgeLeft(safeX + innerPad, cy + ch * 0.5, ch * 0.56, '01  •  MIDNIGHT EVENT', VIOLET, WHITE, stageW * 0.36);

      // Right step progress indicator & status text
      const indW = stageW * 0.24;
      const indX = safeX + stageW - innerPad - indW;
      const barH = ch * 0.16;
      const segs = 4;
      const sGap = indW * 0.035;
      const segW = (indW - sGap * (segs - 1)) / segs;
      const fillProg = easeOutCubic(clamp((p - 0.1) / 0.72, 0, 1));
      for (let i = 0; i < segs; i++) {
        const sx = indX + i * (segW + sGap);
        const sy = cy + ch * 0.5 - barH * 0.5;
        roundRectPath(sx, sy, segW, barH, barH * 0.5);
        const thresh = i / segs;
        ctx.fillStyle = fillProg > thresh ? MAGENTA : RULE_DARK;
        ctx.fill();
      }

      const statSize = fitFontSize('LIVE SIGNAL', stageW * 0.2, ch * 0.34, 700);
      ctx.font = `700 ${statSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = CYAN_SPLIT;
      ctx.fillText('LIVE SIGNAL', indX - innerPad, cy + ch * 0.52);
    });

    // 2. Hero Card: "MIDNIGHT" 10-band Slice Lock-In + Clean Horizontal Scan Rail
    const envHero = sceneCardEnvelope(0.04, 0.02);
    const heroCurtainH = heroH * envHero;
    const heroDrawY = heroY + (heroH - heroCurtainH) * 0.5;
    drawClippedCard(safeX, heroDrawY, stageW, heroCurtainH, cardR, SURFACE_MID, (cx, cy, cw, ch) => {
      // Deterministic sleek scan rail sweep (once cleanly across hold phase)
      const railU = easeInOutQuart(clamp((p - 0.15) / 0.55, 0, 1));
      if (railU > 0.01 && railU < 0.99) {
        const railY = heroY + heroH * railU;
        ctx.fillStyle = VIOLET;
        ctx.globalAlpha = 0.28 * Math.sin(Math.PI * railU);
        ctx.fillRect(cx, railY - minSide * 0.004, cw, minSide * 0.008);
        ctx.fillStyle = MAGENTA;
        ctx.globalAlpha = 0.7 * Math.sin(Math.PI * railU);
        ctx.fillRect(cx, railY - 1, cw, 2);
        ctx.globalAlpha = 1;
      }

      // Subtle architectural top accent bar inside hero card
      const accentW = cw * 0.16;
      roundRectPath(cx + (cw - accentW) * 0.5, heroY + heroH * 0.11, accentW, minSide * 0.006, minSide * 0.003);
      ctx.fillStyle = MAGENTA;
      ctx.fill();

      // Determine slice settle / chromatic micro-split / exit slice
      const inSliceU = clamp((p - 0.04) / 0.32, 0, 1);
      const outSliceU = clamp((p - 0.76) / 0.18, 0, 1);
      const isExitSlice = p > 0.76;
      const splitPulse1 = bandBell(p, 0.49, 0.06);
      const splitPulse2 = bandBell(p, 0.66, 0.055);
      const splitPx = (splitPulse1 + splitPulse2 * 0.85) * minSide * 0.011;

      drawSlicedWord(
        'MIDNIGHT',
        cx + cw * 0.5,
        heroY + heroH * 0.48,
        minSide * 0.17,
        900,
        WHITE,
        cw * 0.78,
        {
          bands: 10,
          settleU: isExitSlice ? outSliceU : inSliceU,
          exiting: isExitSlice,
          maxSlide: cw * 0.12,
          splitPx: splitPx,
          bandStagger: 0.032,
        }
      );

      // Crisp clean subtitle below hero text
      const subAlpha = easeOutCubic(clamp((p - 0.26) / 0.16, 0, 1)) * (1 - easeInCubic(clamp((p - 0.74) / 0.14, 0, 1)));
      if (subAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= subAlpha;
        const subText = 'EXCLUSIVE NIGHT DROP  •  FLASH ACCESS';
        const subSize = fitFontSize(subText, cw * 0.76, minSide * 0.031, 700);
        ctx.font = `700 ${subSize}px ${FONT_FAMILY}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = MAGENTA;
        ctx.fillText(subText, cx + cw * 0.5, heroY + heroH * 0.79);
        ctx.restore();
      }
    });

    // 3. Bottom Twin Cards
    const envBot = sceneCardEnvelope(0.08, 0.0);
    const leftW = stageW * 0.57 - gap * 0.5;
    const rightW = stageW * 0.43 - gap * 0.5;
    const rightX = safeX + leftW + gap;

    // Left Card: Active Equalizer Spectrum Track
    const lwNow = leftW * envBot;
    drawClippedCard(safeX, botY, lwNow, botH, cardR, SURFACE_DARK, () => {
      const pad = minSide * 0.026;
      const lblSize = fitFontSize('SPECTRUM ACTIVITY', leftW * 0.5, minSide * 0.023, 700);
      ctx.font = `700 ${lblSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillStyle = MUTED;
      ctx.fillText('SPECTRUM ACTIVITY', safeX + pad, botY + pad * 0.78);

      const barGain = easeOutCubic(clamp((p - 0.12) / 0.25, 0, 1));
      drawCleanSpectrumTrack(
        safeX + pad,
        botY + botH * 0.36,
        leftW - pad * 2,
        botH * 0.54,
        20,
        p * Math.PI * 2,
        barGain,
        MAGENTA,
        VIOLET
      );
    }, innerFade(envBot));

    // Right Card: Vertical Drop Reveal + Progress Bar
    const rwNow = rightW * envBot;
    drawClippedCard(rightX + (rightW - rwNow), botY, rwNow, botH, cardR, SURFACE_ELEV, () => {
      const pad = minSide * 0.026;
      drawPillBadgeLeft(rightX + pad, botY + botH * 0.27, botH * 0.24, 'NEXT PHASE READY', MAGENTA, VOID_BG, rightW - pad * 2);

      const revealU = easeOutCubic(clamp((p - 0.20) / 0.35, 0, 1));
      const headline = '90% OFF UNLOCK';
      const hSize = fitFontSize(headline, rightW - pad * 2, minSide * 0.044, 800);
      ctx.font = `800 ${hSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = WHITE;
      ctx.fillText(headline, rightX + pad, botY + botH * 0.58);

      // Solid progress track
      const trkY = botY + botH * 0.79;
      const trkH = Math.max(4, botH * 0.09);
      const trkW = rightW - pad * 2;
      roundRectPath(rightX + pad, trkY, trkW, trkH, trkH * 0.5);
      ctx.fillStyle = RULE_DARK;
      ctx.fill();
      roundRectPath(rightX + pad, trkY, Math.max(trkH, trkW * revealU), trkH, trkH * 0.5);
      ctx.fillStyle = VIOLET;
      ctx.fill();
    }, innerFade(envBot));
  }

  // ============================================================================
  // SCENE 1 (5s - 10s): "DEAL" -> "90% OFF" Controlled Chromatic Split + 24-Bar Track
  // ============================================================================
  else if (currentScene === 1) {
    const leftW = stageW * 0.61 - gap * 0.5;
    const rightW = stageW * 0.39 - gap * 0.5;
    const rightX = safeX + leftW + gap;
    const trH = stageH * 0.43 - gap * 0.5;
    const brH = stageH - trH - gap;
    const brY = stageTop + trH + gap;

    // 1. Primary Left Hero Card ("DEAL" morphing cleanly to "90% OFF")
    const envL = sceneCardEnvelope(0.0, 0.02);
    const lhNow = stageH * envL;
    const lyNow = stageTop + (stageH - lhNow) * 0.5;
    drawClippedCard(safeX, lyNow, leftW, lhNow, cardR, SURFACE_DARK, () => {
      const pad = minSide * 0.032;
      const centerX = safeX + leftW * 0.5;

      // Top telemetry row inside card
      drawPillBadgeLeft(safeX + pad, stageTop + stageH * 0.11, minSide * 0.044, '02  •  CHROMATIC FLASH', MAGENTA, VOID_BG, leftW * 0.52);

      const tierTxt = 'MAX DISCOUNT';
      const tierSize = fitFontSize(tierTxt, leftW * 0.32, minSide * 0.024, 700);
      ctx.font = `700 ${tierSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = CYAN_SPLIT;
      ctx.fillText(tierTxt, safeX + leftW - pad, stageTop + stageH * 0.11);

      // Phase A (p = 0.04..0.38): "DEAL"
      if (p < 0.39) {
        const dealIn = clamp((p - 0.04) / 0.17, 0, 1);
        const dealOut = clamp((p - 0.26) / 0.13, 0, 1);
        const isOut = p > 0.26;
        const pulseA = bandBell(p, 0.22, 0.055);
        drawSlicedWord(
          'DEAL',
          centerX,
          stageTop + stageH * 0.49,
          minSide * 0.20,
          900,
          WHITE,
          leftW * 0.80,
          {
            bands: 10,
            settleU: isOut ? dealOut : dealIn,
            exiting: isOut,
            maxSlide: leftW * 0.13,
            splitPx: pulseA * minSide * 0.012,
            bandStagger: 0.025,
          }
        );
      }

      // Phase B (p = 0.38..0.97): "90% OFF"
      if (p >= 0.37) {
        const offIn = clamp((p - 0.38) / 0.14, 0, 1);
        const offOut = clamp((p - 0.78) / 0.17, 0, 1);
        const isOut = p > 0.78;
        const pulseB1 = bandBell(p, 0.58, 0.055);
        const pulseB2 = bandBell(p, 0.71, 0.045);
        drawSlicedWord(
          '90% OFF',
          centerX,
          stageTop + stageH * 0.49,
          minSide * 0.155,
          900,
          WHITE,
          leftW * 0.84,
          {
            bands: 10,
            settleU: isOut ? offOut : offIn,
            exiting: isOut,
            maxSlide: leftW * 0.11,
            splitPx: (pulseB1 + pulseB2 * 0.8) * minSide * 0.012,
            bandStagger: 0.028,
          }
        );
      }

      // Clean Magenta Divider & Persistent Footer Note inside Left Card
      const footAlpha = easeOutCubic(clamp((p - 0.14) / 0.16, 0, 1)) * (1 - easeInCubic(clamp((p - 0.76) / 0.14, 0, 1)));
      if (footAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= footAlpha;
        const ruleW = leftW - pad * 2;
        roundRectPath(safeX + pad, stageTop + stageH * 0.79, ruleW, Math.max(2, minSide * 0.004), 2);
        ctx.fillStyle = VIOLET;
        ctx.fill();

        const footTxt = 'AUTOMATIC AT CHECKOUT  •  NO CODE REQUIRED';
        const fSize = fitFontSize(footTxt, ruleW, minSide * 0.026, 700);
        ctx.font = `700 ${fSize}px ${FONT_FAMILY}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = MUTED;
        ctx.fillText(footTxt, centerX, stageTop + stageH * 0.88);
        ctx.restore();
      }
    });

    // 2. Top-Right Card: Smooth 00% -> 90% Discount Gauge
    const envTR = sceneCardEnvelope(0.06, 0.04);
    const trW = rightW * envTR;
    drawClippedCard(rightX + (rightW - trW), stageTop, trW, trH, cardR, SURFACE_ELEV, () => {
      const pad = minSide * 0.028;
      const lblSize = fitFontSize('RATE DROP', rightW - pad * 2, minSide * 0.024, 700);
      ctx.font = `700 ${lblSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillStyle = MUTED;
      ctx.fillText('RATE DROP', rightX + pad, stageTop + pad * 0.8);

      const countU = easeOutCubic(clamp((p - 0.12) / 0.42, 0, 1));
      const pctVal = Math.round(lerp(0, 90, countU));
      const pctStr = `${pctVal}%`;
      const numSize = fitFontSize(pctStr, rightW - pad * 2, minSide * 0.12, 900);
      ctx.font = `900 ${numSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = MAGENTA;
      ctx.fillText(pctStr, rightX + pad, stageTop + trH * 0.52);

      // Clean Horizontal Gauge
      const barY = stageTop + trH * 0.81;
      const barH = Math.max(5, trH * 0.08);
      const barW = rightW - pad * 2;
      roundRectPath(rightX + pad, barY, barW, barH, barH * 0.5);
      ctx.fillStyle = RULE_DARK;
      ctx.fill();
      roundRectPath(rightX + pad, barY, Math.max(barH, barW * (pctVal / 100)), barH, barH * 0.5);
      ctx.fillStyle = VIOLET;
      ctx.fill();
    });

    // 3. Bottom-Right Card: 24-Bar Active Chromatic Spectrum Track
    const envBR = sceneCardEnvelope(0.11, 0.0);
    const brW = rightW * envBR;
    drawClippedCard(rightX, brY, brW, brH, cardR, SURFACE_MID, () => {
      const pad = minSide * 0.028;
      drawPillBadgeLeft(rightX + pad, brY + brH * 0.18, brH * 0.17, '24-BAND SIGNAL', VIOLET, WHITE, rightW - pad * 2);

      const gainU = easeOutCubic(clamp((p - 0.16) / 0.25, 0, 1));
      drawCleanSpectrumTrack(
        rightX + pad,
        brY + brH * 0.34,
        rightW - pad * 2,
        brH * 0.56,
        24,
        p * Math.PI * 2,
        gainU,
        MAGENTA,
        VIOLET
      );
    });
  }

  // ============================================================================
  // SCENE 2 (10s - 15s): "TONIGHT ONLY • DO NOT MISS" & "LIMITED ACCESS" Cascade
  // ============================================================================
  else if (currentScene === 2) {
    const row0H = (stageH - gap * 2) * 0.31;
    const row1H = (stageH - gap * 2) * 0.38;
    const row2H = stageH - row0H - row1H - gap * 2;
    const row0Y = stageTop;
    const row1Y = row0Y + row0H + gap;
    const row2Y = row1Y + row1H + gap;
    const skew = minSide * 0.022;

    // Row 0: "TONIGHT ONLY" + Time Capsule
    const env0 = sceneCardEnvelope(0.0, 0.05);
    const w0 = stageW * env0;
    drawClippedCard(safeX, row0Y, w0, row0H, cardR, SURFACE_DARK, () => {
      const pad = minSide * 0.032;
      // Clean skewed violet ribbon on left side inside clip
      const ribW = stageW * 0.055;
      parallelogramPath(safeX + pad, row0Y + row0H * 0.22, ribW, row0H * 0.56, skew);
      ctx.fillStyle = VIOLET;
      ctx.fill();

      const sliceIn = clamp((p - 0.05) / 0.26, 0, 1);
      const sliceOut = clamp((p - 0.74) / 0.18, 0, 1);
      const isOut = p > 0.74;
      const split0 = bandBell(p, 0.44, 0.055) * minSide * 0.009;

      drawSlicedWord(
        'TONIGHT ONLY',
        safeX + pad + ribW + pad * 1.1,
        row0Y + row0H * 0.51,
        minSide * 0.088,
        900,
        WHITE,
        stageW * 0.54,
        {
          bands: 8,
          align: 'left',
          settleU: isOut ? sliceOut : sliceIn,
          exiting: isOut,
          maxSlide: stageW * 0.08,
          splitPx: split0,
          bandStagger: 0.03,
        }
      );

      // Clean right pill badge
      drawPillBadge(
        safeX + stageW - pad - stageW * 0.12,
        row0Y + row0H * 0.5,
        row0H * 0.42,
        '03  •  ENDS AT DAWN',
        SURFACE_ELEV,
        CYAN_SPLIT,
        stageW * 0.24
      );
    });

    // Row 1: Neon Magenta Hero Feature Band — "LIMITED ACCESS"
    const env1 = sceneCardEnvelope(0.06, 0.025);
    const w1 = stageW * env1;
    const x1 = safeX + (stageW - w1);
    drawClippedCard(x1, row1Y, w1, row1H, cardR, MAGENTA, () => {
      const pad = minSide * 0.035;
      // Flanking crisp dark skewed vector slashes strictly far from centered text
      const slashW = stageW * 0.045;
      parallelogramPath(safeX + pad, row1Y + row1H * 0.18, slashW, row1H * 0.64, skew);
      ctx.fillStyle = VOID_BG;
      ctx.fill();
      parallelogramPath(safeX + stageW - pad - slashW, row1Y + row1H * 0.18, slashW, row1H * 0.64, -skew);
      ctx.fillStyle = VOID_BG;
      ctx.fill();

      const sliceIn = clamp((p - 0.11) / 0.28, 0, 1);
      const sliceOut = clamp((p - 0.77) / 0.17, 0, 1);
      const isOut = p > 0.77;
      const split1 = (bandBell(p, 0.54, 0.06) + bandBell(p, 0.70, 0.05) * 0.8) * minSide * 0.011;

      drawSlicedWord(
        'LIMITED ACCESS',
        safeX + stageW * 0.5,
        row1Y + row1H * 0.51,
        minSide * 0.112,
        900,
        VOID_BG,
        stageW * 0.72,
        {
          bands: 10,
          settleU: isOut ? sliceOut : sliceIn,
          exiting: isOut,
          maxSlide: stageW * 0.09,
          splitPx: split1,
          splitLeftColor: WHITE,
          splitRightColor: VIOLET,
          bandStagger: 0.028,
        }
      );
    });

    // Row 2: "DO NOT MISS" + Allocation Bars
    const env2 = sceneCardEnvelope(0.12, 0.0);
    const w2 = stageW * env2;
    drawClippedCard(safeX, row2Y, w2, row2H, cardR, SURFACE_ELEV, () => {
      const pad = minSide * 0.032;
      const sliceIn = clamp((p - 0.16) / 0.26, 0, 1);
      const sliceOut = clamp((p - 0.79) / 0.17, 0, 1);
      const isOut = p > 0.79;
      const split2 = bandBell(p, 0.60, 0.055) * minSide * 0.009;

      drawSlicedWord(
        'DO NOT MISS',
        safeX + pad,
        row2Y + row2H * 0.51,
        minSide * 0.088,
        900,
        WHITE,
        stageW * 0.52,
        {
          bands: 8,
          align: 'left',
          settleU: isOut ? sliceOut : sliceIn,
          exiting: isOut,
          maxSlide: stageW * 0.08,
          splitPx: split2,
          bandStagger: 0.03,
        }
      );

      // Right 3-tier stock allocation progress capsule bars
      const meterW = stageW * 0.34;
      const meterX = safeX + stageW - pad - meterW;
      const mBarH = row2H * 0.16;
      const tiers = [
        { label: 'ALLOCATION 01', pct: 1.0, col: VIOLET },
        { label: 'ALLOCATION 02', pct: 0.88, col: MAGENTA },
      ];
      for (let i = 0; i < tiers.length; i++) {
        const ty = row2Y + row2H * (0.26 + i * 0.29);
        const fill = easeOutCubic(clamp((p - (0.2 + i * 0.08)) / 0.35, 0, 1)) * tiers[i].pct;
        roundRectPath(meterX, ty - mBarH * 0.5, meterW, mBarH, mBarH * 0.5);
        ctx.fillStyle = RULE_DARK;
        ctx.fill();
        roundRectPath(meterX, ty - mBarH * 0.5, Math.max(mBarH, meterW * fill), mBarH, mBarH * 0.5);
        ctx.fillStyle = tiers[i].col;
        ctx.fill();
      }

      const statTxt = 'FINAL SLOTS REMAINING';
      const stSize = fitFontSize(statTxt, meterW, minSide * 0.02, 700);
      ctx.font = `700 ${stSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = MUTED;
      ctx.fillText(statTxt, meterX, row2Y + row2H * 0.83);
    }, innerFade(env2));
  }

  // ============================================================================
  // SCENE 3 (15s - 20s): "SHOP NOW" Symmetrical Finale & Laser Anchor Collapse
  // ============================================================================
  else {
    const topH = stageH * 0.14;
    const centerH = stageH * 0.58;
    const botH = stageH - topH - centerH - gap * 2;
    const topY = stageTop;
    const centerY = topY + topH + gap;
    const botY = centerY + centerH + gap;

    // 1. Symmetrical Top Header
    const envTop = sceneCardEnvelope(0.0, 0.04);
    const twNow = stageW * envTop;
    drawClippedCard(safeX + (stageW - twNow) * 0.5, topY, twNow, topH, cardR, SURFACE_DARK, () => {
      const pad = minSide * 0.03;
      const barW = stageW * 0.22;
      const barH = Math.max(3, topH * 0.14);
      roundRectPath(safeX + pad, topY + (topH - barH) * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = VIOLET;
      ctx.fill();
      roundRectPath(safeX + stageW - pad - barW, topY + (topH - barH) * 0.5, barW, barH, barH * 0.5);
      ctx.fillStyle = MAGENTA;
      ctx.fill();

      drawPillBadge(
        safeX + stageW * 0.5,
        topY + topH * 0.5,
        topH * 0.56,
        '04  •  FINAL CALL MIDNIGHT DROP',
        SURFACE_ELEV,
        WHITE,
        stageW * 0.42
      );
    });

    // 2. Center CTA Hero Card with Laser Anchor Collapse (p = 0.78..0.985)
    const inCenter = easeOutCubic(clamp(p / 0.17, 0, 1));
    const collapseV = easeInOutQuart(clamp((p - 0.76) / 0.14, 0, 1));
    const collapseH = easeInCubic(clamp((p - 0.90) / 0.085, 0, 1));
    const curW = stageW * inCenter * (1 - collapseH);
    const minAnchorH = Math.max(3, minSide * 0.005);
    const curH = lerp(centerH * inCenter, minAnchorH, collapseV);
    const curX = safeX + (stageW - curW) * 0.5;
    const curY = centerY + (centerH - curH) * 0.5;
    const midY = centerY + centerH * 0.5;

    if (collapseV < 0.96 && curW > 4 && curH > minSide * 0.04) {
      drawClippedCard(curX, curY, curW, curH, cardR, SURFACE_MID, () => {
        const skew = minSide * 0.025;
        const wingW = stageW * 0.045;
        const pad = minSide * 0.036;
        // Symmetrical left & right chevron wings strictly away from center text
        parallelogramPath(safeX + pad, centerY + centerH * 0.22, wingW, centerH * 0.56, skew);
        ctx.fillStyle = VIOLET;
        ctx.fill();
        parallelogramPath(safeX + stageW - pad - wingW, centerY + centerH * 0.22, wingW, centerH * 0.56, -skew);
        ctx.fillStyle = MAGENTA;
        ctx.fill();

        const sliceIn = clamp((p - 0.06) / 0.26, 0, 1);
        const sliceOut = clamp((p - 0.72) / 0.14, 0, 1);
        const isOut = p > 0.72;
        const splitCta = (bandBell(p, 0.46, 0.055) + bandBell(p, 0.62, 0.05) * 0.75) * minSide * 0.011;

        drawSlicedWord(
          'SHOP NOW',
          safeX + stageW * 0.5,
          centerY + centerH * 0.39,
          minSide * 0.145,
          900,
          WHITE,
          stageW * 0.68,
          {
            bands: 10,
            settleU: isOut ? sliceOut : sliceIn,
            exiting: isOut,
            maxSlide: stageW * 0.10,
            splitPx: splitCta,
            bandStagger: 0.028,
          }
        );

        // Action Pill Button + Arrow Icon below SHOP NOW
        const btnAlpha = easeOutCubic(clamp((p - 0.22) / 0.16, 0, 1)) * (1 - easeInCubic(clamp((p - 0.72) / 0.11, 0, 1)));
        if (btnAlpha > 0.01) {
          ctx.save();
          ctx.globalAlpha *= btnAlpha;
          const btnH = centerH * 0.21;
          const btnW = Math.min(stageW * 0.44, btnH * 4.6);
          const btnX = safeX + (stageW - btnW) * 0.5;
          const btnY = centerY + centerH * 0.73 - btnH * 0.5;
          roundRectPath(btnX, btnY, btnW, btnH, btnH * 0.5);
          ctx.fillStyle = MAGENTA;
          ctx.fill();

          const ctaLabel = 'CLAIM 90% OFF';
          const cSize = fitFontSize(ctaLabel, btnW * 0.68, btnH * 0.46, 800);
          ctx.font = `800 ${cSize}px ${FONT_FAMILY}`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillStyle = VOID_BG;
          ctx.fillText(ctaLabel, safeX + stageW * 0.47, btnY + btnH * 0.52);

          drawArrowIcon(btnX + btnW - btnH * 0.62, btnY + btnH * 0.5, btnH * 0.48, VOID_BG);
          ctx.restore();
        }
      });
    }

    // Sharp Crisp Horizontal Laser Anchor Beam during Finale Collapse (p = 0.76..0.985)
    if (collapseV > 0.05 && collapseH < 0.99 && curW > 2) {
      const beamAlpha = easeOutCubic(clamp((collapseV - 0.1) / 0.4, 0, 1)) * (1 - collapseH);
      ctx.save();
      ctx.globalAlpha *= beamAlpha;
      const beamH = lerp(minSide * 0.014, minAnchorH, collapseV);
      roundRectPath(curX, midY - beamH * 0.5, curW, beamH, beamH * 0.5);
      ctx.fillStyle = MAGENTA;
      ctx.fill();
      ctx.restore();
    }

    // 3. Bottom Dual Symmetrical Metric Cards
    const envBot = sceneCardEnvelope(0.08, 0.06);
    const halfW = (stageW - gap) * 0.5;
    const lwNow = halfW * envBot;
    const rwNow = halfW * envBot;

    drawClippedCard(safeX, botY, lwNow, botH, cardR, SURFACE_ELEV, () => {
      const pad = minSide * 0.026;
      drawPillBadgeLeft(safeX + pad, botY + botH * 0.34, botH * 0.28, '90% OFF ACTIVE', MAGENTA, VOID_BG, halfW - pad * 2);

      const subSize = fitFontSize('APPLIED TO CART AUTOMATICALLY', halfW - pad * 2, minSide * 0.025, 700);
      ctx.font = `700 ${subSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = WHITE;
      ctx.fillText('APPLIED TO CART AUTOMATICALLY', safeX + pad, botY + botH * 0.72);
    }, innerFade(envBot));

    drawClippedCard(safeX + halfW + gap + (halfW - rwNow), botY, rwNow, botH, cardR, SURFACE_DARK, () => {
      const pad = minSide * 0.026;
      const rx = safeX + halfW + gap;
      const lblSize = fitFontSize('LIVE CHECKOUT', halfW * 0.45, minSide * 0.022, 700);
      ctx.font = `700 ${lblSize}px ${FONT_FAMILY}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillStyle = CYAN_SPLIT;
      ctx.fillText('LIVE CHECKOUT', rx + pad, botY + pad * 0.7);

      const gain = easeOutCubic(clamp((p - 0.14) / 0.25, 0, 1));
      drawCleanSpectrumTrack(
        rx + pad,
        botY + botH * 0.36,
        halfW - pad * 2,
        botH * 0.54,
        16,
        p * Math.PI * 2,
        gain,
        VIOLET,
        MAGENTA
      );
    }, innerFade(envBot));
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#161922',
    surface: '#1F2432',
    surfaceMid: '#282F40',
    well: '#10131B',
    mint: '#10E89A',
    ice: '#E6F4F1',
    white: '#FFFFFF',
    muted: '#8D98B2',
    dot: '#222838',
    rule: '#2F374C'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01 || w <= 0.5 || h <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawDownArrow(cx, cy, size, strokeW, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.beginPath();
    ctx.moveTo(0, -size * 0.52);
    ctx.lineTo(0, size * 0.46);
    ctx.moveTo(-size * 0.42, size * 0.08);
    ctx.lineTo(0, size * 0.52);
    ctx.lineTo(size * 0.42, size * 0.08);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  // Precision Single Vertical Odometer Reel Slot (smooth vertical roll, crisp settle on exact integers)
  function drawReelSlot(x, y, w, h, r, reelVal, rollDir, fontSize, weight, wellColor, digitColor) {
    if (w <= 2 || h <= 2) return;
    drawClippedCard(x, y, w, h, r, wellColor, (cx, cy, cw, ch) => {
      const fVal = Math.floor(reelVal);
      const frac = reelVal - fVal;
      const easedFrac = frac <= 0.0005 ? 0 : frac >= 0.9995 ? 1 : frac;
      const d0 = ((fVal % 10) + 10) % 10;
      const d1 = ((fVal + 1) % 10 + 10) % 10;
      const travel = ch * 0.86;
      const centerX = cx + cw * 0.5;
      const centerY = cy + ch * 0.52;

      ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = digitColor;

      if (easedFrac < 0.001) {
        ctx.fillText(String(d0), centerX, centerY);
      } else {
        // rollDir > 0 scrolls numbers upward (increasing counter look); < 0 scrolls downward
        const off0 = -rollDir * easedFrac * travel;
        const off1 = rollDir * (1 - easedFrac) * travel;
        ctx.save();
        ctx.globalAlpha *= 1 - easedFrac * 0.85;
        ctx.fillText(String(d0), centerX, centerY + off0);
        ctx.restore();

        ctx.save();
        ctx.globalAlpha *= 0.15 + easedFrac * 0.85;
        ctx.fillText(String(d1), centerX, centerY + off1);
        ctx.restore();
      }
    });
  }

  // Standardized smooth entrance/exit completing cleanly by p = 0.97
  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.17;
    const exitDur = 0.17;
    const inU = clamp((p - enterDelay) / enterDur, 0, 1);
    const outU = clamp((p - (0.80 - exitDelay)) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Flat Crisp Graphite Slate Background (Strictly ZERO background glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Precision Architectural Fintech Micro-Grid inside Central Stage (Seamless 2-cycle loop)
  const bandH = height * 0.088;
  const loopAngle = 2 * Math.PI * (safeLoopT / duration);
  const gridPhase = loopAngle * 2;
  const cols = 14;
  const rows = 6;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < rows; r++) {
    const dy = lerp(height * 0.16, height - height * 0.16, r / (rows - 1));
    for (let c = 0; c < cols; c++) {
      const dx = lerp(width * 0.08, width * 0.92, c / (cols - 1));
      const pulse = 0.5 + 0.5 * Math.sin(gridPhase + c * 0.4 + r * 0.65);
      const rad = minSide * (0.002 + pulse * 0.0008);
      ctx.beginPath();
      ctx.arc(dx, dy, rad, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 3. Persistent Seamless Top & Bottom Smart-Promo Marquee Ribbons
  function drawMarqueeTrack(y, h, text, speedDir, bgCol, textCol, dotCol) {
    ctx.fillStyle = bgCol;
    ctx.fillRect(0, y, width, h);

    const fontSize = fitFontSize('M', width, h * 0.44, minSide * 0.022, '800');
    ctx.save();
    ctx.font = '800 ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    const parts = text.split('•').map(s => s.trim()).filter(Boolean);
    let unitW = 0;
    const itemWidths = [];
    const padX = fontSize * 1.1;
    for (let i = 0; i < parts.length; i++) {
      const seg = parts[i];
      const sw = ctx.measureText(seg).width;
      itemWidths.push({ seg: seg, w: sw });
      unitW += sw + padX * 2;
    }

    const totalTravel = unitW * Math.max(1, Math.round((width * 1.4) / unitW));
    const travelDist = (safeLoopT / duration) * totalTravel * speedDir;
    let startX = ((travelDist % unitW) - unitW) % unitW;
    if (startX > 0) startX -= unitW;

    let curX = startX;
    let idx = 0;
    const midY = y + h * 0.52;
    while (curX < width + unitW) {
      const item = itemWidths[idx % itemWidths.length];
      ctx.fillStyle = textCol;
      ctx.fillText(item.seg, curX, midY);
      ctx.fillStyle = dotCol;
      ctx.beginPath();
      ctx.arc(curX + item.w + padX, midY - fontSize * 0.03, fontSize * 0.14, 0, Math.PI * 2);
      ctx.fill();
      curX += item.w + padX * 2;
      idx++;
    }
    ctx.restore();
  }

  drawMarqueeTrack(
    0,
    bandH,
    'PRICE DROP   •   UP TO 75% SAVINGS   •   SMART CHECKOUT   •   LIMITED WINDOW   •   ',
    1,
    COLORS.surface,
    COLORS.ice,
    COLORS.mint
  );
  drawMarqueeTrack(
    height - bandH,
    bandH,
    'LIVE DEAL TRACKER   •   24H COUNTDOWN   •   AUTOMATIC DISCOUNT   •   SHOP TODAY   •   ',
    -1,
    COLORS.surface,
    COLORS.mint,
    COLORS.ice
  );

  // Clean Centered Stage Margins
  const stageX = width * 0.065;
  const stageW = width * 0.87;
  const stageY = height * 0.132;
  const stageH = height * 0.736;
  const gutter = minSide * 0.024;
  const cardR = minSide * 0.024;

  const p = sceneProgress;

  if (sceneIdx === 0) {
    // SCENE 0: "PRICE DROP" + Precision Vertical Odometer "00%" -> "75%" + Active Mint Progress Bar
    const metaH = stageH * 0.11;
    const mainY = stageY + stageH * 0.155;
    const mainH = stageH * 0.59;
    const botY = stageY + stageH * 0.79;
    const botH = stageH * 0.21;

    // Row 0: Meta Header
    const mMeta = getCardMotion(p, 0.0, 0.04);
    if (mMeta.vis > 0.01) {
      const leftPillW = stageW * 0.23;
      const rightPillW = stageW * 0.14;
      const slideY = mMeta.slideOffset * minSide * 0.028;

      ctx.save();
      ctx.globalAlpha = mMeta.vis;
      drawClippedCard(stageX, stageY + slideY, leftPillW, metaH, metaH * 0.5, COLORS.mint, (cx, cy, cw, ch) => {
        const fs = fitFontSize('LIVE TRACKER', cw * 0.82, ch * 0.48, minSide * 0.023, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('LIVE TRACKER', cx + cw * 0.5, cy + ch * 0.52);
      });

      const railStart = stageX + leftPillW + gutter * 2;
      const railEnd = stageX + stageW - rightPillW - gutter * 2;
      const railH = minSide * 0.008;
      const railY = stageY + metaH * 0.5 + slideY - railH * 0.5;
      fillRoundRect(railStart, railY, railEnd - railStart, railH, railH * 0.5, COLORS.surfaceMid);
      const fillProg = easeInOutQuart(clamp((p - 0.08) / 0.58, 0, 1));
      fillRoundRect(railStart, railY, (railEnd - railStart) * fillProg, railH, railH * 0.5, COLORS.mint);

      drawClippedCard(stageX + stageW - rightPillW, stageY + slideY, rightPillW, metaH, metaH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('01 / 04', cw * 0.72, ch * 0.48, minSide * 0.023, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('01 / 04', cx + cw * 0.5, cy + ch * 0.52);
      });
      ctx.restore();
    }

    // Row 1: Left Hero Title Card ("PRICE DROP") + Right Dual-Reel Odometer Vault ("75%")
    const leftW = stageW * 0.54 - gutter * 0.5;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;

    const mMainL = getCardMotion(p, 0.02, 0.02);
    if (mMainL.vis > 0.01) {
      const curW = leftW * mMainL.cardVis;
      drawClippedCard(stageX, mainY, curW, mainH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.045;
        const innerW = leftW - pad * 2;

        const tagW = leftW * 0.36;
        const tagH = mainH * 0.14;
        fillRoundRect(cx + pad, cy + pad, tagW, tagH, tagH * 0.5, COLORS.surfaceMid);
        const tfs = fitFontSize('VERIFIED SAVINGS', tagW * 0.84, tagH * 0.5, minSide * 0.02, '800');
        ctx.font = '800 ' + tfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('VERIFIED SAVINGS', cx + pad + tagW * 0.5, cy + pad + tagH * 0.52);

        const shift = (1 - mMainL.innerAlpha) * stageW * 0.02;
        const fs1 = fitFontSize('PRICE', innerW, mainH * 0.25, minSide * 0.105, '900');
        ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.textAlign = 'left';
        ctx.fillText('PRICE', cx + pad - shift, cy + mainH * 0.42);

        const fs2 = fitFontSize('DROP', innerW, mainH * 0.25, minSide * 0.105, '900');
        ctx.font = '900 ' + fs2 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.fillText('DROP', cx + pad - shift, cy + mainH * 0.66);

        // Synchronized Mint Progress Track inside bottom zone of Left Hero Card
        const barH = mainH * 0.065;
        const barY = cy + mainH * 0.84;
        fillRoundRect(cx + pad, barY, innerW, barH, barH * 0.5, COLORS.well);
        const barU = easeOutCubic(clamp((p - 0.12) / 0.52, 0, 1));
        fillRoundRect(cx + pad, barY, innerW * barU, barH, barH * 0.5, COLORS.mint);
      }, mMainL.innerAlpha);
    }

    const mMainR = getCardMotion(p, 0.05, 0.0);
    if (mMainR.vis > 0.01) {
      const curH = mainH * mMainR.cardVis;
      const curY = mainY + (mainH - curH) * 0.5;
      drawClippedCard(rightX, curY, rightW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.04;
        const innerW = cw - pad * 2;
        const topLabelFs = fitFontSize('SAVINGS LOCKED', innerW * 0.8, mainH * 0.12, minSide * 0.024, '800');
        ctx.font = '800 ' + topLabelFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.muted;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SAVINGS LOCKED', cx + cw * 0.5, mainY + mainH * 0.16);

        // Two Smooth Rolling Odometer Slot Reels + Crisp '%' Glyph (00% -> 75%)
        const rollU = easeInOutQuart(clamp((p - 0.10) / 0.38, 0, 1));
        const tensExact = lerp(0, 7, rollU);
        const onesExact = lerp(0, 25, rollU); // spins 2.5 smooth cycles and locks dead-center on digit '5'!

        const slotH = mainH * 0.44;
        const slotW = Math.min(innerW * 0.30, slotH * 0.72);
        const pctSize = fitFontSize('%', innerW * 0.22, slotH * 0.85, minSide * 0.11, '900');
        ctx.font = '900 ' + pctSize + 'px ' + FONT_FAMILY;
        const pctW = ctx.measureText('%').width;
        const slotGap = minSide * 0.015;
        const groupW = slotW * 2 + slotGap * 2 + pctW;
        const sx = cx + (cw - groupW) * 0.5;
        const sy = mainY + mainH * 0.50 - slotH * 0.5;
        const digitFs = fitFontSize('8', slotW * 0.74, slotH * 0.72, slotH * 0.65, '900');

        drawReelSlot(sx, sy, slotW, slotH, cardR * 0.65, tensExact, 1, digitFs, '900', COLORS.well, COLORS.white);
        drawReelSlot(sx + slotW + slotGap, sy, slotW, slotH, cardR * 0.65, onesExact, 1, digitFs, '900', COLORS.well, COLORS.mint);

        ctx.font = '900 ' + pctSize + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'left';
        ctx.fillText('%', sx + slotW * 2 + slotGap * 2, mainY + mainH * 0.51);

        const footFs = fitFontSize('AUTO APPLIED  •  ALL CATEGORIES', innerW, mainH * 0.1, minSide * 0.021, '800');
        ctx.font = '800 ' + footFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.textAlign = 'center';
        ctx.fillText('AUTO APPLIED  •  ALL CATEGORIES', cx + cw * 0.5, mainY + mainH * 0.85);
      }, mMainR.innerAlpha);
    }

    // Row 2: Bottom Action Bar
    const mBot = getCardMotion(p, 0.08, 0.01);
    if (mBot.vis > 0.01) {
      const curW = stageW * mBot.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, botY, curW, botH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('REAL-TIME MARKDOWN  •  LIMITED QUANTITY', stageW * 0.65, ch * 0.45, minSide * 0.028, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('REAL-TIME MARKDOWN  •  LIMITED QUANTITY', stageX + stageW * 0.5, cy + ch * 0.52);

        const dotR = minSide * 0.008 * (0.7 + 0.3 * Math.sin(p * Math.PI * 6));
        ctx.beginPath();
        ctx.arc(stageX + minSide * 0.06, cy + ch * 0.5, dotR, 0, Math.PI * 2);
        ctx.arc(stageX + stageW - minSide * 0.06, cy + ch * 0.5, dotR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.mint;
        ctx.fill();
      }, mBot.innerAlpha);
    }
  } else if (sceneIdx === 1) {
    // SCENE 1: "SAVE MORE" — Markdown Strike-Through Price & 2D Vector Savings Chart
    const leftW = stageW * 0.47 - gutter * 0.5;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;

    const mLeft = getCardMotion(p, 0.0, 0.02);
    if (mLeft.vis > 0.01) {
      const curW = leftW * mLeft.cardVis;
      drawClippedCard(stageX, stageY, curW, stageH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.045;
        const innerW = leftW - pad * 2;

        const tagW = leftW * 0.48;
        const tagH = ch * 0.095;
        fillRoundRect(cx + pad, cy + pad, tagW, tagH, tagH * 0.5, COLORS.mint);
        const tfs = fitFontSize('02 / 04 • SMART VALUE', tagW * 0.86, tagH * 0.5, minSide * 0.021, '900');
        ctx.font = '900 ' + tfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('02 / 04 • SMART VALUE', cx + pad + tagW * 0.5, cy + pad + tagH * 0.52);

        const hfs = fitFontSize('SAVE MORE', innerW, ch * 0.16, minSide * 0.068, '900');
        ctx.font = '900 ' + hfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.fillText('SAVE MORE', cx + pad, cy + ch * 0.27);

        // Old Price with Crisp Animated Horizontal Strike-Through
        const oldPriceY = cy + ch * 0.44;
        const oldFs = fitFontSize('$199 REGULAR', innerW * 0.72, ch * 0.09, minSide * 0.036, '800');
        ctx.font = '800 ' + oldFs + 'px ' + FONT_FAMILY;
        const oldText = '$199';
        const oldW = ctx.measureText(oldText).width;
        ctx.fillStyle = COLORS.muted;
        ctx.fillText(oldText, cx + pad, oldPriceY);

        const strikeU = easeOutCubic(clamp((p - 0.14) / 0.22, 0, 1));
        if (strikeU > 0.02) {
          ctx.beginPath();
          ctx.moveTo(cx + pad - minSide * 0.008, oldPriceY);
          ctx.lineTo(cx + pad + (oldW + minSide * 0.016) * strikeU, oldPriceY);
          ctx.strokeStyle = COLORS.mint;
          ctx.lineWidth = minSide * 0.0055;
          ctx.lineCap = 'round';
          ctx.stroke();
        }

        // Dynamic Price-Drop Badge Pill ("-75%") with Downward Arrow strictly clear to the right
        const dropW = leftW * 0.28;
        const dropH = ch * 0.09;
        const dropX = cx + leftW - pad - dropW;
        const dropY = oldPriceY - dropH * 0.5;
        fillRoundRect(dropX, dropY, dropW, dropH, dropH * 0.5, COLORS.surfaceMid);
        drawDownArrow(dropX + dropH * 0.5, oldPriceY, dropH * 0.4, minSide * 0.005, COLORS.mint);
        const dfs = fitFontSize('-75%', dropW * 0.55, dropH * 0.52, minSide * 0.024, '900');
        ctx.font = '900 ' + dfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.fillText('-75%', dropX + dropW * 0.64, oldPriceY + minSide * 0.002);

        // New Discounted Odometer Box "$ 4 9" in Dark Slate Well
        const boxY = cy + ch * 0.55;
        const boxH = ch * 0.31;
        drawClippedCard(cx + pad, boxY, innerW, boxH, cardR * 0.75, COLORS.well, (bx, by, bw, bh) => {
          const dropU = easeInOutQuart(clamp((p - 0.10) / 0.38, 0, 1));
          const reel1 = lerp(19, 4, dropU);
          const reel2 = lerp(19, 9, dropU);
          const symFs = fitFontSize('$', bw * 0.18, bh * 0.62, minSide * 0.088, '900');
          ctx.font = '900 ' + symFs + 'px ' + FONT_FAMILY;
          ctx.fillStyle = COLORS.ice;
          ctx.textAlign = 'right';
          ctx.textBaseline = 'middle';
          const slotW = Math.min(bw * 0.25, bh * 0.75);
          const slotH = bh * 0.78;
          const slotGap = minSide * 0.012;
          const groupX = bx + bw * 0.5 - (slotW * 2 + slotGap) * 0.5 + minSide * 0.03;

          ctx.fillText('$', groupX - minSide * 0.018, by + bh * 0.52);
          const dFs = fitFontSize('8', slotW * 0.74, slotH * 0.72, slotH * 0.68, '900');
          drawReelSlot(groupX, by + (bh - slotH) * 0.5, slotW, slotH, cardR * 0.45, reel1, -1, dFs, '900', COLORS.surface, COLORS.mint);
          drawReelSlot(groupX + slotW + slotGap, by + (bh - slotH) * 0.5, slotW, slotH, cardR * 0.45, reel2, -1, dFs, '900', COLORS.surface, COLORS.mint);
        });
      }, mLeft.innerAlpha);
    }

    const mRight = getCardMotion(p, 0.05, 0.0);
    if (mRight.vis > 0.01) {
      const curH = stageH * mRight.cardVis;
      const curY = stageY + (stageH - curH) * 0.5;
      drawClippedCard(rightX, curY, rightW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.045;
        const innerW = cw - pad * 2;
        const headFs = fitFontSize('SAVINGS GROWTH INDEX', innerW * 0.65, stageH * 0.08, minSide * 0.025, '800');
        ctx.font = '800 ' + headFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('SAVINGS GROWTH INDEX', cx + pad, stageY + pad + stageH * 0.03);

        const maxTagW = cw * 0.26;
        const maxTagH = stageH * 0.075;
        fillRoundRect(cx + cw - pad - maxTagW, stageY + pad, maxTagW, maxTagH, maxTagH * 0.5, COLORS.well);
        const mfs = fitFontSize('MAX TIER', maxTagW * 0.8, maxTagH * 0.5, minSide * 0.019, '900');
        ctx.font = '900 ' + mfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.fillText('MAX TIER', cx + cw - pad - maxTagW * 0.5, stageY + pad + maxTagH * 0.52);

        // 2D Vector Line Chart strictly confined inside padded chart card
        const chartY = stageY + stageH * 0.18;
        const chartH = stageH * 0.48;
        drawClippedCard(cx + pad, chartY, innerW, chartH, cardR * 0.75, COLORS.well, (gx, gy, gw, gh) => {
          const gPad = minSide * 0.032;
          const x0 = gx + gPad;
          const x1 = gx + gw - gPad;
          const y0 = gy + gPad;
          const y1 = gy + gh - gPad;

          // Subtle flat horizontal reference rules
          ctx.strokeStyle = COLORS.surface;
          ctx.lineWidth = minSide * 0.002;
          for (let g = 0; g < 4; g++) {
            const ry = lerp(y0, y1, g / 3);
            ctx.beginPath();
            ctx.moveTo(x0, ry);
            ctx.lineTo(x1, ry);
            ctx.stroke();
          }

          const nodes = [
            [0.0, 0.85],
            [0.2, 0.72],
            [0.42, 0.60],
            [0.65, 0.35],
            [0.84, 0.22],
            [1.0, 0.08]
          ];
          const traceU = easeOutCubic(clamp((p - 0.12) / 0.38, 0, 1));
          const maxIdx = traceU * (nodes.length - 1);
          const whole = Math.floor(maxIdx);
          const rem = maxIdx - whole;

          ctx.beginPath();
          for (let i = 0; i <= whole; i++) {
            const px = lerp(x0, x1, nodes[i][0]);
            const py = lerp(y0, y1, nodes[i][1]);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
          }
          let tipX = lerp(x0, x1, nodes[Math.min(whole, nodes.length - 1)][0]);
          let tipY = lerp(y0, y1, nodes[Math.min(whole, nodes.length - 1)][1]);
          if (whole < nodes.length - 1) {
            tipX = lerp(x0, x1, lerp(nodes[whole][0], nodes[whole + 1][0], rem));
            tipY = lerp(y0, y1, lerp(nodes[whole][1], nodes[whole + 1][1], rem));
            ctx.lineTo(tipX, tipY);
          }
          ctx.strokeStyle = COLORS.mint;
          ctx.lineWidth = minSide * 0.007;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.stroke();

          // Clean Tip Node Dot inside safe chart padding
          ctx.beginPath();
          ctx.arc(tipX, tipY, minSide * 0.013, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.white;
          ctx.fill();
          ctx.beginPath();
          ctx.arc(tipX, tipY, minSide * 0.006, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.mint;
          ctx.fill();
        });

        // Bottom 4 Equal-Width Crisp Stat Bars inside Right Panel
        const barAreaY = stageY + stageH * 0.72;
        const barAreaH = stageH * 0.20;
        const bCount = 4;
        const bGap = minSide * 0.018;
        const bW = (innerW - bGap * (bCount - 1)) / bCount;
        const targets = [0.42, 0.62, 0.80, 0.96];
        const barLabels = ['25%', '45%', '60%', '75%'];
        const blFs = fitFontSize('75%', bW * 0.7, barAreaH * 0.26, minSide * 0.02, '800');
        for (let b = 0; b < bCount; b++) {
          const bx = cx + pad + b * (bW + bGap);
          fillRoundRect(bx, barAreaY, bW, barAreaH, bW * 0.2, COLORS.well);
          const fillH = barAreaH * targets[b] * easeOutCubic(clamp((p - 0.10 - b * 0.04) / 0.28, 0, 1));
          fillRoundRect(bx, barAreaY + barAreaH - fillH, bW, fillH, bW * 0.2, b === 3 ? COLORS.mint : COLORS.ice);
          ctx.font = '800 ' + blFs + 'px ' + FONT_FAMILY;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillStyle = fillH > barAreaH * 0.35 ? COLORS.bg : COLORS.muted;
          ctx.fillText(barLabels[b], bx + bW * 0.5, barAreaY + barAreaH - Math.min(fillH * 0.5, barAreaH * 0.22));
        }
      }, mRight.innerAlpha);
    }
  } else if (sceneIdx === 2) {
    // SCENE 2: "24 : 00 : 00" COUNTDOWN BLOCKS & "FLASH DEAL" TRACK
    const topH = stageH * 0.14;
    const midY = stageY + stageH * 0.20;
    const midH = stageH * 0.56;
    const botY = stageY + stageH * 0.82;
    const botH = stageH * 0.18;

    // Row 0: Live Header
    const mTop = getCardMotion(p, 0.0, 0.03);
    if (mTop.vis > 0.01) {
      const curW = stageW * mTop.cardVis;
      drawClippedCard(stageX, stageY, curW, topH, cardR * 0.75, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.035;
        const tagW = stageW * 0.22;
        const tagH = ch * 0.56;
        const tagY = cy + (ch - tagH) * 0.5;
        fillRoundRect(stageX + pad, tagY, tagW, tagH, tagH * 0.5, COLORS.mint);
        const tfs = fitFontSize('LIMITED WINDOW', tagW * 0.84, tagH * 0.52, minSide * 0.022, '900');
        ctx.font = '900 ' + tfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('LIMITED WINDOW', stageX + pad + tagW * 0.5, tagY + tagH * 0.52);

        const hfs = fitFontSize('24-HOUR COUNTDOWN', stageW * 0.42, ch * 0.52, minSide * 0.032, '900');
        ctx.font = '900 ' + hfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.fillText('24-HOUR COUNTDOWN', stageX + stageW * 0.5, cy + ch * 0.52);

        const rTagW = stageW * 0.15;
        const rx = stageX + stageW - pad - rTagW;
        fillRoundRect(rx, tagY, rTagW, tagH, tagH * 0.5, COLORS.surfaceMid);
        const rfs = fitFontSize('03 / 04', rTagW * 0.76, tagH * 0.5, minSide * 0.022, '800');
        ctx.font = '800 ' + rfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.fillText('03 / 04', rx + rTagW * 0.5, tagY + tagH * 0.52);
      }, mTop.innerAlpha);
    }

    // Row 1: 3 Precision Clock Blocks Separated Clearly with Floating Colon Dots in Gaps
    const colonGap = minSide * 0.055;
    const blockW = (stageW - colonGap * 2) / 3;
    // Tick smoothly downward from 24:00:00 -> 23:59:55 across settled portion [0.22..0.78]
    const tickSec = clamp((p - 0.22) / 0.56, 0, 1) * 5;
    const secSmooth = tickSec === 0 ? 0 : 60 - tickSec;
    const minReel = tickSec === 0 ? 0 : lerp(0, 59, easeOutCubic(clamp(tickSec * 1.5, 0, 1)));
    const hrsReel = tickSec === 0 ? 24 : lerp(24, 23, easeOutCubic(clamp(tickSec * 1.5, 0, 1)));

    const units = [
      { label: 'HOURS', tens: Math.floor(hrsReel / 10), ones: hrsReel % 10, col: COLORS.white },
      { label: 'MINUTES', tens: Math.floor(minReel / 10), ones: minReel % 10, col: COLORS.ice },
      { label: 'SECONDS', tens: Math.floor(secSmooth / 10), ones: secSmooth % 10, col: COLORS.mint }
    ];

    for (let i = 0; i < 3; i++) {
      const bx = stageX + i * (blockW + colonGap);
      const mb = getCardMotion(p, 0.03 + i * 0.03, 0.02);
      if (mb.vis > 0.01) {
        const curH = midH * mb.cardVis;
        drawClippedCard(bx, midY + (midH - curH) * 0.5, blockW, curH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
          const pad = minSide * 0.035;
          const innerW = cw - pad * 2;
          const slotH = midH * 0.52;
          const slotW = (innerW - minSide * 0.018) * 0.5;
          const slotY = midY + midH * 0.14;
          const dFs = fitFontSize('8', slotW * 0.72, slotH * 0.72, minSide * 0.12, '900');

          const u = units[i];
          drawReelSlot(cx + pad, slotY, slotW, slotH, cardR * 0.65, u.tens, -1, dFs, '900', COLORS.well, u.col);
          drawReelSlot(cx + pad + slotW + minSide * 0.018, slotY, slotW, slotH, cardR * 0.65, u.ones, -1, dFs, '900', COLORS.well, u.col);

          const lfs = fitFontSize(u.label, innerW * 0.8, midH * 0.12, minSide * 0.026, '800');
          ctx.font = '800 ' + lfs + 'px ' + FONT_FAMILY;
          ctx.fillStyle = COLORS.muted;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(u.label, cx + cw * 0.5, midY + midH * 0.82);
        }, mb.innerAlpha);

        // Pulsing Colon Dots strictly centered inside colonGap between adjacent cards
        if (i < 2 && mb.innerAlpha > 0.2) {
          const dotX = bx + blockW + colonGap * 0.5;
          const blink = 0.5 + 0.5 * Math.sin(p * Math.PI * 10);
          ctx.save();
          ctx.globalAlpha = mb.innerAlpha * (0.45 + 0.55 * blink);
          ctx.fillStyle = COLORS.mint;
          const dr = minSide * 0.009;
          ctx.beginPath();
          ctx.arc(dotX, midY + midH * 0.34, dr, 0, Math.PI * 2);
          ctx.arc(dotX, midY + midH * 0.50, dr, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
        }
      }
    }

    // Row 2: Bottom Conveyor Bar ("FLASH DEAL")
    const mBot = getCardMotion(p, 0.08, 0.0);
    if (mBot.vis > 0.01) {
      const curW = stageW * mBot.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, botY, curW, botH, botH * 0.5, COLORS.mint, (cx, cy, cw, ch) => {
        const fs = fitFontSize('FLASH DEAL  •  LOCK YOUR PRICE TODAY', stageW * 0.68, ch * 0.52, minSide * 0.032, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('FLASH DEAL  •  LOCK YOUR PRICE TODAY', stageX + stageW * 0.5, cy + ch * 0.52);
      }, mBot.innerAlpha);
    }
  } else {
    // SCENE 3: Full-Width Progress Expansion -> "CHECKOUT NOW" & Clean Odometer Zero-Reset
    const tierGap = stageH * 0.045;
    const topH = stageH * 0.15;
    const midH = stageH * 0.60;
    const botH = stageH * 0.16;

    const topY = stageY;
    const midY = topY + topH + tierGap;
    const botY = midY + midH + tierGap;

    const pillLabels = ['75% APPLIED', 'INSTANT CART', 'ZERO CODE'];
    const pillW = (stageW - gutter * 2) / 3;
    for (let i = 0; i < 3; i++) {
      const px = stageX + (pillW + gutter) * i;
      const mp = getCardMotion(p, i * 0.02, 0.03);
      if (mp.vis > 0.01) {
        const curH = topH * mp.cardVis;
        drawClippedCard(px, topY + (topH - curH) * 0.5, pillW, curH, cardR * 0.75, COLORS.surface, (cx, cy, cw, ch) => {
          const fs = fitFontSize('• ' + pillLabels[i], cw * 0.82, topH * 0.46, minSide * 0.024, '800');
          ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
          const tw = ctx.measureText(pillLabels[i]).width;
          const dotR = fs * 0.22;
          const gap = fs * 0.55;
          const totalW = dotR * 2 + gap + tw;
          const sx = cx + (cw - totalW) * 0.5;
          ctx.beginPath();
          ctx.arc(sx + dotR, topY + topH * 0.5, dotR, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.mint;
          ctx.fill();
          ctx.fillStyle = COLORS.ice;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText(pillLabels[i], sx + dotR * 2 + gap, topY + topH * 0.52);
        }, mp.innerAlpha);
      }
    }

    // Row 1: Expanding Full-Width Progress CTA Showcase ("CHECKOUT NOW")
    const mCenter = getCardMotion(p, 0.04, 0.02);
    if (mCenter.vis > 0.01) {
      const curW = stageW * mCenter.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, midY, curW, midH, cardR * 1.15, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.05;
        const innerW = stageW - pad * 2;
        const fullFillU = easeInOutQuart(clamp((p - 0.10) / 0.35, 0, 1));

        // Animated Mint Progress Bar Fill Track at Upper Zone
        const trackH = ch * 0.14;
        const trackY = cy + pad;
        fillRoundRect(stageX + pad, trackY, innerW, trackH, trackH * 0.5, COLORS.well);
        fillRoundRect(stageX + pad, trackY, innerW * fullFillU, trackH, trackH * 0.5, COLORS.mint);

        // Status Percentage Label inside Track Right-Cleared or Center Pill
        const pctNum = Math.round(lerp(0, 100, fullFillU));
        const pctStr = pctNum + '% READY';
        const pFs = fitFontSize(pctStr, innerW * 0.3, trackH * 0.55, minSide * 0.022, '900');
        ctx.font = '900 ' + pFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = fullFillU > 0.58 ? COLORS.bg : COLORS.ice;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(pctStr, width * 0.5, trackY + trackH * 0.52);

        // Main Unified Hero Lockup: "CHECKOUT NOW" + Mint Circle Chevron
        const headline = 'CHECKOUT NOW';
        const hSize = fitFontSize(headline, stageW * 0.64, ch * 0.40, minSide * 0.095, '900');
        ctx.font = '900 ' + hSize + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText(headline).width;
        const iconR = minSide * 0.052;
        const iconGap = minSide * 0.032;
        const lockupW = tw + iconGap + iconR * 2;
        const startLX = width * 0.5 - lockupW * 0.5;
        const heroY = cy + ch * 0.62;

        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.fillText(headline, startLX, heroY);

        const icx = startLX + tw + iconGap + iconR;
        ctx.beginPath();
        ctx.arc(icx, heroY, iconR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.mint;
        ctx.fill();
        drawChevron(icx + Math.sin(p * Math.PI * 4) * iconR * 0.1, heroY, iconR * 0.38, minSide * 0.0075, 1, COLORS.bg);
      }, mCenter.innerAlpha);
    }

    // Row 2: Bottom Status Bar
    const mBot = getCardMotion(p, 0.08, 0.0);
    if (mBot.vis > 0.01) {
      const curW = stageW * mBot.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, botY, curW, botH, botH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('04 / 04  •  DEAL EXPIRES SOON', stageW * 0.55, ch * 0.5, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('04 / 04  •  DEAL EXPIRES SOON', width * 0.5, cy + ch * 0.52);

        const lineW = stageW * 0.14;
        const lineH = minSide * 0.0055;
        fillRoundRect(stageX + minSide * 0.04, cy + (ch - lineH) * 0.5, lineW, lineH, lineH * 0.5, COLORS.mint);
        fillRoundRect(stageX + stageW - minSide * 0.04 - lineW, cy + (ch - lineH) * 0.5, lineW, lineH, lineH * 0.5, COLORS.mint);
      }, mBot.innerAlpha);
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#1E0A2E',
    surface: '#2A103F',
    surfaceMid: '#391754',
    rose: '#FFD1DC',
    gold: '#F8C957',
    goldBright: '#FFE8A3',
    white: '#FFF6F8',
    muted: '#C2A0CA',
    dot: '#2D1245',
    rule: '#431C63'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function addRoundRectSubpath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function addPolySubpath(ox, oy, scale, pts) {
    ctx.moveTo(ox + pts[0][0] * scale, oy + pts[0][1] * scale);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(ox + pts[i][0] * scale, oy + pts[i][1] * scale);
    }
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01 || w <= 0.5 || h <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawFourPointStar(cx, cy, outerR, innerR, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const a = (i * Math.PI) / 4;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawOctagonSeal(cx, cy, r, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    for (let i = 0; i < 16; i++) {
      const rad = i % 2 === 0 ? r : r * 0.86;
      const a = (i * Math.PI * 2) / 16;
      const px = Math.cos(a) * rad;
      const py = Math.sin(a) * rad;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  // Normalized Geometric Vector Glyph Metrics & Path Subpath Builders (Height = 1.0, evenodd holes)
  const GLYPH_ADV = {
    V: 0.76,
    I: 0.24,
    P: 0.70,
    L: 0.62,
    U: 0.74,
    X: 0.78,
    E: 0.64,
    '4': 0.76,
    '0': 0.74,
    '%': 0.90,
    N: 0.74,
    O: 0.74,
    C: 0.70,
    K: 0.74
  };

  function addGlyphSubpaths(ch, ox, oy, s) {
    if (ch === 'I') {
      addPolySubpath(ox, oy, s, [[0, 0], [0.24, 0], [0.24, 1], [0, 1]]);
    } else if (ch === 'V') {
      addPolySubpath(ox, oy, s, [
        [0, 0], [0.23, 0], [0.38, 0.58], [0.53, 0], [0.76, 0], [0.49, 1], [0.27, 1]
      ]);
    } else if (ch === 'P') {
      ctx.moveTo(ox, oy);
      ctx.lineTo(ox + 0.46 * s, oy);
      ctx.quadraticCurveTo(ox + 0.70 * s, oy, ox + 0.70 * s, oy + 0.31 * s);
      ctx.quadraticCurveTo(ox + 0.70 * s, oy + 0.62 * s, ox + 0.46 * s, oy + 0.62 * s);
      ctx.lineTo(ox + 0.23 * s, oy + 0.62 * s);
      ctx.lineTo(ox + 0.23 * s, oy + s);
      ctx.lineTo(ox, oy + s);
      ctx.closePath();
      // Counter hole
      ctx.moveTo(ox + 0.23 * s, oy + 0.20 * s);
      ctx.lineTo(ox + 0.41 * s, oy + 0.20 * s);
      ctx.quadraticCurveTo(ox + 0.49 * s, oy + 0.20 * s, ox + 0.49 * s, oy + 0.31 * s);
      ctx.quadraticCurveTo(ox + 0.49 * s, oy + 0.42 * s, ox + 0.41 * s, oy + 0.42 * s);
      ctx.lineTo(ox + 0.23 * s, oy + 0.42 * s);
      ctx.closePath();
    } else if (ch === 'L') {
      addPolySubpath(ox, oy, s, [[0, 0], [0.23, 0], [0.23, 0.79], [0.62, 0.79], [0.62, 1], [0, 1]]);
    } else if (ch === 'U') {
      ctx.moveTo(ox, oy);
      ctx.lineTo(ox + 0.22 * s, oy);
      ctx.lineTo(ox + 0.22 * s, oy + 0.64 * s);
      ctx.quadraticCurveTo(ox + 0.22 * s, oy + 0.80 * s, ox + 0.37 * s, oy + 0.80 * s);
      ctx.quadraticCurveTo(ox + 0.52 * s, oy + 0.80 * s, ox + 0.52 * s, oy + 0.64 * s);
      ctx.lineTo(ox + 0.52 * s, oy);
      ctx.lineTo(ox + 0.74 * s, oy);
      ctx.lineTo(ox + 0.74 * s, oy + 0.65 * s);
      ctx.quadraticCurveTo(ox + 0.74 * s, oy + s, ox + 0.37 * s, oy + s);
      ctx.quadraticCurveTo(ox, oy + s, ox, oy + 0.65 * s);
      ctx.closePath();
    } else if (ch === 'X') {
      addPolySubpath(ox, oy, s, [
        [0, 0], [0.25, 0], [0.39, 0.30], [0.53, 0], [0.78, 0],
        [0.52, 0.50], [0.78, 1], [0.53, 1], [0.39, 0.70], [0.25, 1], [0, 1], [0.26, 0.50]
      ]);
    } else if (ch === 'E') {
      addPolySubpath(ox, oy, s, [
        [0, 0], [0.64, 0], [0.64, 0.20], [0.23, 0.20], [0.23, 0.40], [0.56, 0.40],
        [0.56, 0.59], [0.23, 0.59], [0.23, 0.80], [0.64, 0.80], [0.64, 1], [0, 1]
      ]);
    } else if (ch === '4') {
      addPolySubpath(ox, oy, s, [
        [0.42, 0], [0.66, 0], [0.66, 0.63], [0.76, 0.63], [0.76, 0.82],
        [0.66, 0.82], [0.66, 1], [0.43, 1], [0.43, 0.82], [0, 0.82], [0, 0.59]
      ]);
      addPolySubpath(ox, oy, s, [[0.20, 0.63], [0.43, 0.63], [0.43, 0.24]]);
    } else if (ch === '0' || ch === 'O') {
      addRoundRectSubpath(ox, oy, 0.74 * s, s, 0.35 * s);
      addRoundRectSubpath(ox + 0.22 * s, oy + 0.20 * s, 0.30 * s, 0.60 * s, 0.14 * s);
    } else if (ch === '%') {
      // Top-left ring
      const r1x = ox + 0.19 * s;
      const r1y = oy + 0.20 * s;
      ctx.moveTo(r1x + 0.18 * s, r1y);
      ctx.arc(r1x, r1y, 0.18 * s, 0, Math.PI * 2);
      ctx.moveTo(r1x + 0.065 * s, r1y);
      ctx.arc(r1x, r1y, 0.065 * s, 0, Math.PI * 2);
      // Tilted diagonal bar cleanly clear of both rings
      addPolySubpath(ox, oy, s, [[0.68, 0], [0.84, 0], [0.22, 1], [0.06, 1]]);
      // Bottom-right ring
      const r2x = ox + 0.71 * s;
      const r2y = oy + 0.80 * s;
      ctx.moveTo(r2x + 0.18 * s, r2y);
      ctx.arc(r2x, r2y, 0.18 * s, 0, Math.PI * 2);
      ctx.moveTo(r2x + 0.065 * s, r2y);
      ctx.arc(r2x, r2y, 0.065 * s, 0, Math.PI * 2);
    } else if (ch === 'N') {
      addPolySubpath(ox, oy, s, [
        [0, 0], [0.23, 0], [0.52, 0.61], [0.52, 0], [0.74, 0],
        [0.74, 1], [0.51, 1], [0.22, 0.39], [0.22, 1], [0, 1]
      ]);
    } else if (ch === 'C') {
      const cx0 = ox + 0.37 * s;
      const cy0 = oy + 0.50 * s;
      const startA = 0.66;
      const endA = Math.PI * 2 - 0.66;
      const segs = 28;
      for (let i = 0; i <= segs; i++) {
        const a = lerp(startA, endA, i / segs);
        const px = cx0 + Math.cos(a) * 0.37 * s;
        const py = cy0 + Math.sin(a) * 0.50 * s;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      for (let i = segs; i >= 0; i--) {
        const a = lerp(startA, endA, i / segs);
        const px = cx0 + Math.cos(a) * 0.16 * s;
        const py = cy0 + Math.sin(a) * 0.29 * s;
        ctx.lineTo(px, py);
      }
      ctx.closePath();
    } else if (ch === 'K') {
      addPolySubpath(ox, oy, s, [
        [0, 0], [0.23, 0], [0.23, 0.39], [0.49, 0], [0.74, 0],
        [0.44, 0.48], [0.74, 1], [0.49, 1], [0.23, 0.59], [0.23, 1], [0, 1]
      ]);
    }
  }

  function traceWordSubpaths(word, cx, cy, s, letterGapRatio) {
    let totalAdv = 0;
    for (let i = 0; i < word.length; i++) {
      totalAdv += GLYPH_ADV[word[i]] || 0.7;
      if (i < word.length - 1) totalAdv += letterGapRatio;
    }
    const wordW = totalAdv * s;
    const startX = cx - wordW * 0.5;
    const startY = cy - s * 0.5;
    let curX = startX;
    for (let i = 0; i < word.length; i++) {
      const ch = word[i];
      addGlyphSubpaths(ch, curX, startY, s);
      curX += ((GLYPH_ADV[ch] || 0.7) + letterGapRatio) * s;
    }
    return { x: startX, y: startY, w: wordW, h: s };
  }

  // Render Giant Vector Text as a True Live Clipping Window for Metallic Shimmer Ribbons & Twinkling Stars
  function drawClipMaskWord(word, cx, cy, maxW, maxH, gapRatio, phase, slitRatio, baseFill, outlineCol, outlineW) {
    let totalAdv = 0;
    for (let i = 0; i < word.length; i++) {
      totalAdv += GLYPH_ADV[word[i]] || 0.7;
      if (i < word.length - 1) totalAdv += gapRatio;
    }
    const s = Math.min(maxW / totalAdv, maxH);
    const totalW = totalAdv * s;
    const slitW = totalW * clamp(slitRatio, 0, 1);
    if (slitW <= 1) return;

    ctx.save();
    // Vertical Slit Mask Window around center (active during slit reveal, open completely at 1.0)
    if (slitRatio < 0.999) {
      ctx.beginPath();
      ctx.rect(cx - slitW * 0.5, cy - s * 0.56, slitW, s * 1.12);
      ctx.clip();
    }

    // Trace crisp glyph vector paths once for clipping
    ctx.beginPath();
    const box = traceWordSubpaths(word, cx, cy, s, gapRatio);

    ctx.save();
    ctx.clip('evenodd');

    // Interior deep satin fill
    ctx.fillStyle = baseFill;
    ctx.fillRect(box.x - 4, box.y - 4, box.w + 8, box.h + 8);

    // Sweeping Diagonal Shimmer Gold & Champagne Light Bands strictly inside clipped glyphs
    const sweepSpan = box.w + box.h * 1.8;
    const bandTravel = ((phase % 1) + 1) % 1;
    const bands = [
      { off: -0.1, w: 0.14, col: COLORS.gold },
      { off: 0.16, w: 0.06, col: COLORS.goldBright },
      { off: 0.34, w: 0.11, col: COLORS.rose },
      { off: 0.62, w: 0.08, col: COLORS.gold }
    ];
    for (let b = 0; b < bands.length; b++) {
      const bd = bands[b];
      const u = ((bandTravel + bd.off) % 1 + 1) % 1;
      const sx = box.x - box.h * 0.6 + u * sweepSpan;
      const bw = box.w * bd.w;
      const skew = box.h * 0.45;
      ctx.beginPath();
      ctx.moveTo(sx, box.y - 4);
      ctx.lineTo(sx + bw, box.y - 4);
      ctx.lineTo(sx + bw - skew, box.y + box.h + 4);
      ctx.lineTo(sx - skew, box.y + box.h + 4);
      ctx.closePath();
      ctx.fillStyle = bd.col;
      ctx.fill();
    }

    // Deterministic Evenly Distributed Grid of Crisp Vector 4-Point Diamond Sparkles inside Letter Interior
    const starCols = 6;
    const starRows = 5;
    const starCount = starCols * starRows;
    for (let k = 0; k < starCount; k++) {
      const colIdx = k % starCols;
      const rowIdx = Math.floor(k / starCols);
      const jx = ((k * 0.6180339) % 1 - 0.5) * 0.55;
      const jy = ((k * 0.381966) % 1 - 0.5) * 0.55;
      const fx = (colIdx + 0.5 + jx) / starCols;
      const fy = (rowIdx + 0.5 + jy) / starRows;
      const sx = box.x + fx * box.w;
      const sy = box.y + fy * box.h;
      const tw = 0.38 + 0.62 * (0.5 + 0.5 * Math.sin(phase * Math.PI * 4 + k * 1.15));
      const sr = s * (0.042 + (k % 3) * 0.015) * tw;
      const col = k % 3 === 0 ? COLORS.white : k % 3 === 1 ? COLORS.goldBright : COLORS.rose;
      drawFourPointStar(sx, sy, sr, sr * 0.28, k * 0.2 + phase * Math.PI, col);
    }

    ctx.restore();

    // Razor-sharp outer & inner contour highlight stroke for high-fashion contrast
    if (outlineW > 0.2) {
      ctx.beginPath();
      traceWordSubpaths(word, cx, cy, s, gapRatio);
      ctx.strokeStyle = outlineCol;
      ctx.lineWidth = outlineW;
      ctx.lineJoin = 'round';
      ctx.stroke();
    }
    ctx.restore();
  }

  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.17;
    const exitDur = 0.17;
    const inU = clamp((p - enterDelay) / enterDur, 0, 1);
    const outU = clamp((p - (0.80 - exitDelay)) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Flat Velvet Plum Background (Strictly ZERO background glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Subtle Flat Faceted Diamond Lattice in Central Stage (Seamless 2-cycle loop)
  const bandH = height * 0.088;
  const loopAngle = 2 * Math.PI * (safeLoopT / duration);
  const latticePhase = loopAngle * 2;
  const cols = 14;
  const rows = 6;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < rows; r++) {
    const dy = lerp(height * 0.16, height - height * 0.16, r / (rows - 1));
    for (let c = 0; c < cols; c++) {
      const dx = lerp(width * 0.08, width * 0.92, c / (cols - 1));
      const pulse = 0.5 + 0.5 * Math.sin(latticePhase + c * 0.5 + r * 0.8);
      const rad = minSide * (0.0024 + pulse * 0.0012);
      drawFourPointStar(dx, dy, rad * 1.4, rad * 0.5, 0, COLORS.dot);
    }
  }

  // 3. Persistent Seamless Top & Bottom Champagne/Gold Marquee Tracks
  function drawMarqueeTrack(y, h, text, speedDir, bgCol, textCol, dotCol) {
    ctx.fillStyle = bgCol;
    ctx.fillRect(0, y, width, h);

    const fontSize = fitFontSize('M', width, h * 0.44, minSide * 0.022, '800');
    ctx.save();
    ctx.font = '800 ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    const parts = text.split('•');
    let unitW = 0;
    const itemWidths = [];
    const padX = fontSize * 1.1;
    for (let i = 0; i < parts.length; i++) {
      const seg = parts[i].trim();
      const sw = ctx.measureText(seg).width;
