    let curX = startX;
    let idx = 0;
    const midY = y + h * 0.52;
    while (curX < width + unitW) {
      const item = itemWidths[idx % itemWidths.length];
      ctx.fillStyle = textCol;
      ctx.fillText(item.seg, curX, midY);
      drawFourPointStar(curX + item.w + padX, midY - fontSize * 0.03, fontSize * 0.24, fontSize * 0.09, 0, dotCol);
