          const bx = bx0 + b * barGap - barW * 0.5;
          const by = cy + ch * 0.78 - bh;
          fillRoundRect(bx, by, barW, bh, barW * 0.5, b === 1 ? COLORS.rose : COLORS.gold);
        }
      }, mSideL.innerAlpha);
    }

    const mCenter = getCardMotion(p, 0.06, 0.02);
    if (mCenter.vis > 0.01) {
      const curW = centerW * mCenter.cardVis;
      const curX = centerX + (centerW - curW) * 0.5;
      drawClippedCard(curX, midY, curW, midH, cardR * 1.15, COLORS.surface, (cx, cy, cw, ch) => {
        // Upper Zone (8%..56%): Giant Clipped Vector "UNLOCK" with uniform 1:1 scale & fade
        const reveal = easeOutQuint(clamp((p - 0.08) / 0.22, 0, 1));
        const wordScale = lerp(0.88, 1.0, reveal);
        const wcx = centerX + centerW * 0.5;
        const wcy = cy + ch * 0.34;
        ctx.save();
        ctx.globalAlpha *= reveal;
        ctx.translate(wcx, wcy);
        ctx.scale(wordScale, wordScale);
        ctx.translate(-wcx, -wcy);
        drawClipMaskWord(
          'UNLOCK',
          wcx,
          wcy,
          centerW * 0.84,
          ch * 0.40,
          0.11,
          p * 1.35 + 0.2,
          1,
          COLORS.surfaceMid,
          COLORS.gold,
          minSide * 0.0032
        );
        ctx.restore();

        // Lower Clear Zone (64%..92%): Champagne Rose CTA Pill "VIP ACCESS" + Chevron Circle
        const pillW = Math.min(centerW * 0.74, minSide * 0.62);
        const pillH = ch * 0.26;
        const pillX = centerX + (centerW - pillW) * 0.5;
        const pillY = cy + ch * 0.64;
        fillRoundRect(pillX, pillY, pillW, pillH, pillH * 0.5, COLORS.rose);

        const ctaFs = fitFontSize('VIP ACCESS', pillW * 0.56, pillH * 0.54, minSide * 0.044, '900');
        ctx.font = '900 ' + ctaFs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('VIP ACCESS').width;
        const iconR = pillH * 0.34;
        const iconGap = minSide * 0.02;
        const lockW = tw + iconGap + iconR * 2;
        const startLX = pillX + (pillW - lockW) * 0.5;

        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('VIP ACCESS', startLX, pillY + pillH * 0.52);

        const icx = startLX + tw + iconGap + iconR;
        const icy = pillY + pillH * 0.5;
        ctx.beginPath();
        ctx.arc(icx, icy, iconR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();
        drawChevron(icx + Math.sin(p * Math.PI * 4) * iconR * 0.1, icy, iconR * 0.38, minSide * 0.0055, 1, COLORS.gold);
      }, mCenter.innerAlpha);
    }

    const mSideR = getCardMotion(p, 0.04, 0.01);
    if (mSideR.vis > 0.01) {
      const curW = sideW * mSideR.cardVis;
      const curX = rightColX + (sideW - curW);
      drawClippedCard(curX, midY, curW, midH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const sealCX = rightColX + sideW * 0.5;
        const sealCY = cy + ch * 0.42;
        const sealR = Math.min(sideW, ch) * 0.32;
        drawOctagonSeal(sealCX, sealCY, sealR, p * Math.PI * 0.5, COLORS.gold);
        const sfs = fitFontSize('VIP', sealR * 1.15, sealR * 0.85, minSide * 0.04, '900');
        ctx.font = '900 ' + sfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('VIP', sealCX, sealCY + minSide * 0.002);

        const lfs = fitFontSize('ELITE', sideW * 0.72, ch * 0.12, minSide * 0.025, '800');
        ctx.font = '800 ' + lfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.fillText('ELITE', sealCX, cy + ch * 0.80);
      }, mSideR.innerAlpha);
    }

    // Row 2: Bottom Finale Footer Bar
    const mBot = getCardMotion(p, 0.09, 0.0);
    if (mBot.vis > 0.01) {
      const curW = stageW * mBot.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, botY, curW, botH, botH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('MEMBER PRIVILEGE  •  EXPIRES TONIGHT', stageW * 0.54, ch * 0.52, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('MEMBER PRIVILEGE  •  EXPIRES TONIGHT', stageX + stageW * 0.5, cy + ch * 0.52);

        const lineW = stageW * 0.14;
        const lineH = minSide * 0.0055;
        fillRoundRect(stageX + minSide * 0.04, cy + (ch - lineH) * 0.5, lineW, lineH, lineH * 0.5, COLORS.gold);
        fillRoundRect(stageX + stageW - minSide * 0.04 - lineW, cy + (ch - lineH) * 0.5, lineW, lineH, lineH * 0.5, COLORS.gold);
      }, mBot.innerAlpha);
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#08291F',
    surface: '#0E3B2D',
    surfaceMid: '#14523E',
    mint: '#B8FFE0',
    tangerine: '#FF7A2F',
    cream: '#F4FFF9',
    muted: '#86CCA8',
    topo: '#124736',
    dot: '#134D3B'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01 || w <= 0.5 || h <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawFourPointDiamond(cx, cy, outerR, innerR, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const a = (i * Math.PI) / 4;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawForwardArrow(cx, cy, size, strokeW, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.beginPath();
    ctx.moveTo(-size * 0.55, 0);
    ctx.lineTo(size * 0.45, 0);
    ctx.moveTo(size * 0.05, -size * 0.42);
    ctx.lineTo(size * 0.52, 0);
    ctx.lineTo(size * 0.05, size * 0.42);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  // Smooth curve point sampler with arc-length lookup table for true tangent text-on-path
  function buildCurveTable(sampleCount, pointFn) {
    const pts = [];
    const cumLen = [0];
    let total = 0;
    for (let i = 0; i <= sampleCount; i++) {
      const u = i / sampleCount;
      const p = pointFn(u);
      pts.push(p);
      if (i > 0) {
        const dx = p.x - pts[i - 1].x;
        const dy = p.y - pts[i - 1].y;
        total += Math.sqrt(dx * dx + dy * dy);
        cumLen.push(total);
      }
    }
    return { pts: pts, cumLen: cumLen, total: total, n: sampleCount };
  }

  function sampleAtDist(table, dist) {
    const d = clamp(dist, 0, table.total);
    let lo = 0;
    let hi = table.n;
    while (lo < hi - 1) {
      const mid = (lo + hi) >> 1;
      if (table.cumLen[mid] <= d) lo = mid;
      else hi = mid;
    }
    const d0 = table.cumLen[lo];
    const d1 = table.cumLen[hi];
    const frac = d1 > d0 ? (d - d0) / (d1 - d0) : 0;
    const p0 = table.pts[lo];
    const p1 = table.pts[hi];
    const x = lerp(p0.x, p1.x, frac);
    const y = lerp(p0.y, p1.y, frac);
    // Smooth centered finite difference angle over neighboring samples
    const prevIdx = Math.max(0, lo - 1);
    const nextIdx = Math.min(table.n, hi + 1);
    const dx = table.pts[nextIdx].x - table.pts[prevIdx].x;
    const dy = table.pts[nextIdx].y - table.pts[prevIdx].y;
    const angle = Math.atan2(dy, dx);
    return { x: x, y: y, angle: angle, nx: -Math.sin(angle), ny: Math.cos(angle) };
  }

  // Draw crisp flat rounded-end ribbon following any monotonic smooth curve table
  function drawRibbonAlongTable(table, startDist, endDist, halfW, fillColor) {
    const s0 = clamp(startDist, 0, table.total);
    const s1 = clamp(endDist, 0, table.total);
    if (s1 - s0 <= halfW * 0.6 || halfW <= 1) return;

    const steps = 64;
    const topPts = [];
    const botPts = [];
    for (let i = 0; i <= steps; i++) {
      const d = lerp(s0, s1, i / steps);
      const sp = sampleAtDist(table, d);
      topPts.push({ x: sp.x + sp.nx * halfW, y: sp.y + sp.ny * halfW });
      botPts.push({ x: sp.x - sp.nx * halfW, y: sp.y - sp.ny * halfW });
    }
    const endSp = sampleAtDist(table, s1);
    const startSp = sampleAtDist(table, s0);

    ctx.beginPath();
    ctx.moveTo(topPts[0].x, topPts[0].y);
    for (let i = 1; i <= steps; i++) {
      ctx.lineTo(topPts[i].x, topPts[i].y);
    }
    ctx.arc(endSp.x, endSp.y, halfW, endSp.angle + Math.PI * 0.5, endSp.angle - Math.PI * 0.5, true);
    for (let i = steps; i >= 0; i--) {
      ctx.lineTo(botPts[i].x, botPts[i].y);
    }
    ctx.arc(startSp.x, startSp.y, halfW, startSp.angle - Math.PI * 0.5, startSp.angle + Math.PI * 0.5, true);
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();
  }

  // Draw text along centerline strictly bounded inside [startDist + pad, endDist - pad]
  function drawTextOnCurve(table, startDist, endDist, phrase, fontSize, weight, tracking, scrollPx, color, pad) {
    const s0 = clamp(startDist + pad, 0, table.total);
    const s1 = clamp(endDist - pad, 0, table.total);
    if (s1 - s0 < fontSize * 1.2) return;

    ctx.save();
    ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Clip vertically/horizontally to a slightly padded ribbon envelope via curve boundary
    const chars = phrase.split('');
    const charWidths = [];
    let unitLen = 0;
    for (let i = 0; i < chars.length; i++) {
      const cw = ctx.measureText(chars[i]).width;
      const step = cw * 1.04 + tracking;
      charWidths.push({ ch: chars[i], cw: cw, step: step });
      unitLen += step;
    }
    if (unitLen <= 1) {
      ctx.restore();
      return;
    }

    const offset = ((scrollPx % unitLen) + unitLen) % unitLen;
    const fadeZone = Math.min((s1 - s0) * 0.25, fontSize * 1.55);
    let cursor = s0 - offset;
    let idx = 0;
    while (cursor < s1 + unitLen) {
      const item = charWidths[idx % charWidths.length];
      const charCenter = cursor + item.cw * 0.5;
      if (charCenter >= s0 + item.cw * 0.4 && charCenter <= s1 - item.cw * 0.4) {
        const endFade = clamp((charCenter - s0) / fadeZone, 0, 1) * clamp((s1 - charCenter) / fadeZone, 0, 1);
        if (endFade > 0.02) {
          const sp = sampleAtDist(table, charCenter);
          ctx.save();
          ctx.globalAlpha *= easeOutCubic(endFade);
          ctx.translate(sp.x, sp.y);
          ctx.rotate(sp.angle);
          ctx.fillText(item.ch, 0, fontSize * 0.03);
          ctx.restore();
        }
      }
      cursor += item.step;
      idx++;
      if (idx > 600) break;
    }
    ctx.restore();
  }

  // Standardized crisp entrance/exit timing that completes cleanly by p = 0.97
  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.17;
    const exitDur = 0.17;
    const inU = clamp((p - enterDelay) / enterDur, 0, 1);
    const outU = clamp((p - (0.80 - exitDelay)) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Flat Deep Forest Emerald Background (Zero glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Smooth Vector Topographic Contour Lines across Central Stage (Seamless 2-cycle loop)
  const bandH = height * 0.088;
  const loopAngle = 2 * Math.PI * (safeLoopT / duration);
  const topoPhase = loopAngle * 2;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, bandH, width, height - bandH * 2);
  ctx.clip();

  const topoCount = 6;
  ctx.strokeStyle = COLORS.topo;
  ctx.lineWidth = minSide * 0.0022;
  for (let i = 0; i < topoCount; i++) {
    const baseY = lerp(bandH + height * 0.09, height - bandH - height * 0.09, i / (topoCount - 1));
    const segs = 44;
    ctx.beginPath();
    for (let s = 0; s <= segs; s++) {
      const u = s / segs;
      const px = u * width;
      const py =
        baseY +
        Math.sin(u * Math.PI * 3.5 + topoPhase + i * 0.9) * (height * 0.028) +
        Math.cos(u * Math.PI * 2.0 - loopAngle + i * 1.3) * (height * 0.015);
      if (s === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }

  // Subtle flat botanical grid dots inside central field
  const dotCols = 14;
  const dotRows = 6;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < dotRows; r++) {
    const dy = lerp(height * 0.16, height - height * 0.16, r / (dotRows - 1));
    for (let c = 0; c < dotCols; c++) {
      const dx = lerp(width * 0.08, width * 0.92, c / (dotCols - 1));
      const pulse = 0.5 + 0.5 * Math.sin(topoPhase + c * 0.4 + r * 0.7);
      const rad = minSide * (0.002 + pulse * 0.0009);
      ctx.beginPath();
      ctx.arc(dx, dy, rad, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();

  // 3. Persistent Flat Top & Bottom Seasonal Marquee Tracks (Seamless exact loop)
  function drawMarqueeTrack(y, h, text, speedDir, bgCol, textCol, dotCol) {
    ctx.fillStyle = bgCol;
    ctx.fillRect(0, y, width, h);

    const fontSize = fitFontSize('M', width, h * 0.44, minSide * 0.022, '800');
    ctx.save();
    ctx.font = '800 ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    const parts = text.split('•');
    let unitW = 0;
    const itemWidths = [];
    const padX = fontSize * 1.1;
    for (let i = 0; i < parts.length; i++) {
      const seg = parts[i].trim();
      const sw = ctx.measureText(seg).width;
      itemWidths.push({ seg: seg, w: sw });
      unitW += sw + padX * 2;
    }

    const totalTravel = unitW * Math.max(1, Math.round((width * 1.4) / unitW));
    const travelDist = (safeLoopT / duration) * totalTravel * speedDir;
    let startX = ((travelDist % unitW) - unitW) % unitW;
    if (startX > 0) startX -= unitW;

    let curX = startX;
    let idx = 0;
    const midY = y + h * 0.52;
    while (curX < width + unitW) {
      const item = itemWidths[idx % itemWidths.length];
      ctx.fillStyle = textCol;
      ctx.fillText(item.seg, curX, midY);
      ctx.fillStyle = dotCol;
      ctx.beginPath();
      ctx.arc(curX + item.w + padX, midY - fontSize * 0.03, fontSize * 0.14, 0, Math.PI * 2);
      ctx.fill();
      curX += item.w + padX * 2;
      idx++;
    }
    ctx.restore();
  }

  drawMarqueeTrack(
    0,
    bandH,
    'NEW ARRIVAL   •   SEASONAL DROP   •   FRESH COLLECTION   •   25% OFF TODAY   •   ',
    1,
    COLORS.surface,
    COLORS.cream,
    COLORS.tangerine
  );
  drawMarqueeTrack(
    height - bandH,
    bandH,
    'ORGANIC EDIT   •   LIMITED RELEASE   •   SHOP THE SEASON   •   FREE SHIPPING   •   ',
    -1,
    COLORS.surface,
    COLORS.mint,
    COLORS.tangerine
  );

  // Safe interior stage margins with ample air around top & bottom tracks
  const stageX = width * 0.065;
  const stageW = width * 0.87;
  const stageY = height * 0.132;
  const stageH = height * 0.736;
  const gutter = minSide * 0.024;
  const cardR = minSide * 0.024;

  // Seamless anchor pill at scene boundaries (p=0 / p=1)
  const anchorAlpha =
    sceneProgress < 0.14
      ? 1 - easeOutCubic(sceneProgress / 0.14)
      : sceneProgress > 0.86
      ? easeInCubic((sceneProgress - 0.86) / 0.14)
      : 0;
  if (anchorAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha = anchorAlpha;
    const barW = stageW * 0.25 * anchorAlpha;
    const barH = minSide * 0.007;
    fillRoundRect(width * 0.5 - barW * 0.5, height * 0.5 - barH * 0.5, barW, barH, barH * 0.5, COLORS.mint);
    ctx.restore();
  }

  const p = sceneProgress;

  if (sceneIdx === 0) {
    // SCENE 0: "NEW ARRIVAL" — Dual Counter-Flowing S-Curve Text-on-Path Ribbons
    const metaH = stageH * 0.11;
    const bandTopY = stageY + stageH * 0.16;
    const bandTopH = stageH * 0.29;
    const bandBotY = stageY + stageH * 0.51;
    const bandBotH = stageH * 0.29;
    const footY = stageY + stageH * 0.86;
    const footH = stageH * 0.14;

    // Row 0: Editorial Meta Pills + Rotating Botanical Diamonds
    const mMeta = getCardMotion(p, 0.0, 0.04);
    if (mMeta.vis > 0.01) {
      const leftPillW = stageW * 0.23;
      const rightPillW = stageW * 0.14;
      const slideY = mMeta.slideOffset * minSide * 0.028;

      ctx.save();
      ctx.globalAlpha = mMeta.vis;
      drawClippedCard(stageX, stageY + slideY, leftPillW, metaH, metaH * 0.5, COLORS.tangerine, (cx, cy, cw, ch) => {
        const fs = fitFontSize('SEASONAL EDIT', cw * 0.82, ch * 0.48, minSide * 0.023, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SEASONAL EDIT', cx + cw * 0.5, cy + ch * 0.52);
      });

      const midStart = stageX + leftPillW + gutter * 2;
      const midEnd = stageX + stageW - rightPillW - gutter * 2;
      const dotCount = 5;
      for (let d = 0; d < dotCount; d++) {
        const dx = lerp(midStart, midEnd, d / (dotCount - 1));
        const dy = stageY + metaH * 0.5 + slideY;
        const rot = p * Math.PI * 2 + d * 0.4;
        const col = d % 2 === 0 ? COLORS.mint : COLORS.tangerine;
        drawFourPointDiamond(dx, dy, metaH * 0.22, metaH * 0.09, rot, col);
      }

      drawClippedCard(stageX + stageW - rightPillW, stageY + slideY, rightPillW, metaH, metaH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('01 / 03', cw * 0.72, ch * 0.48, minSide * 0.023, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('01 / 03', cx + cw * 0.5, cy + ch * 0.52);
      });
      ctx.restore();
    }

    // Upper S-Curve Mint Cream Ribbon ("NEW ARRIVAL") — cleanly confined inside bandTopY..bandTopY+bandTopH
    const mRib1 = getCardMotion(p, 0.03, 0.02);
    if (mRib1.vis > 0.01) {
      const ribHalfW = bandTopH * 0.34;
      const centerTopY = bandTopY + bandTopH * 0.5;
      const ampTop = bandTopH * 0.5 - ribHalfW * 1.12;
      const padX = ribHalfW * 1.05;
      const table1 = buildCurveTable(180, (u) => {
        const px = lerp(stageX + padX, stageX + stageW - padX, u);
        const py = centerTopY + Math.sin(u * Math.PI * 2 + p * Math.PI * 2) * ampTop;
        return { x: px, y: py };
      });

      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(mRib1.vis / 0.22, 0, 1));
      const drawLen1 = table1.total * mRib1.cardVis;
      const sStart1 = (table1.total - drawLen1) * 0.5;
      const sEnd1 = sStart1 + drawLen1;
      drawRibbonAlongTable(table1, sStart1, sEnd1, ribHalfW, COLORS.mint);

      if (mRib1.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= mRib1.innerAlpha;
        const tSize = Math.min(ribHalfW * 0.95, minSide * 0.048);
        const scroll1 = p * table1.total * 0.45;
        drawTextOnCurve(
          table1,
          sStart1,
          sEnd1,
          'NEW ARRIVAL   •   SPRING DROP   •   ',
          tSize,
          '900',
          tSize * 0.08,
          scroll1,
          COLORS.bg,
          ribHalfW * 0.75
        );
        ctx.restore();
      }
      ctx.restore();
    }

    // Lower Counter-Phase S-Curve Tangerine Ribbon ("SEASONAL COLLECTION") — strictly separated gap
    const mRib2 = getCardMotion(p, 0.07, 0.0);
    if (mRib2.vis > 0.01) {
      const ribHalfW = bandBotH * 0.34;
      const centerBotY = bandBotY + bandBotH * 0.5;
      const ampBot = bandBotH * 0.5 - ribHalfW * 1.12;
      const padX = ribHalfW * 1.05;
      const table2 = buildCurveTable(180, (u) => {
        const px = lerp(stageX + padX, stageX + stageW - padX, u);
        const py = centerBotY - Math.sin(u * Math.PI * 2 + p * Math.PI * 2 + 0.6) * ampBot;
        return { x: px, y: py };
      });

      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(mRib2.vis / 0.22, 0, 1));
      const drawLen2 = table2.total * mRib2.cardVis;
      const sStart2 = (table2.total - drawLen2) * 0.5;
      const sEnd2 = sStart2 + drawLen2;
      drawRibbonAlongTable(table2, sStart2, sEnd2, ribHalfW, COLORS.tangerine);

      if (mRib2.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= mRib2.innerAlpha;
        const tSize = Math.min(ribHalfW * 0.95, minSide * 0.048);
        const scroll2 = -p * table2.total * 0.42;
        drawTextOnCurve(
          table2,
          sStart2,
          sEnd2,
          'CURATED PIECES   •   ORGANIC EDIT   •   ',
          tSize,
          '900',
          tSize * 0.08,
          scroll2,
          COLORS.cream,
          ribHalfW * 0.75
        );
        ctx.restore();
      }
      ctx.restore();
    }

    // Bottom Clean Editorial Capsule Footer
    const mFoot = getCardMotion(p, 0.10, 0.02);
    if (mFoot.vis > 0.01) {
      const curW = stageW * mFoot.cardVis;
      const curX = stageX + (stageW - curW) * 0.5;
      drawClippedCard(curX, footY, curW, footH, footH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('BOTANICAL CAPSULE  •  LIMITED BATCH', stageW * 0.52, ch * 0.52, minSide * 0.026, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cream;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('BOTANICAL CAPSULE  •  LIMITED BATCH', stageX + stageW * 0.5, cy + ch * 0.52);

        const barW = stageW * 0.14;
        const barH = minSide * 0.008;
        const pulse = 0.65 + 0.35 * Math.sin(p * Math.PI * 2);
        fillRoundRect(stageX + minSide * 0.045, cy + (ch - barH) * 0.5, barW * pulse, barH, barH * 0.5, COLORS.mint);
        fillRoundRect(stageX + stageW - minSide * 0.045 - barW * pulse, cy + (ch - barH) * 0.5, barW * pulse, barH, barH * 0.5, COLORS.tangerine);
      }, mFoot.innerAlpha);
    }
  } else if (sceneIdx === 1) {
    // SCENE 1: "FRESH COLLECTION" — Parallel Ribbons Framing Editorial Centerpiece & Gliding Tangerine Arrows
    const topRibBandH = stageH * 0.19;
    const midY = stageY + stageH * 0.24;
    const midH = stageH * 0.52;
    const botRibBandY = stageY + stageH * 0.81;
    const botRibBandH = stageH * 0.19;

    // Top Parallel Mint Wave Ribbon
    const mTopR = getCardMotion(p, 0.0, 0.02);
    if (mTopR.vis > 0.01) {
      const halfW = topRibBandH * 0.42;
      const centerTopY = stageY + topRibBandH * 0.5;
      const amp = topRibBandH * 0.5 - halfW * 1.1;
      const padX = halfW * 1.05;
      const tTop = buildCurveTable(160, (u) => ({
        x: lerp(stageX + padX, stageX + stageW - padX, u),
        y: centerTopY + Math.sin(u * Math.PI * 3 + p * Math.PI * 2) * amp
      }));
      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(mTopR.vis / 0.22, 0, 1));
      const len = tTop.total * mTopR.cardVis;
      drawRibbonAlongTable(tTop, 0, len, halfW, COLORS.mint);
      if (mTopR.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= mTopR.innerAlpha;
        const tSize = Math.min(halfW * 0.9, minSide * 0.036);
        drawTextOnCurve(
          tTop,
          0,
          len,
          'SEASONAL FAVORITES   •   FRESH DROP   •   ',
          tSize,
          '900',
          tSize * 0.07,
          p * tTop.total * 0.38,
          COLORS.bg,
          halfW * 0.7
        );
        ctx.restore();
      }
      ctx.restore();
    }

    // Center Split Card ("FRESH COLLECTION") + Right Arrow Conveyor Track
    const leftW = stageW * 0.68 - gutter * 0.5;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;

    const mMidL = getCardMotion(p, 0.04, 0.01);
    if (mMidL.vis > 0.01) {
      const curW = leftW * mMidL.cardVis;
      drawClippedCard(stageX, midY, curW, midH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.045;
        const innerW = leftW - pad * 2;
        const badgeW = leftW * 0.34;
        const badgeH = midH * 0.16;

        fillRoundRect(cx + pad, cy + pad, badgeW, badgeH, badgeH * 0.5, COLORS.tangerine);
        const bfs = fitFontSize('02 / 03 • EDITION', badgeW * 0.84, badgeH * 0.52, minSide * 0.021, '900');
        ctx.font = '900 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('02 / 03 • EDITION', cx + pad + badgeW * 0.5, cy + pad + badgeH * 0.52);

        const shift = (1 - mMidL.innerAlpha) * stageW * 0.025;
        const fs1 = fitFontSize('FRESH', innerW, midH * 0.25, minSide * 0.092, '900');
        ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'left';
        ctx.fillText('FRESH', cx + pad - shift, cy + midH * 0.44);

        const fs2 = fitFontSize('COLLECTION', innerW, midH * 0.25, minSide * 0.092, '900');
        ctx.font = '900 ' + fs2 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cream;
        ctx.fillText('COLLECTION', cx + pad - shift, cy + midH * 0.69);

        const subFs = fitFontSize('ELEVATED ESSENTIALS FOR EVERYDAY RITUALS', innerW, midH * 0.1, minSide * 0.021, '700');
        ctx.font = '700 ' + subFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.muted;
        ctx.fillText('ELEVATED ESSENTIALS FOR EVERYDAY RITUALS', cx + pad, cy + midH * 0.87);
      }, mMidL.innerAlpha);
    }

    const mMidR = getCardMotion(p, 0.07, 0.0);
    if (mMidR.vis > 0.01) {
      const curH = midH * mMidR.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(rightX, curY, rightW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.04;
        const headFs = fitFontSize('NOW TRENDING', cw - pad * 2, midH * 0.12, minSide * 0.024, '800');
        ctx.font = '800 ' + headFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('NOW TRENDING', cx + cw * 0.5, midY + midH * 0.18);

        // Strictly bounded Tangerine Forward-Arrow Conveyor Pill inside center of panel
        const trackW = cw - pad * 2;
        const trackH = midH * 0.34;
        const trackX = cx + pad;
        const trackY = midY + midH * 0.34;
        drawClippedCard(trackX, trackY, trackW, trackH, trackH * 0.5, COLORS.bg, (tx, ty, tw, th) => {
          const unitStep = tw / 3;
          const scrollX = (p * 1.5 % 1) * unitStep;
          const arrowSize = Math.min(unitStep * 0.38, th * 0.44);
          for (let k = -1; k <= 3; k++) {
            const ax = tx + (k + 0.5) * unitStep + scrollX;
            if (ax > tx + arrowSize * 0.55 && ax < tx + tw - arrowSize * 0.55) {
              drawForwardArrow(ax, ty + th * 0.5, arrowSize, minSide * 0.0085, COLORS.tangerine);
            }
          }
        });

        const footFs = fitFontSize('NEW SEASON EDIT', cw - pad * 2, midH * 0.12, minSide * 0.022, '800');
        ctx.font = '800 ' + footFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cream;
        ctx.fillText('NEW SEASON EDIT', cx + cw * 0.5, midY + midH * 0.83);
      }, mMidR.innerAlpha);
    }

    // Bottom Parallel Tangerine Wave Ribbon
    const mBotR = getCardMotion(p, 0.02, 0.03);
    if (mBotR.vis > 0.01) {
      const halfW = botRibBandH * 0.42;
      const centerBotY = botRibBandY + botRibBandH * 0.5;
      const amp = botRibBandH * 0.5 - halfW * 1.1;
      const padX = halfW * 1.05;
      const tBot = buildCurveTable(160, (u) => ({
        x: lerp(stageX + padX, stageX + stageW - padX, u),
        y: centerBotY - Math.sin(u * Math.PI * 3 + p * Math.PI * 2 + 0.8) * amp
      }));
      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(mBotR.vis / 0.22, 0, 1));
      const len = tBot.total * mBotR.cardVis;
      const startD = tBot.total - len;
      drawRibbonAlongTable(tBot, startD, tBot.total, halfW, COLORS.tangerine);
      if (mBotR.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= mBotR.innerAlpha;
        const tSize = Math.min(halfW * 0.9, minSide * 0.036);
        drawTextOnCurve(
          tBot,
          startD,
          tBot.total,
          'LIMITED BATCH   •   CRAFTED NATURALLY   •   ',
          tSize,
          '900',
          tSize * 0.07,
          -p * tBot.total * 0.36,
          COLORS.cream,
          halfW * 0.7
        );
        ctx.restore();
      }
      ctx.restore();
    }
  } else {
    // SCENE 2: "25% OFF TODAY" — Open Oval Arch Track Wrapping Center Card & Unfurling Flat for Loop Reset
    // Arch factor smoothly swells into deep oval track and uncoils flat at exit!
    const archFactor =
      p < 0.25
        ? easeOutCubic(p / 0.25)
        : p > 0.75
        ? 1 - easeInCubic((p - 0.75) / 0.25)
        : 1;

    const topRibbonMotion = getCardMotion(p, 0.0, 0.02);
    const botRibbonMotion = getCardMotion(p, 0.02, 0.02);
    const centerCardMotion = getCardMotion(p, 0.06, 0.04);

    // Clear geometric separation:
    // Top Arch Ribbon strictly occupies stageY .. stageY + stageH * 0.22
    // Center Showcase Card strictly occupies stageY + stageH * 0.26 .. stageY + stageH * 0.74
    // Bottom Arch Ribbon strictly occupies stageY + stageH * 0.78 .. stageY + stageH
    const halfW = minSide * 0.033;
    const padX = halfW * 1.1;

    if (topRibbonMotion.vis > 0.01) {
      const flatY = stageY + stageH * 0.11;
      const curveDip = stageH * 0.105 * archFactor;
      const tUpper = buildCurveTable(160, (u) => {
        const px = lerp(stageX + padX, stageX + stageW - padX, u);
        // Arch upward in the middle like upper half of an open oval (symmetric bell)
        const bell = Math.cos((u - 0.5) * Math.PI);
        const py = flatY + curveDip * 0.55 - bell * curveDip;
        return { x: px, y: py };
      });

      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(topRibbonMotion.vis / 0.22, 0, 1));
      const drawLen = tUpper.total * topRibbonMotion.cardVis;
      const s0 = (tUpper.total - drawLen) * 0.5;
      drawRibbonAlongTable(tUpper, s0, s0 + drawLen, halfW, COLORS.mint);
      if (topRibbonMotion.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= topRibbonMotion.innerAlpha;
        const tSize = Math.min(halfW * 0.92, minSide * 0.034);
        drawTextOnCurve(
          tUpper,
          s0,
          s0 + drawLen,
          'SEASONAL CELEBRATION   •   UP TO 25% OFF   •   ',
          tSize,
          '900',
          tSize * 0.07,
          p * tUpper.total * 0.42,
          COLORS.bg,
          halfW * 0.7
        );
        ctx.restore();
      }
      ctx.restore();
    }

    if (botRibbonMotion.vis > 0.01) {
      const flatY = stageY + stageH * 0.89;
      const curveDip = stageH * 0.105 * archFactor;
      const tLower = buildCurveTable(160, (u) => {
        const px = lerp(stageX + padX, stageX + stageW - padX, u);
        const bell = Math.cos((u - 0.5) * Math.PI);
        const py = flatY - curveDip * 0.55 + bell * curveDip;
        return { x: px, y: py };
      });

      ctx.save();
      ctx.globalAlpha = easeOutCubic(clamp(botRibbonMotion.vis / 0.22, 0, 1));
      const drawLen = tLower.total * botRibbonMotion.cardVis;
      const s0 = (tLower.total - drawLen) * 0.5;
      drawRibbonAlongTable(tLower, s0, s0 + drawLen, halfW, COLORS.tangerine);
      if (botRibbonMotion.innerAlpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= botRibbonMotion.innerAlpha;
        const tSize = Math.min(halfW * 0.92, minSide * 0.034);
        drawTextOnCurve(
          tLower,
          s0,
          s0 + drawLen,
          'LIMITED TIME OFFER   •   ONLINE STORE   •   ',
          tSize,
          '900',
          tSize * 0.07,
          -p * tLower.total * 0.42,
          COLORS.cream,
          halfW * 0.7
        );
        ctx.restore();
      }
      ctx.restore();
    }

    // Center Showcase Window strictly bounded inside stageY + stageH * 0.27 .. 0.73 (>= 40px gap from arches!)
    if (centerCardMotion.vis > 0.01) {
      const fullW = stageW * 0.76;
      const fullH = stageH * 0.44;
      const curW = fullW * centerCardMotion.cardVis;
      const curH = fullH;
      const curX = width * 0.5 - curW * 0.5;
      const curY = stageY + stageH * 0.5 - curH * 0.5;

      drawClippedCard(curX, curY, curW, curH, cardR * 1.15, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.04;
        const leftBadgeW = minSide * 0.14;
        const badgeH = minSide * 0.052;
        const pillX = width * 0.5 - fullW * 0.5 + pad;
        const pillY = cy + pad;

        fillRoundRect(pillX, pillY, leftBadgeW, badgeH, badgeH * 0.5, COLORS.surfaceMid);
        const bfs = fitFontSize('03 / 03', leftBadgeW * 0.78, badgeH * 0.52, minSide * 0.022, '800');
        ctx.font = '800 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.mint;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('03 / 03', pillX + leftBadgeW * 0.5, pillY + badgeH * 0.52);

        const rightTagW = minSide * 0.22;
        const rPillX = width * 0.5 + fullW * 0.5 - pad - rightTagW;
        fillRoundRect(rPillX, pillY, rightTagW, badgeH, badgeH * 0.5, COLORS.tangerine);
        const rfs = fitFontSize('SEASONAL FINAL', rightTagW * 0.84, badgeH * 0.52, minSide * 0.021, '900');
        ctx.font = '900 ' + rfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.fillText('SEASONAL FINAL', rPillX + rightTagW * 0.5, pillY + badgeH * 0.52);

        // Hero Unified Lockup: "25% OFF TODAY" + Action Circle
        const headline = '25% OFF TODAY';
        const hSize = fitFontSize(headline, fullW * 0.62, ch * 0.42, minSide * 0.088, '900');
        ctx.font = '900 ' + hSize + 'px ' + FONT_FAMILY;
        const textW = ctx.measureText(headline).width;
        const iconR = minSide * 0.046;
        const iconGap = minSide * 0.028;
        const lockupW = textW + iconGap + iconR * 2;
        const startLX = width * 0.5 - lockupW * 0.5;
        const heroY = cy + ch * 0.58;

        ctx.fillStyle = COLORS.cream;
        ctx.textAlign = 'left';
        ctx.fillText(headline, startLX, heroY);

        const icx = startLX + textW + iconGap + iconR;
        ctx.beginPath();
        ctx.arc(icx, heroY, iconR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.mint;
        ctx.fill();

        const pulse = Math.sin(p * Math.PI * 4) * iconR * 0.1;
        drawChevron(icx + pulse, heroY, iconR * 0.38, minSide * 0.007, 1, COLORS.bg);

        // Bottom clean caption inside card
        const footFs = fitFontSize('NO CODE NEEDED  •  AUTOMATIC SAVINGS AT CHECKOUT', fullW * 0.8, ch * 0.1, minSide * 0.021, '700');
        ctx.font = '700 ' + footFs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.muted;
        ctx.textAlign = 'center';
        ctx.fillText('NO CODE NEEDED  •  AUTOMATIC SAVINGS AT CHECKOUT', width * 0.5, cy + ch * 0.85);
      }, centerCardMotion.innerAlpha);
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#1638F5',
    sapphire: '#0E26B8',
    navy: '#0A1C8C',
    gold: '#FFD426',
    white: '#FFFFFF',
    ice: '#D6E2FF',
    dot: '#284BFF',
    rule: '#3256FF'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  // Gentle balanced spring settle (max ~3% natural overshoot, zero erratic bounce)
  function easeOutGentleSpring(u) {
    const x = clamp(u, 0, 1);
    const base = 1 - Math.pow(1 - x, 3);
    const settle = Math.sin(x * Math.PI * 2) * (1 - x) * 0.04;
    return clamp(base + settle, 0, 1.035);
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01 || w <= 0.5 || h <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawFourPointStar(cx, cy, outerR, innerR, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const a = (i * Math.PI) / 4;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawSerratedSeal(cx, cy, outerR, innerR, teeth, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    const total = teeth * 2;
    for (let i = 0; i < total; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const a = (i * Math.PI * 2) / total;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawDiamond(cx, cy, r, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, -r);
    ctx.lineTo(r * 0.75, 0);
    ctx.lineTo(0, r);
    ctx.lineTo(-r * 0.75, 0);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawPlus(cx, cy, armLen, thickness, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    fillRoundRect(-armLen, -thickness * 0.5, armLen * 2, thickness, thickness * 0.5, color);
    fillRoundRect(-thickness * 0.5, -armLen, thickness, armLen * 2, thickness * 0.5, color);
    ctx.restore();
  }

  function drawTextSpaced(text, cx, cy, fontSize, weight, color, extraTracking) {
    ctx.save();
    ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.fillStyle = color;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const chars = text.split('');
    let totalW = 0;
    const widths = [];
    for (let i = 0; i < chars.length; i++) {
      const cw = ctx.measureText(chars[i]).width;
      widths.push(cw);
      totalW += cw + (i < chars.length - 1 ? extraTracking : 0);
    }
    let cursorX = cx - totalW * 0.5;
    for (let i = 0; i < chars.length; i++) {
      ctx.fillText(chars[i], cursorX, cy);
      cursorX += widths[i] + extraTracking;
    }
    ctx.restore();
  }

  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.17;
    const exitDur = 0.17;
    const inU = clamp((p - enterDelay) / enterDur, 0, 1);
    const outU = clamp((p - (0.80 - exitDelay)) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Flat Crisp Royal Cobalt Background (Zero glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Subtle Flat Geometric Micro-Grid (Seamless 2-cycle loop, crisp vector circles)
  const bandH = height * 0.095;
  const gridCols = 14;
  const gridRows = 6;
  const gridLeft = width * 0.08;
  const gridRight = width * 0.92;
  const gridTop = height * 0.16;
  const gridBottom = height * 0.84;
  const dotPhase = 2 * Math.PI * (safeLoopT / duration) * 2;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < gridRows; r++) {
    const dy = lerp(gridTop, gridBottom, r / (gridRows - 1));
    for (let c = 0; c < gridCols; c++) {
      const dx = lerp(gridLeft, gridRight, c / (gridCols - 1));
      const wave = 0.5 + 0.5 * Math.sin(dotPhase + c * 0.45 + r * 0.35);
      const rad = minSide * (0.0024 + 0.0014 * wave);
      ctx.beginPath();
      ctx.arc(dx, dy, rad, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 3. Top & Bottom Continuous Kinetic Ticker Channels (Full-bleed, no outer edge border strokes)
  function drawTickerBand(y, h, text, dir, bgColor, textColor, dotColor) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y, width, h);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();

    const fs = h * 0.36;
    ctx.font = '700 ' + fs + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const tileW = ctx.measureText(text).width;
    if (tileW > 0) {
      const shift = (safeLoopT / duration) * tileW * 2 * dir;
      let sx = ((shift % tileW) + tileW) % tileW - tileW;
      const cy = y + h * 0.52;
      while (sx < width + tileW) {
        const parts = text.split('•');
        let cx = sx;
        for (let i = 0; i < parts.length; i++) {
          ctx.fillStyle = textColor;
          ctx.fillText(parts[i], cx, cy);
          cx += ctx.measureText(parts[i]).width;
          if (i < parts.length - 1) {
            const dw = ctx.measureText('•').width;
            ctx.fillStyle = dotColor;
            ctx.beginPath();
            ctx.arc(cx + dw * 0.5, y + h * 0.5, minSide * 0.0045, 0, Math.PI * 2);
            ctx.fill();
            cx += dw;
          }
        }
        sx += tileW;
      }
    }
    ctx.restore();
  }

  drawTickerBand(
    0,
    bandH,
    'MEGA SALE   •   BUY 1 GET 1   •   UP TO 50% OFF   •   SPECIAL PROMO   •   ',
    -1,
    COLORS.sapphire,
    COLORS.white,
    COLORS.gold
  );

  drawTickerBand(
    height - bandH,
    bandH,
    'LIMITED STOCK   •   BEST VALUE   •   ONLINE STORE   •   GRAB IT FAST   •   ',
    1,
    COLORS.sapphire,
    COLORS.ice,
    COLORS.gold
  );

  const stageX = width * 0.065;
  const stageW = width * 0.87;
  const stageY = height * 0.14;
  const stageH = height * 0.72;
  const gutter = minSide * 0.024;
  const cardR = minSide * 0.024;

  // Seamless bridge indicator at p=0 and p=1
  const anchorAlpha =
    sceneProgress < 0.14
      ? 1 - easeOutCubic(sceneProgress / 0.14)
      : sceneProgress > 0.86
      ? easeInCubic((sceneProgress - 0.86) / 0.14)
      : 0;
  if (anchorAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha = anchorAlpha;
    const barW = stageW * 0.26 * anchorAlpha;
    const barH = minSide * 0.007;
    fillRoundRect(width * 0.5 - barW * 0.5, height * 0.5 - barH * 0.5, barW, barH, barH * 0.5, COLORS.gold);
    ctx.restore();
  }

  const p = sceneProgress;

  if (sceneIdx === 0) {
    // SCENE 0: "MEGA SALE" — Serrated Promo Seal & Confetti Geometric Channel
    const metaH = stageH * 0.11;
    const mainY = stageY + stageH * 0.16;
    const mainH = stageH * 0.55;
    const botY = stageY + stageH * 0.76;
    const botH = stageH * 0.24;

    // Row 0: Meta Header
    const mMeta = getCardMotion(p, 0.0, 0.04);
    if (mMeta.vis > 0.001) {
      const leftPillW = stageW * 0.23;
      const rightPillW = stageW * 0.14;
      const slideY = mMeta.slideOffset * minSide * 0.03;

      ctx.save();
      ctx.globalAlpha = mMeta.vis;
      drawClippedCard(stageX, stageY + slideY, leftPillW, metaH, metaH * 0.5, COLORS.gold, (cx, cy, cw, ch) => {
        const fs = fitFontSize('BIGGEST EVENT', cw * 0.82, ch * 0.48, minSide * 0.024, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('BIGGEST EVENT', cx + cw * 0.5, cy + ch * 0.52);
      });

      // 7 evenly spaced geometric dots between pills
      const dotsStart = stageX + leftPillW + gutter * 1.5;
      const dotsEnd = stageX + stageW - rightPillW - gutter * 1.5;
      const dotCount = 7;
      for (let d = 0; d < dotCount; d++) {
        const dx = lerp(dotsStart, dotsEnd, d / (dotCount - 1));
        const wave = 0.65 + 0.35 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - d * 0.65));
        ctx.beginPath();
        ctx.arc(dx, stageY + metaH * 0.5 + slideY, minSide * 0.008 * wave, 0, Math.PI * 2);
        ctx.fillStyle = d % 2 === 0 ? COLORS.gold : COLORS.white;
        ctx.fill();
      }

      drawClippedCard(stageX + stageW - rightPillW, stageY + slideY, rightPillW, metaH, metaH * 0.5, COLORS.sapphire, (cx, cy, cw, ch) => {
        const fs = fitFontSize('01 / 04', cw * 0.72, ch * 0.48, minSide * 0.023, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.gold;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('01 / 04', cx + cw * 0.5, cy + ch * 0.52);
      });
      ctx.restore();
    }

    // Row 1: Main "MEGA SALE" Card + Rotating Serrated Rosette Seal Card
    const leftW = stageW * 0.64 - gutter * 0.5;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;
    const mHeroL = getCardMotion(p, 0.02, 0.02);
    const mHeroR = getCardMotion(p, 0.06, 0.0);

    if (mHeroL.vis > 0.001) {
      const cw = leftW * mHeroL.cardVis;
      drawClippedCard(stageX, mainY, cw, mainH, cardR, COLORS.white, (cx, cy, w, h) => {
        const pad = minSide * 0.05;
        const textShift = (1 - mHeroL.innerAlpha) * stageW * 0.025;
        const fsMega = fitFontSize('MEGA', leftW - pad * 2, mainH * 0.3, minSide * 0.12, '900');
        ctx.font = '900 ' + fsMega + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('MEGA', cx + pad - textShift, cy + mainH * 0.25);

        const fsSale = fitFontSize('SALE', leftW - pad * 2, mainH * 0.3, minSide * 0.12, '900');
        ctx.font = '900 ' + fsSale + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.fillText('SALE', cx + pad - textShift, cy + mainH * 0.52);

        // Clean bottom-left Gold Pill strictly inside lower zone (72%..92%)
        const pillW = leftW * 0.36;
        const pillH = mainH * 0.16;
        const px = cx + pad;
        const py = cy + mainH - pad - pillH;
        fillRoundRect(px, py, pillW, pillH, pillH * 0.5, COLORS.gold);
        const pfs = fitFontSize('LIMITED OFFER', pillW * 0.82, pillH * 0.52, minSide * 0.023, '900');
        ctx.font = '900 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.fillText('LIMITED OFFER', px + pillW * 0.5, py + pillH * 0.52);

        // Top-right crisp 4-point star emblem strictly in clear corner zone
        const starR = minSide * 0.036 * easeOutGentleSpring(mHeroL.innerAlpha);
        drawFourPointStar(stageX + leftW - pad - starR, cy + pad + starR, starR, starR * 0.42, p * Math.PI, COLORS.gold);
      }, mHeroL.innerAlpha);
    }

    if (mHeroR.vis > 0.001) {
      const curH = mainH * mHeroR.cardVis;
      const curY = mainY + (mainH - curH) * 0.5;
      drawClippedCard(rightX, curY, rightW, curH, cardR, COLORS.sapphire, (cx, cy, cw, ch) => {
        const sc = easeOutGentleSpring(mHeroR.innerAlpha);
        const outerR = Math.min(rightW, mainH) * 0.37 * sc;
        const innerR = outerR * 0.84;
        const rot = easeInOutQuart(p) * Math.PI * 0.5;
        const rcx = cx + cw * 0.5;
        const rcy = mainY + mainH * 0.5;
        drawSerratedSeal(rcx, rcy, outerR, innerR, 14, rot, COLORS.gold);

        const fsNum = fitFontSize('50%', innerR * 1.25, innerR * 0.72, minSide * 0.085, '900');
        ctx.font = '900 ' + fsNum + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('50%', rcx, rcy - innerR * 0.14);

        const fsOff = fitFontSize('OFF', innerR * 0.9, innerR * 0.36, minSide * 0.038, '900');
        ctx.font = '900 ' + fsOff + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.fillText('OFF', rcx, rcy + innerR * 0.34);
      }, mHeroR.innerAlpha);
    }

    // Row 2: Dedicated Confetti Showcase Card + Action Banner
    const mBotL = getCardMotion(p, 0.07, 0.02);
    const mBotR = getCardMotion(p, 0.09, 0.0);
    const botLW = stageW * 0.34 - gutter * 0.5;
    const botRX = stageX + botLW + gutter;
    const botRW = stageW - botLW - gutter;

    if (mBotL.vis > 0.001) {
      const cw = botLW * mBotL.cardVis;
      drawClippedCard(stageX, botY, cw, botH, cardR, COLORS.sapphire, (cx, cy, w, h) => {
        // 5 strictly separated 2D geometric confetti shapes oscillating gently in disjoint columns
        const pad = minSide * 0.032;
        const zoneW = botLW - pad * 2;
        const slotW = zoneW / 5;
        const shapeR = Math.min(slotW * 0.32, h * 0.18);
        for (let i = 0; i < 5; i++) {
          const sx = stageX + pad + slotW * (i + 0.5);
          const sy = cy + h * 0.5 + Math.sin(p * Math.PI * 4 - i * 0.9) * h * 0.14;
          if (i === 0 || i === 4) {
            ctx.beginPath();
            ctx.arc(sx, sy, shapeR * 0.85, 0, Math.PI * 2);
            ctx.fillStyle = i === 0 ? COLORS.gold : COLORS.white;
            ctx.fill();
          } else if (i === 1) {
            drawFourPointStar(sx, sy, shapeR * 1.15, shapeR * 0.45, p * Math.PI * 2, COLORS.white);
          } else if (i === 2) {
            ctx.save();
            ctx.translate(sx, sy);
            ctx.rotate(Math.PI * 0.25 + p * Math.PI * 2);
            fillRoundRect(-shapeR * 0.45, -shapeR, shapeR * 0.9, shapeR * 2, shapeR * 0.45, COLORS.gold);
            ctx.restore();
          } else {
            drawDiamond(sx, sy, shapeR * 1.05, p * Math.PI, COLORS.ice);
          }
        }
      }, mBotL.innerAlpha);
    }

    if (mBotR.vis > 0.001) {
      const cw = botRW * mBotR.cardVis;
      drawClippedCard(botRX + (botRW - cw), botY, cw, botH, cardR, COLORS.gold, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const btnR = Math.min(botRW * 0.1, h * 0.32);
        const gapBtn = minSide * 0.028;
        const fs = fitFontSize('STOREWIDE PROMO', botRW - pad * 2 - btnR * 2 - gapBtn, h * 0.5, minSide * 0.046, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('STOREWIDE PROMO').width;
        const groupW = tw + gapBtn + btnR * 2;
        const startX = botRX + (botRW - groupW) * 0.5;

        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('STOREWIDE PROMO', startX, cy + h * 0.52);

        const bcx = startX + tw + gapBtn + btnR;
        const bcy = cy + h * 0.5;
        ctx.beginPath();
        ctx.arc(bcx, bcy, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.navy;
        ctx.fill();

        const glide = Math.sin(p * Math.PI * 4) * btnR * 0.14;
        drawChevron(bcx + glide, bcy, btnR * 0.42, minSide * 0.007, 1, COLORS.gold);
      }, mBotR.innerAlpha);
    }
  } else if (sceneIdx === 1) {
    // SCENE 1: "BUY 1 GET 1" — Dual-Block Elastic Ribbon & 2X Value Counter
    const topH = stageH * 0.45;
    const botY = stageY + topH + gutter;
    const botH = stageH - topH - gutter;

    const topLW = stageW * 0.57 - gutter * 0.5;
    const topRX = stageX + topLW + gutter;
    const topRW = stageW - topLW - gutter;

    const mTL = getCardMotion(p, 0.0, 0.03);
    const mTR = getCardMotion(p, 0.04, 0.02);
    const mBL = getCardMotion(p, 0.06, 0.01);
    const mBR = getCardMotion(p, 0.08, 0.0);

    if (mTL.vis > 0.001) {
      const cw = topLW * mTL.cardVis;
      drawClippedCard(stageX, stageY, cw, topH, cardR, COLORS.white, (cx, cy, w, h) => {
        const pad = minSide * 0.048;
        const pillW = topLW * 0.34;
        const pillH = topH * 0.24;
        const maxTW = topLW - pad * 2 - pillW - gutter;
        const fs = fitFontSize('BUY 1', maxTW, topH * 0.54, minSide * 0.115, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('BUY 1', cx + pad, cy + topH * 0.52);

        const px = stageX + topLW - pad - pillW;
        const py = cy + topH * 0.5 - pillH * 0.5;
        fillRoundRect(px, py, pillW, pillH, pillH * 0.5, COLORS.gold);
        const pfs = fitFontSize('FREE GIFT', pillW * 0.8, pillH * 0.54, minSide * 0.024, '900');
        ctx.font = '900 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.fillText('FREE GIFT', px + pillW * 0.5, py + pillH * 0.52);
      }, mTL.innerAlpha);
    }

    if (mTR.vis > 0.001) {
      const cw = topRW * mTR.cardVis;
      drawClippedCard(topRX + (topRW - cw), stageY, cw, topH, cardR, COLORS.gold, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const plusR = minSide * 0.036;
        const gapP = minSide * 0.028;
        const fs = fitFontSize('GET 1', topRW - pad * 2 - plusR * 2 - gapP, topH * 0.54, minSide * 0.105, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('GET 1').width;
        const groupW = tw + gapP + plusR * 2;
        const startX = topRX + (topRW - groupW) * 0.5;

        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('GET 1', startX, cy + topH * 0.52);

        const plusRot = easeInOutQuart(p) * Math.PI * 0.5;
        drawPlus(startX + tw + gapP + plusR, cy + topH * 0.5, plusR, minSide * 0.014, plusRot, COLORS.bg);
      }, mTR.innerAlpha);
    }

    const botLW = stageW * 0.34 - gutter * 0.5;
    const botRX = stageX + botLW + gutter;
    const botRW = stageW - botLW - gutter;

    if (mBL.vis > 0.001) {
      const ch = botH * mBL.cardVis;
      const cy = botY + (botH - ch) * 0.5;
      drawClippedCard(stageX, cy, botLW, ch, cardR, COLORS.sapphire, (cx, cy2, cw, ch2) => {
        const sc = easeOutGentleSpring(mBL.innerAlpha);
        const starR = Math.min(cw, botH) * 0.28 * sc;
        drawFourPointStar(cx + cw * 0.5, botY + botH * 0.42, starR, starR * 0.42, easeInOutQuart(p) * Math.PI, COLORS.gold);

        const fs = fitFontSize('02 / 04', cw * 0.72, botH * 0.16, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('02 / 04', cx + cw * 0.5, botY + botH * 0.8);
      }, mBL.innerAlpha);
    }

    if (mBR.vis > 0.001) {
      const cw = botRW * mBR.cardVis;
      drawClippedCard(botRX, botY, cw, botH, cardR, COLORS.sapphire, (cx, cy, w, h) => {
        const pad = minSide * 0.048;
        const innerW = botRW - pad * 2;

        // Top Label
        const fsTop = fitFontSize('DOUBLE VALUE DEALS', innerW, h * 0.16, minSide * 0.028, '800');
        ctx.font = '800 ' + fsTop + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.gold;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('DOUBLE VALUE DEALS', cx + pad, cy + h * 0.22);

        // Middle Row: "2X" + Expanding Progress Capsule
        const fs2x = fitFontSize('2X', innerW * 0.25, h * 0.34, minSide * 0.088, '900');
        ctx.font = '900 ' + fs2x + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.fillText('2X', cx + pad, cy + h * 0.52);

        const tw2x = ctx.measureText('2X').width;
        const barX = cx + pad + tw2x + gutter * 1.4;
        const barW = Math.max(10, cx + botRW - pad - barX);
        const barH = minSide * 0.028;
        const barY = cy + h * 0.52 - barH * 0.5;
        const fillU = easeInOutQuart(clamp((p - 0.12) / 0.55, 0, 1));
        fillRoundRect(barX, barY, barW, barH, barH * 0.5, COLORS.navy);
        fillRoundRect(barX, barY, barW * fillU, barH, barH * 0.5, COLORS.gold);

        // Bottom Label
        const fsBot = fitFontSize('NO EXTRA CHARGE  •  ONLINE & IN-STORE', innerW, h * 0.14, minSide * 0.024, '700');
        ctx.font = '700 ' + fsBot + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.ice;
        ctx.fillText('NO EXTRA CHARGE  •  ONLINE & IN-STORE', cx + pad, cy + h * 0.8);
      }, mBR.innerAlpha);
    }
  } else if (sceneIdx === 2) {
    // SCENE 2: "HALF PRICE • 50% OFF • BEST VALUE" — 3-Track Cascade
    const trackGap = stageH * 0.055;
    const trackH = (stageH - trackGap * 2) / 3;
    const trackR = trackH * 0.25;

    const mT0 = getCardMotion(p, 0.0, 0.04);
    const mT1 = getCardMotion(p, 0.04, 0.02);
    const mT2 = getCardMotion(p, 0.08, 0.0);

    if (mT0.vis > 0.001) {
      const cw = stageW * mT0.cardVis;
      drawClippedCard(stageX, stageY, cw, trackH, trackR, COLORS.white, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const badgeD = h * 0.48;
        const bx = cx + pad + badgeD * 0.5;
        const by = cy + h * 0.5;
        ctx.beginPath();
        ctx.arc(bx, by, badgeD * 0.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();

        const bfs = fitFontSize('03', badgeD * 0.65, badgeD * 0.55, minSide * 0.028, '900');
        ctx.font = '900 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('03', bx, by + minSide * 0.001);

        const starsZoneW = stageW * 0.28;
        const textX = cx + pad + badgeD + gutter * 1.4;
        const maxTW = stageW - pad * 2 - badgeD - gutter * 2.4 - starsZoneW;
        const fs = fitFontSize('HALF PRICE', maxTW, h * 0.56, minSide * 0.078, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.fillText('HALF PRICE', textX, cy + h * 0.52);

        // 4 strictly spaced 4-point Gold Stars pulsing cleanly
        const starSlot = starsZoneW / 4;
        const starBaseX = stageX + stageW - pad - starsZoneW;
        const maxStarR = Math.min(starSlot * 0.36, h * 0.22);
        for (let i = 0; i < 4; i++) {
          const pulse = 0.72 + 0.28 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.8));
          const sx = starBaseX + starSlot * (i + 0.5);
          drawFourPointStar(sx, cy + h * 0.5, maxStarR * pulse, maxStarR * 0.42 * pulse, 0, COLORS.gold);
        }
      }, mT0.innerAlpha);
    }

    if (mT1.vis > 0.001) {
      const y1 = stageY + trackH + trackGap;
      const cw = stageW * mT1.cardVis;
      const x1 = stageX + (stageW - cw) * 0.5;
      drawClippedCard(x1, y1, cw, trackH, trackR, COLORS.gold, (cx, cy, w, h) => {
        const pad = minSide * 0.05;
        const sideW = stageW * 0.16;
        const trackPulse = Math.sin(clamp((p - 0.16) / 0.68, 0, 1) * Math.PI);
        const tracking = minSide * 0.006 * trackPulse;
        const maxTW = stageW - pad * 2 - sideW * 2 - gutter * 2 - tracking * 7;
        const fs = fitFontSize('50% OFF', maxTW, h * 0.62, minSide * 0.095, '900');
        drawTextSpaced('50% OFF', stageX + stageW * 0.5, cy + h * 0.52, fs, '900', COLORS.navy, tracking);

        const dR = Math.min(sideW * 0.26, h * 0.24);
        const rot = easeInOutQuart(p) * Math.PI;
        drawDiamond(stageX + pad + dR, cy + h * 0.5, dR, rot, COLORS.navy);
        drawDiamond(stageX + stageW - pad - dR, cy + h * 0.5, dR, -rot, COLORS.navy);
      }, mT1.innerAlpha);
    }

    if (mT2.vis > 0.001) {
      const y2 = stageY + (trackH + trackGap) * 2;
      const cw = stageW * mT2.cardVis;
      drawClippedCard(stageX + (stageW - cw), y2, cw, trackH, trackR, COLORS.sapphire, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const dialR = h * 0.27;
        const pillW = stageW * 0.2;
        const pillH = h * 0.44;
        const maxTW = stageW - pad * 2 - dialR * 2 - pillW - gutter * 2.5;
        const fs = fitFontSize('BEST VALUE', maxTW, h * 0.56, minSide * 0.078, '900');

        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('BEST VALUE', stageX + pad, cy + h * 0.52);

        const dialCX = stageX + stageW - pad - dialR;
        const dialCY = cy + h * 0.5;
        const pillX = dialCX - dialR - gutter * 1.4 - pillW;
        const pillY = cy + h * 0.5 - pillH * 0.5;

        fillRoundRect(pillX, pillY, pillW, pillH, pillH * 0.5, COLORS.white);
        const pfs = fitFontSize('24H PROMO', pillW * 0.78, pillH * 0.54, minSide * 0.025, '900');
        ctx.font = '900 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.fillText('24H PROMO', pillX + pillW * 0.5, pillY + pillH * 0.52);

        const ringW = minSide * 0.009;
        ctx.beginPath();
        ctx.arc(dialCX, dialCY, dialR, 0, Math.PI * 2);
        ctx.strokeStyle = COLORS.rule;
        ctx.lineWidth = ringW;
        ctx.stroke();

        const sweep = easeInOutQuart(clamp((p - 0.12) / 0.72, 0, 1)) * Math.PI * 2;
        if (sweep > 0.01) {
          ctx.beginPath();
          ctx.arc(dialCX, dialCY, dialR, -Math.PI * 0.5, -Math.PI * 0.5 + sweep);
          ctx.strokeStyle = COLORS.gold;
          ctx.lineWidth = ringW;
          ctx.lineCap = 'round';
          ctx.stroke();
        }
        ctx.beginPath();
        ctx.arc(dialCX, dialCY, dialR * 0.34, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.gold;
        ctx.fill();
      }, mT2.innerAlpha);
    }
  } else {
    // SCENE 3: "GRAB IT FAST" — Grand Finale Lockup & Seamless Loop Reset
    const tierGap = stageH * 0.05;
    const topH = stageH * 0.16;
    const midH = stageH * 0.56;
    const botH = stageH * 0.18;

    const topY = stageY;
    const midY = stageY + topH + tierGap;
    const botY = midY + midH + tierGap;

    const benefits = ['EASY RETURNS', 'TOP RATED', 'FAST SHIPPING'];
    const microW = (stageW - gutter * 2) / 3;
    for (let i = 0; i < 3; i++) {
      const mMicro = getCardMotion(p, i * 0.03, (2 - i) * 0.02);
      if (mMicro.vis > 0.001) {
        const mx = stageX + i * (microW + gutter);
        const slideY = mMicro.slideOffset * minSide * 0.025;
        ctx.save();
        ctx.globalAlpha = mMicro.vis;
        drawClippedCard(mx, topY + slideY, microW, topH, minSide * 0.018, COLORS.sapphire, (cx, cy, cw, ch) => {
          const dotR = minSide * 0.008;
          const pad = minSide * 0.03;
          const gapDot = minSide * 0.016;
          const maxTW = cw - pad * 2 - dotR * 2 - gapDot;
          const fs = fitFontSize(benefits[i], maxTW, ch * 0.48, minSide * 0.025, '800');
          ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
          const tw = ctx.measureText(benefits[i]).width;
          const groupW = dotR * 2 + gapDot + tw;
          const startX = cx + (cw - groupW) * 0.5;

          ctx.beginPath();
          ctx.arc(startX + dotR, cy + ch * 0.5, dotR, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.gold;
          ctx.fill();

          ctx.fillStyle = COLORS.white;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText(benefits[i], startX + dotR * 2 + gapDot, cy + ch * 0.52);
        });
        ctx.restore();
      }
    }

    const wingW = stageW * 0.2;
    const centerW = stageW - wingW * 2 - gutter * 2;
    const centerX = stageX + wingW + gutter;
    const rightX = centerX + centerW + gutter;

    const mWingL = getCardMotion(p, 0.04, 0.02);
    const mHero = getCardMotion(p, 0.02, 0.0);
    const mWingR = getCardMotion(p, 0.06, 0.02);

    if (mWingL.vis > 0.001) {
      const curH = midH * mWingL.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(stageX, curY, wingW, curH, cardR, COLORS.sapphire, (cx, cy, cw, ch) => {
        const sc = easeOutGentleSpring(mWingL.innerAlpha);
        const outerR = Math.min(cw, midH) * 0.27 * sc;
        const rot = easeInOutQuart(p) * Math.PI * 0.5;
        drawSerratedSeal(cx + cw * 0.5, midY + midH * 0.4, outerR, outerR * 0.8, 12, rot, COLORS.gold);

        const fs = fitFontSize('SALE', cw * 0.7, midH * 0.16, minSide * 0.032, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SALE', cx + cw * 0.5, midY + midH * 0.78);
      }, mWingL.innerAlpha);
    }

    if (mHero.vis > 0.001) {
      const curW = centerW * mHero.cardVis;
      const curX = centerX + (centerW - curW) * 0.5;
      drawClippedCard(curX, midY, curW, midH, cardR, COLORS.gold, (cx, cy, cw, ch) => {
        const pad = minSide * 0.046;
        const btnR = Math.min(centerW * 0.115, midH * 0.22);
        const btnGap = minSide * 0.03;
        const maxTW = centerW - pad * 2 - btnR * 2 - btnGap;
        const fs = fitFontSize('GRAB IT FAST', maxTW, ch * 0.44, minSide * 0.072, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('GRAB IT FAST').width;
        const groupW = tw + btnGap + btnR * 2;
        const startX = centerX + (centerW - groupW) * 0.5;

        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('GRAB IT FAST', startX, cy + ch * 0.52);

        const btnCX = startX + tw + btnGap + btnR;
        const btnCY = cy + ch * 0.5;
        ctx.beginPath();
        ctx.arc(btnCX, btnCY, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.navy;
        ctx.fill();

        const glide = Math.sin(p * Math.PI * 4) * btnR * 0.14;
        drawChevron(btnCX + glide, btnCY, btnR * 0.42, minSide * 0.009, 1, COLORS.gold);
      }, mHero.innerAlpha);
    }

    if (mWingR.vis > 0.001) {
      const curH = midH * mWingR.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(rightX, curY, wingW, curH, cardR, COLORS.sapphire, (cx, cy, cw, ch) => {
        const pad = minSide * 0.032;
        const fs = fitFontSize('04 / 04', cw * 0.76, midH * 0.16, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.gold;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('04 / 04', cx + cw * 0.5, midY + midH * 0.24);

        const bars = 4;
        const barAreaW = cw - pad * 2;
        const barH = minSide * 0.014;
        const barGap = minSide * 0.018;
        const startBarY = midY + midH * 0.42;
        for (let i = 0; i < bars; i++) {
          const wave = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.8));
          const bw = barAreaW * wave;
          fillRoundRect(cx + pad, startBarY + i * (barH + barGap), bw, barH, barH * 0.5, i === 0 ? COLORS.gold : COLORS.white);
        }
      }, mWingR.innerAlpha);
    }

    const mBot = getCardMotion(p, 0.08, 0.03);
    if (mBot.vis > 0.001) {
      const slideY = -mBot.slideOffset * minSide * 0.025;
      ctx.save();
      ctx.globalAlpha = mBot.vis;
      drawClippedCard(stageX, botY + slideY, stageW, botH, botH * 0.5, COLORS.white, (cx, cy, cw, ch) => {
        const label = 'LIMITED STOCK  •  ORDER TODAY';
        const pad = minSide * 0.045;
        const fs = fitFontSize(label, cw * 0.58, ch * 0.48, minSide * 0.026, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const textW = ctx.measureText(label).width;
        ctx.fillStyle = COLORS.navy;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, cx + cw * 0.5, cy + ch * 0.52);

        const availLine = Math.max(0, (cw - textW) * 0.5 - pad - gutter * 1.5);
        const lineProgress = easeInOutQuart(clamp((p - 0.14) / 0.68, 0, 1));
        const lineW = availLine * lineProgress;
        const lineH = minSide * 0.005;
        const lineY = cy + ch * 0.5 - lineH * 0.5;
        if (lineW > 1) {
          fillRoundRect(cx + pad, lineY, lineW, lineH, lineH * 0.5, COLORS.bg);
          fillRoundRect(cx + cw - pad - lineW, lineY, lineW, lineH, lineH * 0.5, COLORS.bg);
        }
      });
      ctx.restore();
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#0D0926',
    surface: '#16103A',
    surfaceMid: '#201752',
    cyan: '#00F0FF',
    coral: '#FF4D79',
    white: '#F4F8FF',
    muted: '#9694C2',
    dot: '#1B1447',
    rule: '#2B2168'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    const edgeFade = clamp(Math.min(w, h) / Math.max(2, r * 2), 0, 1);
    if (edgeFade <= 0.01 || w <= 0.5 || h <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= edgeFade;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawTextSpaced(text, cx, cy, fontSize, weight, color, extraTracking) {
    ctx.save();
    ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.fillStyle = color;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const chars = text.split('');
    let totalW = 0;
    const widths = [];
    for (let i = 0; i < chars.length; i++) {
      const cw = ctx.measureText(chars[i]).width;
      widths.push(cw);
      totalW += cw + (i < chars.length - 1 ? extraTracking : 0);
    }
    let cursorX = cx - totalW * 0.5;
    for (let i = 0; i < chars.length; i++) {
      ctx.fillText(chars[i], cursorX, cy);
      cursorX += widths[i] + extraTracking;
    }
    ctx.restore();
  }

  // Smooth crisp flat liquid wave region (no glow/blur) bounded strictly inside [x, y, w, h]
  function fillWaveArea(x, y, w, h, baseLevelRatio, amp, cycles, phase, fillTop, color) {
    if (w <= 1 || h <= 1) return;
    const steps = 48;
    const baseY = y + h * baseLevelRatio;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const px = x + u * w;
      const py =
        baseY +
        Math.sin(u * Math.PI * 2 * cycles + phase) * amp +
        Math.cos(u * Math.PI * 2 * (cycles * 0.5) - phase * 0.7) * amp * 0.32;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    if (fillTop) {
      ctx.lineTo(x + w, y);
      ctx.lineTo(x, y);
    } else {
      ctx.lineTo(x + w, y + h);
      ctx.lineTo(x, y + h);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.17;
    const exitDur = 0.17;
    const inU = clamp((p - enterDelay) / enterDur, 0, 1);
    const outU = clamp((p - (0.80 - exitDelay)) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Flat Midnight Indigo Background (Zero glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Subtle Flat Architectural Fluid Droplet Lattice in Central Field (Seamless 2-cycle loop)
  const gridCols = 14;
  const gridRows = 6;
  const gridLeft = width * 0.08;
  const gridRight = width * 0.92;
  const gridTop = height * 0.165;
  const gridBottom = height * 0.835;
  const dotPhase = 2 * Math.PI * (safeLoopT / duration) * 2;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < gridRows; r++) {
    const dy = lerp(gridTop, gridBottom, r / (gridRows - 1));
    for (let c = 0; c < gridCols; c++) {
      const dx = lerp(gridLeft, gridRight, c / (gridCols - 1));
      const wave = 0.5 + 0.5 * Math.sin(dotPhase - c * 0.42 + r * 0.35);
      const rad = minSide * (0.0022 + 0.0014 * wave);
      ctx.beginPath();
      ctx.arc(dx, dy, rad, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 3. Persistent Top & Bottom Smooth Fluid Wave Ribbon Bands (Strictly separated from central stage)
  const waveBandH = height * 0.115;
  const wavePhase = 2 * Math.PI * (safeLoopT / duration) * 3;

  // Top fluid band
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, width, waveBandH);
  ctx.clip();
  fillWaveArea(0, 0, width, waveBandH, 0.84, minSide * 0.008, 3, wavePhase, true, COLORS.surfaceMid);
  fillWaveArea(0, 0, width, waveBandH, 0.72, minSide * 0.006, 2, -wavePhase, true, COLORS.surface);

  // Clean ticker text strictly inside flat upper zone (0..0.068*height)
  const topTickerH = height * 0.068;
  const topText = 'CYBER DROP   •   ONLINE ONLY   •   SAVE UP TO 60%   •   FAST CHECKOUT   •   ';
  const topFS = topTickerH * 0.42;
  ctx.font = '700 ' + topFS + 'px ' + FONT_FAMILY;
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  const topTileW = ctx.measureText(topText).width;
  if (topTileW > 0) {
    const shift = (safeLoopT / duration) * topTileW * 2 * -1;
    let sx = ((shift % topTileW) + topTileW) % topTileW - topTileW;
    while (sx < width + topTileW) {
      const parts = topText.split('•');
      let cx = sx;
      for (let i = 0; i < parts.length; i++) {
        ctx.fillStyle = COLORS.white;
        ctx.fillText(parts[i], cx, topTickerH * 0.54);
        cx += ctx.measureText(parts[i]).width;
        if (i < parts.length - 1) {
          const dw = ctx.measureText('•').width;
          ctx.fillStyle = COLORS.cyan;
          ctx.beginPath();
          ctx.arc(cx + dw * 0.5, topTickerH * 0.52, minSide * 0.0042, 0, Math.PI * 2);
          ctx.fill();
          cx += dw;
        }
      }
      sx += topTileW;
    }
  }
  ctx.restore();

  // Bottom fluid band
  const botBandY = height - waveBandH;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, botBandY, width, waveBandH);
  ctx.clip();
  fillWaveArea(0, botBandY, width, waveBandH, 0.16, minSide * 0.008, 3, -wavePhase, false, COLORS.surfaceMid);
  fillWaveArea(0, botBandY, width, waveBandH, 0.28, minSide * 0.006, 2, wavePhase, false, COLORS.surface);

  const botTickerY = height - topTickerH;
  const botText = 'DIGITAL EXCLUSIVE   •   LIMITED HOURS   •   INSTANT ACCESS   •   CYBER DEAL   •   ';
  ctx.font = '700 ' + topFS + 'px ' + FONT_FAMILY;
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  const botTileW = ctx.measureText(botText).width;
  if (botTileW > 0) {
    const shift = (safeLoopT / duration) * botTileW * 2;
    let sx = ((shift % botTileW) + botTileW) % botTileW - botTileW;
    while (sx < width + botTileW) {
      const parts = botText.split('•');
      let cx = sx;
      for (let i = 0; i < parts.length; i++) {
        ctx.fillStyle = COLORS.muted;
        ctx.fillText(parts[i], cx, botTickerY + topTickerH * 0.52);
        cx += ctx.measureText(parts[i]).width;
        if (i < parts.length - 1) {
          const dw = ctx.measureText('•').width;
          ctx.fillStyle = COLORS.coral;
          ctx.beginPath();
          ctx.arc(cx + dw * 0.5, botTickerY + topTickerH * 0.5, minSide * 0.0042, 0, Math.PI * 2);
          ctx.fill();
          cx += dw;
        }
      }
      sx += botTileW;
    }
  }
  ctx.restore();

  // Central Stage Coordinates (Strict clearance from top/bottom wave bands)
  const stageX = width * 0.065;
  const stageW = width * 0.87;
  const stageY = height * 0.15;
  const stageH = height * 0.7;
  const gutter = minSide * 0.024;
  const cardR = minSide * 0.024;

  // Seamless bridge indicator at p=0 and p=1
  const anchorAlpha =
    sceneProgress < 0.14
      ? 1 - easeOutCubic(sceneProgress / 0.14)
      : sceneProgress > 0.86
      ? easeInCubic((sceneProgress - 0.86) / 0.14)
      : 0;
  if (anchorAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha = anchorAlpha;
    const barW = stageW * 0.26 * anchorAlpha;
    const barH = minSide * 0.007;
    fillRoundRect(width * 0.5 - barW * 0.5, height * 0.5 - barH * 0.5, barW, barH, barH * 0.5, COLORS.cyan);
    ctx.restore();
  }

  const p = sceneProgress;

  if (sceneIdx === 0) {
    // SCENE 0: "CYBER DEAL" — Liquid-Filled Hero Capsule & Wave Crest Split
    const metaH = stageH * 0.11;
    const mainY = stageY + stageH * 0.16;
    const mainH = stageH * 0.56;
    const botY = stageY + stageH * 0.77;
    const botH = stageH * 0.23;

    // Row 0: Meta Header
    const mMeta = getCardMotion(p, 0.0, 0.04);
    if (mMeta.vis > 0.001) {
      const leftPillW = stageW * 0.23;
      const rightPillW = stageW * 0.14;
      const slideY = mMeta.slideOffset * minSide * 0.03;

      ctx.save();
      ctx.globalAlpha = mMeta.vis;
      drawClippedCard(stageX, stageY + slideY, leftPillW, metaH, metaH * 0.5, COLORS.cyan, (cx, cy, cw, ch) => {
        const fs = fitFontSize('CYBER EVENT', cw * 0.82, ch * 0.48, minSide * 0.024, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('CYBER EVENT', cx + cw * 0.5, cy + ch * 0.52);
      });

      // Smooth undulating fluid sine divider rule between pills
      const waveStart = stageX + leftPillW + gutter;
      const waveEnd = stageX + stageW - rightPillW - gutter;
      const waveW = (waveEnd - waveStart) * mMeta.vis;
      if (waveW > 2) {
        ctx.beginPath();
        const segs = 36;
        for (let i = 0; i <= segs; i++) {
          const u = i / segs;
          const px = waveStart + u * waveW;
          const py = stageY + metaH * 0.5 + slideY + Math.sin(u * Math.PI * 6 + p * Math.PI * 4) * minSide * 0.005;
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.strokeStyle = COLORS.rule;
        ctx.lineWidth = minSide * 0.004;
        ctx.lineCap = 'round';
        ctx.stroke();
      }

      drawClippedCard(stageX + stageW - rightPillW, stageY + slideY, rightPillW, metaH, metaH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const fs = fitFontSize('01 / 04', cw * 0.72, ch * 0.48, minSide * 0.023, '700');
        ctx.font = '700 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cyan;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('01 / 04', cx + cw * 0.5, cy + ch * 0.52);
      });
      ctx.restore();
    }

    // Row 1: Left Liquid-Wave Hero Capsule + Right Liquid Gauge Panel
    const leftW = stageW * 0.65 - gutter * 0.5;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;
    const mHeroL = getCardMotion(p, 0.02, 0.02);
    const mHeroR = getCardMotion(p, 0.06, 0.0);

    if (mHeroL.vis > 0.001) {
      const curW = leftW * mHeroL.cardVis;
      drawClippedCard(stageX, mainY, curW, mainH, cardR, COLORS.surface, (cx, cy, cw, ch) => {
        const pad = minSide * 0.05;
        // Strict upper typography zone (0%..58% of card height) — zero wave intersection!
        const textShift = (1 - mHeroL.innerAlpha) * stageW * 0.025;
        const fs1 = fitFontSize('CYBER', leftW - pad * 2, mainH * 0.28, minSide * 0.115, '900');
        ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('CYBER', cx + pad - textShift, cy + mainH * 0.22);

        const fs2 = fitFontSize('DEAL', leftW - pad * 2, mainH * 0.28, minSide * 0.115, '900');
        ctx.font = '900 ' + fs2 + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cyan;
        ctx.fillText('DEAL', cx + pad - textShift, cy + mainH * 0.45);

        // Right-aligned pill badge strictly inside top-right clear zone
        const badgeW = leftW * 0.28;
        const badgeH = mainH * 0.14;
        const bx = stageX + leftW - pad - badgeW;
        const by = cy + pad;
        fillRoundRect(bx, by, badgeW, badgeH, badgeH * 0.5, COLORS.coral);
        const bfs = fitFontSize('ONLINE ONLY', badgeW * 0.8, badgeH * 0.55, minSide * 0.02, '800');
        ctx.font = '800 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.fillText('ONLINE ONLY', bx + badgeW * 0.5, by + badgeH * 0.52);

        // Strict lower fluid wave zone (66%..100% of card height)
        const waveZoneY = cy + mainH * 0.66;
        const waveZoneH = mainH * 0.34;
        ctx.save();
        ctx.beginPath();
        ctx.rect(stageX, waveZoneY, leftW, waveZoneH);
        ctx.clip();
        fillWaveArea(stageX, waveZoneY, leftW, waveZoneH, 0.28, minSide * 0.012, 2, p * Math.PI * 4, false, COLORS.surfaceMid);
        fillWaveArea(stageX, waveZoneY, leftW, waveZoneH, 0.44, minSide * 0.01, 2.5, -p * Math.PI * 4 + 1.1, false, COLORS.cyan);
        ctx.restore();
      }, mHeroL.innerAlpha);
    }

    if (mHeroR.vis > 0.001) {
      const curH = mainH * mHeroR.cardVis;
      const curY = mainY + (mainH - curH) * 0.5;
      drawClippedCard(rightX, curY, rightW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.04;
        const tankW = rightW * 0.2;
        const tankH = mainH - pad * 2;
        const tankX = rightX + pad;
        const tankY = mainY + pad;

        // Vertical Liquid Fill Pill Tank
        fillRoundRect(tankX, tankY, tankW, tankH, tankW * 0.5, COLORS.bg);
        ctx.save();
        roundRectPath(tankX, tankY, tankW, tankH, tankW * 0.5);
        ctx.clip();
        const fillU = easeInOutQuart(clamp((p - 0.1) / 0.55, 0, 1));
        const levelRatio = lerp(0.82, 0.26, fillU);
        fillWaveArea(tankX, tankY, tankW, tankH, levelRatio, minSide * 0.007, 1.5, p * Math.PI * 4, false, COLORS.coral);
        ctx.restore();

        // Right-side stacked value copy strictly separated from liquid tank
        const textX = tankX + tankW + gutter * 1.4;
        const textW = rightW - pad * 2 - tankW - gutter * 1.4;
        const tcx = textX + textW * 0.5;

        const fsSave = fitFontSize('SAVE', textW, mainH * 0.16, minSide * 0.036, '800');
        ctx.font = '800 ' + fsSave + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SAVE', tcx, mainY + mainH * 0.25);

        const fsNum = fitFontSize('60%', textW, mainH * 0.34, minSide * 0.095, '900');
        ctx.font = '900 ' + fsNum + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.coral;
        ctx.fillText('60%', tcx, mainY + mainH * 0.5);

        const fsNow = fitFontSize('NOW', textW, mainH * 0.16, minSide * 0.036, '800');
        ctx.font = '800 ' + fsNow + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cyan;
        ctx.fillText('NOW', tcx, mainY + mainH * 0.74);
      }, mHeroR.innerAlpha);
    }

    // Row 2: Bottom Info + Coral Action Capsule
    const mBotL = getCardMotion(p, 0.07, 0.02);
    const mBotR = getCardMotion(p, 0.09, 0.0);
    const botLW = stageW * 0.56 - gutter * 0.5;
    const botRX = stageX + botLW + gutter;
    const botRW = stageW - botLW - gutter;

    if (mBotL.vis > 0.001) {
      const cw = botLW * mBotL.cardVis;
      drawClippedCard(stageX, botY, cw, botH, cardR, COLORS.surfaceMid, (cx, cy, w, h) => {
        const fs = fitFontSize('LIMITED TIME  •  INSTANT ACCESS', botLW * 0.86, h * 0.42, minSide * 0.028, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('LIMITED TIME  •  INSTANT ACCESS', stageX + botLW * 0.5, cy + h * 0.52);
      }, mBotL.innerAlpha);
    }

    if (mBotR.vis > 0.001) {
      const cw = botRW * mBotR.cardVis;
      drawClippedCard(botRX + (botRW - cw), botY, cw, botH, cardR, COLORS.coral, (cx, cy, w, h) => {
        const pad = minSide * 0.04;
        const btnR = Math.min(botRW * 0.13, h * 0.34);
        const gapBtn = minSide * 0.028;
        const fs = fitFontSize('60% OFF', botRW - pad * 2 - btnR * 2 - gapBtn, h * 0.56, minSide * 0.054, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('60% OFF').width;
        const groupW = tw + gapBtn + btnR * 2;
        const startX = botRX + (botRW - groupW) * 0.5;

        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('60% OFF', startX, cy + h * 0.52);

        const bcx = startX + tw + gapBtn + btnR;
        const bcy = cy + h * 0.5;
        ctx.beginPath();
        ctx.arc(bcx, bcy, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();

        const glide = Math.sin(p * Math.PI * 4) * btnR * 0.14;
        drawChevron(bcx + glide, bcy, btnR * 0.42, minSide * 0.007, 1, COLORS.cyan);
      }, mBotR.innerAlpha);
    }
  } else if (sceneIdx === 1) {
    // SCENE 1: "SAVE 60%" — Expanding Fluid Tank Card & Liquid Tube Equalizer
    const leftW = stageW * 0.45;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;

    const mLeft = getCardMotion(p, 0.0, 0.02);
    if (mLeft.vis > 0.001) {
      const curH = stageH * mLeft.cardVis;
      const curY = stageY + (stageH - curH) * 0.5;
      drawClippedCard(stageX, curY, leftW, curH, cardR, COLORS.cyan, (cx, cy, cw, ch) => {
        const pad = minSide * 0.048;
        const innerW = cw - pad * 2;
        const pillW = Math.min(innerW * 0.7, innerW);
        const pillH = stageH * 0.105;

        // Top Pill
        fillRoundRect(cx + (cw - pillW) * 0.5, stageY + pad, pillW, pillH, pillH * 0.5, COLORS.bg);
        const pfs = fitFontSize('CYBER DROP', pillW * 0.8, pillH * 0.5, minSide * 0.023, '800');
        ctx.font = '800 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cyan;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('CYBER DROP', cx + cw * 0.5, stageY + pad + pillH * 0.52);

        // Rolling Odometer Counter 10% -> 60% in Center Clear Zone
        const countU = easeOutCubic(clamp((p - 0.1) / 0.45, 0, 1));
        const val = Math.round(lerp(10, 60, countU));
        const nfs = fitFontSize('60%', innerW * 0.92, stageH * 0.36, minSide * 0.21, '900');
        ctx.font = '900 ' + nfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.fillText(val + '%', cx + cw * 0.5, stageY + stageH * 0.46);

        const sfs = fitFontSize('OFF STOREWIDE', innerW * 0.88, stageH * 0.08, minSide * 0.032, '900');
        ctx.font = '900 ' + sfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.fillText('OFF STOREWIDE', cx + cw * 0.5, stageY + stageH * 0.68);

        // Strictly separated Bottom Liquid Wave Zone (78%..100%)
        const wzY = stageY + stageH * 0.78;
        const wzH = stageH * 0.22;
        ctx.save();
        ctx.beginPath();
        ctx.rect(stageX, wzY, leftW, wzH);
        ctx.clip();
        fillWaveArea(stageX, wzY, leftW, wzH, 0.32, minSide * 0.01, 2, p * Math.PI * 4, false, COLORS.surfaceMid);
        fillWaveArea(stageX, wzY, leftW, wzH, 0.48, minSide * 0.008, 2.5, -p * Math.PI * 4, false, COLORS.surface);
        ctx.restore();
      }, mLeft.innerAlpha);
    }

    const cardH = (stageH - gutter * 2) / 3;
    const mR1 = getCardMotion(p, 0.03, 0.03);
    const mR2 = getCardMotion(p, 0.06, 0.01);
    const mR3 = getCardMotion(p, 0.09, 0.0);

    if (mR1.vis > 0.001) {
      const cw = rightW * mR1.cardVis;
      drawClippedCard(rightX, stageY, cw, cardH, cardR, COLORS.surface, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const badgeW = rightW * 0.22;
        const badgeH = h * 0.34;
        const fs = fitFontSize('ONLINE ONLY', rightW - pad * 2 - badgeW - gutter, h * 0.5, minSide * 0.068, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('ONLINE ONLY', cx + pad, cy + h * 0.52);

        const bx = rightX + rightW - pad - badgeW;
        const by = cy + h * 0.5 - badgeH * 0.5;
        fillRoundRect(bx, by, badgeW, badgeH, badgeH * 0.5, COLORS.surfaceMid);
        const bfs = fitFontSize('02 / 04', badgeW * 0.76, badgeH * 0.52, minSide * 0.022, '700');
        ctx.font = '700 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.coral;
        ctx.textAlign = 'center';
        ctx.fillText('02 / 04', bx + badgeW * 0.5, by + badgeH * 0.52);
      }, mR1.innerAlpha);
    }

    if (mR2.vis > 0.001) {
      const y2 = stageY + cardH + gutter;
      const cw = rightW * mR2.cardVis;
      drawClippedCard(rightX + (rightW - cw), y2, cw, cardH, cardR, COLORS.coral, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const dotsW = minSide * 0.09;
        const dotR = minSide * 0.011;
        for (let d = 0; d < 3; d++) {
          const pulse = 0.72 + 0.28 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - d * 0.8));
          ctx.beginPath();
          ctx.arc(rightX + pad + dotR + d * minSide * 0.03, cy + h * 0.5, dotR * pulse, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.white;
          ctx.fill();
        }
        const textCenterX = rightX + pad + dotsW + (rightW - pad * 2 - dotsW) * 0.5;
        const trackPulse = Math.sin(clamp((p - 0.18) / 0.64, 0, 1) * Math.PI);
        const tracking = minSide * 0.006 * trackPulse;
        const fs = fitFontSize('SAVE BIG', rightW - pad * 2 - dotsW - gutter - tracking * 8, h * 0.52, minSide * 0.072, '900');
        drawTextSpaced('SAVE BIG', textCenterX, cy + h * 0.52, fs, '900', COLORS.white, tracking);
      }, mR2.innerAlpha);
    }

    if (mR3.vis > 0.001) {
      const y3 = stageY + (cardH + gutter) * 2;
      const cw = rightW * mR3.cardVis;
      drawClippedCard(rightX, y3, cw, cardH, cardR, COLORS.surfaceMid, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const tubesW = rightW * 0.34;
        const fs = fitFontSize('NO CODE NEEDED', rightW - pad * 2 - tubesW - gutter, h * 0.42, minSide * 0.044, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('NO CODE NEEDED', cx + pad, cy + h * 0.52);

        // 5 Liquid-Filled Capsule Tubes (Each tube clips its own rising/falling liquid fill)
        const tubes = 5;
        const tGap = minSide * 0.014;
        const tw = (tubesW - tGap * (tubes - 1)) / tubes;
        const th = h * 0.62;
        const tx0 = rightX + rightW - pad - tubesW;
        const ty0 = cy + (h - th) * 0.5;
        for (let i = 0; i < tubes; i++) {
          const tx = tx0 + i * (tw + tGap);
          fillRoundRect(tx, ty0, tw, th, tw * 0.5, COLORS.bg);
          const fillWave = 0.35 + 0.5 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.75));
          const fh = th * fillWave;
          ctx.save();
          roundRectPath(tx, ty0, tw, th, tw * 0.5);
          ctx.clip();
          fillRoundRect(tx, ty0 + th - fh, tw, fh, 0, i % 2 === 0 ? COLORS.cyan : COLORS.coral);
          ctx.restore();
        }
      }, mR3.innerAlpha);
    }
  } else if (sceneIdx === 2) {
    // SCENE 2: "DIGITAL EXCLUSIVE • FAST CHECKOUT" — 3 Parallel Fluid Wave Streams
    const trackGap = stageH * 0.055;
    const trackH = (stageH - trackGap * 2) / 3;
    const trackR = trackH * 0.26;

    const mT0 = getCardMotion(p, 0.0, 0.04);
    const mT1 = getCardMotion(p, 0.04, 0.02);
    const mT2 = getCardMotion(p, 0.08, 0.0);

    // Track 0: "DIGITAL" + Clipped Dual-Sine Fluid Wave Channel
    if (mT0.vis > 0.001) {
      const cw = stageW * mT0.cardVis;
      drawClippedCard(stageX, stageY, cw, trackH, trackR, COLORS.surface, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const badgeD = h * 0.48;
        const bx = cx + pad + badgeD * 0.5;
        const by = cy + h * 0.5;
        ctx.beginPath();
        ctx.arc(bx, by, badgeD * 0.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.coral;
        ctx.fill();

        const bfs = fitFontSize('03', badgeD * 0.65, badgeD * 0.55, minSide * 0.028, '900');
        ctx.font = '900 ' + bfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('03', bx, by + minSide * 0.001);

        const waveChanW = stageW * 0.36;
        const textX = cx + pad + badgeD + gutter * 1.4;
        const maxTW = stageW - pad * 2 - badgeD - gutter * 2.4 - waveChanW;
        const fs = fitFontSize('DIGITAL', maxTW, h * 0.56, minSide * 0.082, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.fillText('DIGITAL', textX, cy + h * 0.52);

        // Smooth Dual-Sine Wave Capsule Window on Right
        const wx = stageX + stageW - pad - waveChanW;
        const wy = cy + h * 0.24;
        const wh = h * 0.52;
        fillRoundRect(wx, wy, waveChanW, wh, wh * 0.5, COLORS.bg);
        ctx.save();
        roundRectPath(wx, wy, waveChanW, wh, wh * 0.5);
        ctx.clip();
        fillWaveArea(wx, wy, waveChanW, wh, 0.54, wh * 0.16, 2, p * Math.PI * 4, false, COLORS.surfaceMid);
        fillWaveArea(wx, wy, waveChanW, wh, 0.66, wh * 0.14, 3, -p * Math.PI * 4 + 1, false, COLORS.cyan);
        ctx.restore();
      }, mT0.innerAlpha);
    }

    // Track 1: "EXCLUSIVE" Centered + Symmetrical Fluid Dot Wave Trails
    if (mT1.vis > 0.001) {
      const y1 = stageY + trackH + trackGap;
      const cw = stageW * mT1.cardVis;
      const x1 = stageX + (stageW - cw) * 0.5;
      drawClippedCard(x1, y1, cw, trackH, trackR, COLORS.cyan, (cx, cy, w, h) => {
        const pad = minSide * 0.05;
        const sideW = stageW * 0.18;
        const trackPulse = Math.sin(clamp((p - 0.16) / 0.68, 0, 1) * Math.PI);
        const tracking = minSide * 0.006 * trackPulse;
        const maxTW = stageW - pad * 2 - sideW * 2 - gutter * 2 - tracking * 9;
        const fs = fitFontSize('EXCLUSIVE', maxTW, h * 0.58, minSide * 0.085, '900');
        drawTextSpaced('EXCLUSIVE', stageX + stageW * 0.5, cy + h * 0.52, fs, '900', COLORS.bg, tracking);

        const dotCount = 4;
        const dotR = minSide * 0.011;
        for (let i = 0; i < dotCount; i++) {
          const dy = Math.sin(p * Math.PI * 4 - i * 0.85) * h * 0.16;
          const lx = stageX + pad + dotR + i * (sideW * 0.26);
          const rx = stageX + stageW - pad - dotR - i * (sideW * 0.26);
          ctx.fillStyle = COLORS.bg;
          ctx.beginPath();
          ctx.arc(lx, cy + h * 0.5 + dy, dotR * (1 - i * 0.1), 0, Math.PI * 2);
          ctx.fill();
          ctx.beginPath();
          ctx.arc(rx, cy + h * 0.5 - dy, dotR * (1 - i * 0.1), 0, Math.PI * 2);
          ctx.fill();
        }
      }, mT1.innerAlpha);
    }

    // Track 2: "FAST CHECKOUT" + "24H ONLY" Pill + Liquid-Wave Filled Radial Dial
    if (mT2.vis > 0.001) {
      const y2 = stageY + (trackH + trackGap) * 2;
      const cw = stageW * mT2.cardVis;
      drawClippedCard(stageX + (stageW - cw), y2, cw, trackH, trackR, COLORS.coral, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const dialR = h * 0.28;
        const pillW = stageW * 0.19;
        const pillH = h * 0.44;
        const maxTW = stageW - pad * 2 - dialR * 2 - pillW - gutter * 2.6;
        const fs = fitFontSize('FAST CHECKOUT', maxTW, h * 0.54, minSide * 0.072, '900');

        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('FAST CHECKOUT', stageX + pad, cy + h * 0.52);

        const dialCX = stageX + stageW - pad - dialR;
        const dialCY = cy + h * 0.5;
        const pillX = dialCX - dialR - gutter * 1.4 - pillW;
        const pillY = cy + h * 0.5 - pillH * 0.5;

        fillRoundRect(pillX, pillY, pillW, pillH, pillH * 0.5, COLORS.bg);
        const pfs = fitFontSize('24H ONLY', pillW * 0.78, pillH * 0.54, minSide * 0.025, '800');
        ctx.font = '800 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.cyan;
        ctx.textAlign = 'center';
        ctx.fillText('24H ONLY', pillX + pillW * 0.5, pillY + pillH * 0.52);

        // Liquid-filled circular gauge with clean progress arc
        ctx.beginPath();
        ctx.arc(dialCX, dialCY, dialR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();
        ctx.save();
        ctx.beginPath();
        ctx.arc(dialCX, dialCY, dialR * 0.88, 0, Math.PI * 2);
        ctx.clip();
        const fillLevel = lerp(0.85, 0.28, easeInOutQuart(clamp((p - 0.12) / 0.7, 0, 1)));
        fillWaveArea(
          dialCX - dialR,
          dialCY - dialR,
          dialR * 2,
          dialR * 2,
          fillLevel,
          dialR * 0.1,
          1.5,
          p * Math.PI * 4,
          false,
          COLORS.cyan
        );
        ctx.restore();
      }, mT2.innerAlpha);
    }
  } else {
    // SCENE 3: "ORDER NOW" — Unified Fluid Crest Lockup
    const tierGap = stageH * 0.05;
    const topH = stageH * 0.16;
    const midH = stageH * 0.56;
    const botH = stageH * 0.18;

    const topY = stageY;
    const midY = stageY + topH + tierGap;
    const botY = midY + midH + tierGap;

    const benefits = ['INSTANT ACCESS', 'FREE DELIVERY', '24H SUPPORT'];
    const microW = (stageW - gutter * 2) / 3;
    for (let i = 0; i < 3; i++) {
      const mMicro = getCardMotion(p, i * 0.03, (2 - i) * 0.02);
      if (mMicro.vis > 0.001) {
        const mx = stageX + i * (microW + gutter);
        const slideY = mMicro.slideOffset * minSide * 0.025;
        ctx.save();
        ctx.globalAlpha = mMicro.vis;
        drawClippedCard(mx, topY + slideY, microW, topH, minSide * 0.018, COLORS.surface, (cx, cy, cw, ch) => {
          const dotR = minSide * 0.008;
          const pad = minSide * 0.03;
          const gapDot = minSide * 0.016;
          const maxTW = cw - pad * 2 - dotR * 2 - gapDot;
          const fs = fitFontSize(benefits[i], maxTW, ch * 0.48, minSide * 0.024, '800');
          ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
          const tw = ctx.measureText(benefits[i]).width;
          const groupW = dotR * 2 + gapDot + tw;
          const startX = cx + (cw - groupW) * 0.5;

          ctx.beginPath();
          ctx.arc(startX + dotR, cy + ch * 0.5, dotR, 0, Math.PI * 2);
          ctx.fillStyle = i === 1 ? COLORS.coral : COLORS.cyan;
          ctx.fill();

          ctx.fillStyle = COLORS.white;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText(benefits[i], startX + dotR * 2 + gapDot, cy + ch * 0.52);
        });
        ctx.restore();
      }
    }

    const wingW = stageW * 0.2;
    const centerW = stageW - wingW * 2 - gutter * 2;
    const centerX = stageX + wingW + gutter;
    const rightX = centerX + centerW + gutter;

    const mWingL = getCardMotion(p, 0.04, 0.02);
    const mHero = getCardMotion(p, 0.02, 0.0);
    const mWingR = getCardMotion(p, 0.06, 0.02);

    if (mWingL.vis > 0.001) {
      const curH = midH * mWingL.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(stageX, curY, wingW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        // Upper badge cleanly separated from lower fluid wave pool
        const fs = fitFontSize('24H', cw * 0.68, midH * 0.22, minSide * 0.056, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('24H', cx + cw * 0.5, midY + midH * 0.28);

        const wzY = midY + midH * 0.52;
        const wzH = midH * 0.48;
        ctx.save();
        ctx.beginPath();
        ctx.rect(stageX, wzY, wingW, wzH);
        ctx.clip();
        fillWaveArea(stageX, wzY, wingW, wzH, 0.34, minSide * 0.01, 1.5, p * Math.PI * 4, false, COLORS.coral);
        fillWaveArea(stageX, wzY, wingW, wzH, 0.55, minSide * 0.008, 2, -p * Math.PI * 4, false, COLORS.cyan);
        ctx.restore();
      }, mWingL.innerAlpha);
    }

    if (mHero.vis > 0.001) {
      const curW = centerW * mHero.cardVis;
      const curX = centerX + (centerW - curW) * 0.5;
      drawClippedCard(curX, midY, curW, midH, cardR, COLORS.cyan, (cx, cy, cw, ch) => {
        const pad = minSide * 0.05;
        const btnR = Math.min(centerW * 0.12, midH * 0.23);
        const btnGap = minSide * 0.034;
        const maxTW = centerW - pad * 2 - btnR * 2 - btnGap;
        const fs = fitFontSize('ORDER NOW', maxTW, ch * 0.48, minSide * 0.086, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('ORDER NOW').width;
        const groupW = tw + btnGap + btnR * 2;
        const startX = centerX + (centerW - groupW) * 0.5;

        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('ORDER NOW', startX, cy + ch * 0.52);

        const btnCX = startX + tw + btnGap + btnR;
        const btnCY = cy + ch * 0.5;
        ctx.beginPath();
        ctx.arc(btnCX, btnCY, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();

        const glide = Math.sin(p * Math.PI * 4) * btnR * 0.14;
        drawChevron(btnCX + glide, btnCY, btnR * 0.42, minSide * 0.009, 1, COLORS.cyan);
      }, mHero.innerAlpha);
    }

    if (mWingR.vis > 0.001) {
      const curH = midH * mWingR.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(rightX, curY, wingW, curH, cardR, COLORS.surfaceMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.032;
        const fs = fitFontSize('04 / 04', cw * 0.76, midH * 0.16, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.coral;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('04 / 04', cx + cw * 0.5, midY + midH * 0.24);

        const bars = 4;
        const barAreaW = cw - pad * 2;
        const barH = minSide * 0.014;
        const barGap = minSide * 0.018;
        const startBarY = midY + midH * 0.42;
        for (let i = 0; i < bars; i++) {
          const wave = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.8));
          const bw = barAreaW * wave;
          fillRoundRect(cx + pad, startBarY + i * (barH + barGap), bw, barH, barH * 0.5, i === 0 ? COLORS.cyan : COLORS.white);
        }
      }, mWingR.innerAlpha);
    }

    const mBot = getCardMotion(p, 0.08, 0.03);
    if (mBot.vis > 0.001) {
      const slideY = -mBot.slideOffset * minSide * 0.025;
      ctx.save();
      ctx.globalAlpha = mBot.vis;
      drawClippedCard(stageX, botY + slideY, stageW, botH, botH * 0.5, COLORS.surface, (cx, cy, cw, ch) => {
        const label = 'CYBER WEEK OFFER  •  LIMITED TIME';
        const pad = minSide * 0.045;
        const fs = fitFontSize(label, cw * 0.58, ch * 0.48, minSide * 0.026, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        const textW = ctx.measureText(label).width;
        ctx.fillStyle = COLORS.white;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, cx + cw * 0.5, cy + ch * 0.52);

        const availLine = Math.max(0, (cw - textW) * 0.5 - pad - gutter * 1.5);
        const lineProgress = easeInOutQuart(clamp((p - 0.14) / 0.68, 0, 1));
        const lineW = availLine * lineProgress;
        const lineH = minSide * 0.005;
        const lineY = cy + ch * 0.5 - lineH * 0.5;
        if (lineW > 1) {
          fillRoundRect(cx + pad, lineY, lineW, lineH, lineH * 0.5, COLORS.coral);
          fillRoundRect(cx + cw - pad - lineW, lineY, lineW, lineH, lineH * 0.5, COLORS.coral);
        }
      });
      ctx.restore();
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const COLORS = {
    bg: '#0B0C10',
    cardDark: '#151821',
    cardMid: '#1C202C',
    volt: '#D9FF00',
    chalk: '#F7F8FA',
    chalkMuted: '#8E97AB',
    chalkSoft: '#E2E6EE',
    dot: '#222736',
    rule: '#2B3142'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawClippedCard(x, y, w, h, r, bgColor, drawContent, innerAlpha) {
    if (w <= 0.5 || h <= 0.5) return;
    ctx.save();
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();
    const alpha = innerAlpha === undefined ? 1 : innerAlpha;
    if (alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= alpha;
      drawContent(x, y, w, h);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawStarburst(cx, cy, outerR, innerR, points, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const a = (i * Math.PI) / points;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function drawChevron(cx, cy, size, strokeW, dir, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(dir, 1);
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawTextSpaced(text, cx, cy, fontSize, weight, color, extraTracking) {
    ctx.save();
    ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.fillStyle = color;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const chars = text.split('');
    let totalW = 0;
    const widths = [];
    for (let i = 0; i < chars.length; i++) {
      const cw = ctx.measureText(chars[i]).width;
      widths.push(cw);
      totalW += cw + (i < chars.length - 1 ? extraTracking : 0);
    }
    let cursorX = cx - totalW * 0.5;
    for (let i = 0; i < chars.length; i++) {
      ctx.fillText(chars[i], cursorX, cy);
      cursorX += widths[i] + extraTracking;
    }
    ctx.restore();
  }

  // Smooth staggered reveal factor: enters [delay..delay+0.18], exits [0.82-exitDelay..1.0-exitDelay]
  function getCardMotion(p, enterDelay, exitDelay) {
    const enterDur = 0.18;
    const exitDur = 0.18;
    const eStart = enterDelay;
    const xStart = 0.82 - exitDelay;
    const inU = clamp((p - eStart) / enterDur, 0, 1);
    const outU = clamp((p - xStart) / exitDur, 0, 1);
    const inE = easeOutQuint(inU);
    const outE = easeInCubic(outU);
    const visibility = inE * (1 - outE);
    const cardVis = easeOutCubic(clamp(visibility * 1.35, 0, 1));
    const innerAlpha = easeOutCubic(clamp((visibility - 0.35) / 0.5, 0, 1));
    return {
      inE: inE,
      outE: outE,
      vis: visibility,
      cardVis: cardVis,
      innerAlpha: innerAlpha,
      slideOffset: (1 - inE) - outE
    };
  }

  // 1. Crisp Flat Background (Zero glow)
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Subtle Architectural Dot Grid in Central Field (Seamless 2-cycle loop)
  const bandH = height * 0.095;
  const gridCols = 16;
  const gridRows = 7;
  const gridLeft = width * 0.075;
  const gridRight = width * 0.925;
  const gridTop = height * 0.155;
  const gridBottom = height * 0.845;
  const dotPhaseBase = 2 * Math.PI * (safeLoopT / duration) * 2;
  ctx.fillStyle = COLORS.dot;
  for (let r = 0; r < gridRows; r++) {
    const dy = lerp(gridTop, gridBottom, r / (gridRows - 1));
    for (let c = 0; c < gridCols; c++) {
      const dx = lerp(gridLeft, gridRight, c / (gridCols - 1));
      const wave = 0.5 + 0.5 * Math.sin(dotPhaseBase - c * 0.36 - r * 0.42);
      const radius = minSide * (0.002 + 0.0012 * wave);
      ctx.beginPath();
      ctx.arc(dx, dy, radius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 3. Top & Bottom Continuous Kinetic Ticker Channels (Full-bleed, no outer border strokes)
  function drawTickerBand(y, h, text, dir, bgColor, textColor, accentColor) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y, width, h);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.clip();

    const fontSize = h * 0.36;
    ctx.font = '700 ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const tileW = ctx.measureText(text).width;
    const progress = safeLoopT / duration;
    const cycles = 2;
    const rawShift = progress * tileW * cycles * dir;
    let startX = ((rawShift % tileW) + tileW) % tileW - tileW;
    const centerY = y + h * 0.52;

    while (startX < width + tileW) {
      const segments = text.split('•');
      let curX = startX;
      for (let i = 0; i < segments.length; i++) {
        const seg = segments[i];
        ctx.fillStyle = textColor;
        ctx.fillText(seg, curX, centerY);
        curX += ctx.measureText(seg).width;
        if (i < segments.length - 1) {
          const dotW = ctx.measureText('•').width;
          ctx.fillStyle = accentColor;
          ctx.beginPath();
          ctx.arc(curX + dotW * 0.5, y + h * 0.5, minSide * 0.0045, 0, Math.PI * 2);
          ctx.fill();
          curX += dotW;
        }
      }
      startX += tileW;
    }
    ctx.restore();
  }

  drawTickerBand(
    0,
    bandH,
    'FLASH SALE   •   LIMITED TIME   •   UP TO 70% OFF   •   ONLINE EXCLUSIVE   •   ',
    -1,
    COLORS.cardDark,
    COLORS.chalk,
    COLORS.volt
  );

  drawTickerBand(
    height - bandH,
    bandH,
    'NEW DEALS   •   TODAY ONLY   •   FAST CHECKOUT   •   BEST OFFER   •   ',
    1,
    COLORS.cardDark,
    COLORS.chalkMuted,
    COLORS.volt
  );

  // Subtle flat anchor bar that bridges scene transitions cleanly at p=0 and p=1
  const stageX = width * 0.065;
  const stageW = width * 0.87;
  const stageY = height * 0.14;
  const stageH = height * 0.72;
  const gutter = minSide * 0.024;
  const cardR = minSide * 0.022;

  const anchorAlpha =
    sceneProgress < 0.14
      ? 1 - easeOutCubic(sceneProgress / 0.14)
      : sceneProgress > 0.86
      ? easeInCubic((sceneProgress - 0.86) / 0.14)
      : 0;

  if (anchorAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha = anchorAlpha;
    const barW = stageW * 0.28 * anchorAlpha;
    const barH = minSide * 0.006;
    fillRoundRect(
      width * 0.5 - barW * 0.5,
      height * 0.5 - barH * 0.5,
      barW,
      barH,
      barH * 0.5,
      COLORS.volt
    );
    ctx.restore();
  }

  // 4. Scene Choreography (All 4 Scenes, Strictly Non-Overlapping Zones)
  const p = sceneProgress;

  if (sceneIdx === 0) {
    // SCENE 0: "FLASH SALE" — Modular Split Reveal & Geometric Emblem
    const metaH = stageH * 0.11;
    const heroH = stageH * 0.31;
    const botH = stageH * 0.13;

    const rowMetaY = stageY;
    const rowHeroAY = stageY + stageH * 0.16;
    const rowHeroBY = stageY + stageH * 0.51;
    const rowBotY = stageY + stageH * 0.87;

    // Row 0: Meta Header
    const mMeta = getCardMotion(p, 0.0, 0.04);
    if (mMeta.vis > 0.001) {
      const leftPillW = stageW * 0.23;
      const rightPillW = stageW * 0.14;
      const slideY = mMeta.slideOffset * minSide * 0.03;

      ctx.save();
      ctx.globalAlpha = mMeta.vis;
      drawClippedCard(stageX, rowMetaY + slideY, leftPillW, metaH, metaH * 0.5, COLORS.volt, (cx, cy, cw, ch) => {
        const fs = fitFontSize('SPECIAL EVENT', cw * 0.82, ch * 0.48, minSide * 0.024, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('SPECIAL EVENT', cx + cw * 0.5, cy + ch * 0.52);
      });

      const lineStart = stageX + leftPillW + gutter;
      const lineEnd = stageX + stageW - rightPillW - gutter;
      const lineLen = Math.max(0, (lineEnd - lineStart) * mMeta.vis);
      fillRoundRect(lineStart, rowMetaY + metaH * 0.5 - minSide * 0.002 + slideY, lineLen, minSide * 0.004, minSide * 0.002, COLORS.rule);

      drawClippedCard(
        stageX + stageW - rightPillW,
        rowMetaY + slideY,
        rightPillW,
        metaH,
        metaH * 0.5,
        COLORS.cardDark,
        (cx, cy, cw, ch) => {
