    // Row 1: "FLASH" Card + Starburst Emblem Card
    const mA1 = getCardMotion(p, 0.03, 0.02);
    const mA2 = getCardMotion(p, 0.06, 0.0);
    const leftCardW = stageW * 0.66 - gutter * 0.5;
