    // Row 2: Chevron Flow Card + "SALE" Card
    const mB1 = getCardMotion(p, 0.05, 0.01);
    const mB2 = getCardMotion(p, 0.08, 0.0);
    const chevW = stageW * 0.34 - gutter * 0.5;
    const saleX = stageX + chevW + gutter;
    const saleW = stageW - chevW - gutter;

    if (mB1.vis > 0.001) {
