      const segH = botH * 0.46;
      const segY = rowBotY + (botH - segH) * 0.5 + slideY;
      const activeFloat = clamp((p - 0.15) / 0.65, 0, 1) * segCount;

      for (let i = 0; i < segCount; i++) {
        const sx = stageX + i * (segW + segGap);
        const lit = i < activeFloat;
        fillRoundRect(sx, segY, segW, segH, segH * 0.35, lit ? COLORS.volt : COLORS.cardDark);
