      drawClippedCard(offerX, rowBotY + slideY, offerW, botH, botH * 0.5, COLORS.cardDark, (cx, cy, cw, ch) => {
        const fs = fitFontSize('LIMITED TIME OFFER', cw * 0.84, ch * 0.48, minSide * 0.024, '800');
