  } else if (sceneIdx === 1) {
    // SCENE 1: "UP TO 70% OFF" — Precision Split-Zone Discount Reveal
    const leftW = stageW * 0.45;
    const rightX = stageX + leftW + gutter;
    const rightW = stageW - leftW - gutter;

    const mLeft = getCardMotion(p, 0.0, 0.02);
    if (mLeft.vis > 0.001) {
      const curH = stageH * mLeft.cardVis;
      const curY = stageY + (stageH - curH) * 0.5;
      drawClippedCard(stageX, curY, leftW, curH, cardR, COLORS.volt, (cx, cy, cw, ch) => {
        const pad = minSide * 0.048;
        const innerW = cw - pad * 2;
        const topZoneY = stageY + pad;
        const pillH = stageH * 0.105;

        // Sub-row 1: Top Pill
        const pillW = Math.min(innerW * 0.72, innerW);
        fillRoundRect(cx + pad, topZoneY, pillW, pillH, pillH * 0.5, COLORS.bg);
