        // Sub-row 2: Smooth Odometer Number Roll 10% -> 70%
        const countU = easeOutCubic(clamp((p - 0.1) / 0.45, 0, 1));
        const val = Math.round(lerp(10, 70, countU));
        const numText = val + '%';
        const numZoneY = stageY + stageH * 0.52;
        const nfs = fitFontSize('70%', innerW * 0.94, stageH * 0.42, minSide * 0.24, '900');
