        const trackPulse = Math.sin(clamp((p - 0.18) / 0.64, 0, 1) * Math.PI);
        const tracking = minSide * 0.006 * trackPulse;
        const maxTW = rightW - pad * 2 - dotSize - gutter - tracking * 9;
        const fs = fitFontSize('OFF TODAY', maxTW, h * 0.52, minSide * 0.072, '900');
