        const barW = (eqZoneW - barGap * (bars - 1)) / bars;
        const eqStartX = rightX + rightW - pad - eqZoneW;
        const maxBarH = h * 0.54;
        for (let i = 0; i < bars; i++) {
          const wave = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.75));
          const bh = maxBarH * wave;
          const bx = eqStartX + i * (barW + barGap);
          const by = cy + h * 0.5 - bh * 0.5;
          fillRoundRect(bx, by, barW, bh, barW * 0.5, i % 2 === 0 ? COLORS.volt : COLORS.chalkSoft);
        }
      }, mR3.innerAlpha);
    }
  } else if (sceneIdx === 2) {
    // SCENE 2: "HURRY • ACT NOW • TODAY ONLY" — 3-Track Kinetic Ribbon Cascade
    const trackGap = stageH * 0.055;
    const trackH = (stageH - trackGap * 2) / 3;
    const trackR = trackH * 0.24;

    const mT0 = getCardMotion(p, 0.0, 0.04);
    const mT1 = getCardMotion(p, 0.04, 0.02);
    const mT2 = getCardMotion(p, 0.08, 0.0);

    // Track 0: "HURRY" + Smooth Clipped Chevron Channel
    if (mT0.vis > 0.001) {
      const y0 = stageY;
      const cw = stageW * mT0.cardVis;
      drawClippedCard(stageX, y0, cw, trackH, trackR, COLORS.cardDark, (cx, cy, w, h) => {
        const pad = minSide * 0.045;
        const badgeD = h * 0.48;
