        ctx.fillText('HURRY', textStartX, cy + h * 0.52);

        // Right clipped chevron track with smooth edge fade
        const chanX = stageX + stageW - pad - chevZoneW;
        ctx.save();
        ctx.beginPath();
        ctx.rect(chanX, cy, chevZoneW, h);
        ctx.clip();
        const step = chevZoneW * 0.28;
        const flow = (p * 1.8) % 1;
        const cs = minSide * 0.032;
        const fadeMargin = chevZoneW * 0.16;
        for (let i = -1; i <= 4; i++) {
