        const chevZoneW = stageW * 0.22;
        const maxTW = stageW - pad * 2 - chevZoneW * 2 - gutter * 2;
        const trackPulse = Math.sin(clamp((p - 0.16) / 0.68, 0, 1) * Math.PI);
        const tracking = minSide * 0.007 * trackPulse;
        const fs = fitFontSize('ACT NOW', maxTW - tracking * 7, h * 0.62, minSide * 0.095, '900');

