        const cs = minSide * 0.032;
        const drift = Math.sin(p * Math.PI * 4) * minSide * 0.012;
        // Left inward chevrons strictly within left chevZone
        const leftEnd = stageX + pad + chevZoneW;
        for (let i = 0; i < 3; i++) {
