        ctx.font = '800 ' + pfs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.volt;
        ctx.textAlign = 'center';
        ctx.fillText('24H DEAL', pillX + pillW * 0.5, pillY + pillH * 0.52);

