    const midY = stageY + topH + tierGap;
    const botY = midY + midH + tierGap;

    // Top Tier: 3 Equal Micro-Benefit Cards
    const benefits = ['FAST DELIVERY', 'BEST PRICE', 'TOP QUALITY'];
    const microW = (stageW - gutter * 2) / 3;
    for (let i = 0; i < 3; i++) {
      const mMicro = getCardMotion(p, i * 0.03, (2 - i) * 0.02);
      if (mMicro.vis > 0.001) {
        const mx = stageX + i * (microW + gutter);
        const slideY = mMicro.slideOffset * minSide * 0.025;
        ctx.save();
        ctx.globalAlpha = mMicro.vis;
        drawClippedCard(mx, topY + slideY, microW, topH, minSide * 0.016, COLORS.cardDark, (cx, cy, cw, ch) => {
          const dotR = minSide * 0.008;
          const pad = minSide * 0.03;
          const gapDot = minSide * 0.016;
          const maxTW = cw - pad * 2 - dotR * 2 - gapDot;
          const fs = fitFontSize(benefits[i], maxTW, ch * 0.48, minSide * 0.025, '800');
          ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
          const tw = ctx.measureText(benefits[i]).width;
          const groupW = dotR * 2 + gapDot + tw;
          const startX = cx + (cw - groupW) * 0.5;

          ctx.beginPath();
          ctx.arc(startX + dotR, cy + ch * 0.5, dotR, 0, Math.PI * 2);
          ctx.fillStyle = COLORS.volt;
          ctx.fill();

          ctx.fillStyle = COLORS.chalk;
          ctx.textAlign = 'left';
          ctx.textBaseline = 'middle';
          ctx.fillText(benefits[i], startX + dotR * 2 + gapDot, cy + ch * 0.52);
        });
        ctx.restore();
      }
    }

    // Middle Tier: Left Wing + Center "SHOP NOW" Hero + Right Wing
    const wingW = stageW * 0.2;
    const centerW = stageW - wingW * 2 - gutter * 2;
    const centerX = stageX + wingW + gutter;
    const rightX = centerX + centerW + gutter;

    const mWingL = getCardMotion(p, 0.04, 0.02);
    const mHero = getCardMotion(p, 0.02, 0.0);
    const mWingR = getCardMotion(p, 0.06, 0.02);

    if (mWingL.vis > 0.001) {
      const curH = midH * mWingL.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(stageX, curY, wingW, curH, cardR, COLORS.cardMid, (cx, cy, cw, ch) => {
        const starR = Math.min(cw, midH) * 0.26 * mWingL.innerAlpha;
        const rot = easeInOutQuart(p) * Math.PI;
        drawStarburst(cx + cw * 0.5, midY + midH * 0.42, starR, starR * 0.42, 4, rot, COLORS.volt);

        const fs = fitFontSize('24H', cw * 0.7, midH * 0.16, minSide * 0.032, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.chalk;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('24H', cx + cw * 0.5, midY + midH * 0.78);
      }, mWingL.innerAlpha);
    }

    if (mHero.vis > 0.001) {
      const curW = centerW * mHero.cardVis;
      const curX = centerX + (centerW - curW) * 0.5;
      drawClippedCard(curX, midY, curW, midH, cardR, COLORS.volt, (cx, cy, cw, ch) => {
        const pad = minSide * 0.05;
        const btnR = Math.min(centerW * 0.125, midH * 0.24);
        const btnGap = minSide * 0.036;
        const maxTW = centerW - pad * 2 - btnR * 2 - btnGap;
        const fs = fitFontSize('SHOP NOW', maxTW, ch * 0.5, minSide * 0.092, '900');
        ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
        const tw = ctx.measureText('SHOP NOW').width;
        const groupW = tw + btnGap + btnR * 2;
        const startX = centerX + (centerW - groupW) * 0.5;

        ctx.fillStyle = COLORS.bg;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('SHOP NOW', startX, cy + ch * 0.52);

        const btnCX = startX + tw + btnGap + btnR;
        const btnCY = cy + ch * 0.5;
        ctx.beginPath();
        ctx.arc(btnCX, btnCY, btnR, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.bg;
        ctx.fill();

        const arrowGlide = Math.sin(p * Math.PI * 4) * btnR * 0.14;
        drawChevron(btnCX + arrowGlide, btnCY, btnR * 0.42, minSide * 0.009, 1, COLORS.volt);
      }, mHero.innerAlpha);
    }

    if (mWingR.vis > 0.001) {
      const curH = midH * mWingR.cardVis;
      const curY = midY + (midH - curH) * 0.5;
      drawClippedCard(rightX, curY, wingW, curH, cardR, COLORS.cardMid, (cx, cy, cw, ch) => {
        const pad = minSide * 0.032;
        const fs = fitFontSize('04 / 04', cw * 0.76, midH * 0.16, minSide * 0.025, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        ctx.fillStyle = COLORS.volt;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('04 / 04', cx + cw * 0.5, midY + midH * 0.24);

        const bars = 4;
        const barAreaW = cw - pad * 2;
        const barH = minSide * 0.014;
        const barGap = minSide * 0.018;
        const startBarY = midY + midH * 0.42;
        for (let i = 0; i < bars; i++) {
          const wave = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - i * 0.8));
          const bw = barAreaW * wave;
          fillRoundRect(cx + pad, startBarY + i * (barH + barGap), bw, barH, barH * 0.5, i === 0 ? COLORS.volt : COLORS.chalk);
        }
      }, mWingR.innerAlpha);
    }

    // Bottom Tier: "DON'T MISS OUT — LIMITED STOCK" + Symmetrical Smooth Guide Rules
    const mBot = getCardMotion(p, 0.08, 0.03);
    if (mBot.vis > 0.001) {
      const slideY = -mBot.slideOffset * minSide * 0.025;
      ctx.save();
      ctx.globalAlpha = mBot.vis;
      drawClippedCard(stageX, botY + slideY, stageW, botH, botH * 0.5, COLORS.cardDark, (cx, cy, cw, ch) => {
        const label = "DON'T MISS OUT  •  LIMITED STOCK";
        const pad = minSide * 0.045;
        const fs = fitFontSize(label, cw * 0.58, ch * 0.48, minSide * 0.026, '800');
        ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
        const textW = ctx.measureText(label).width;
        ctx.fillStyle = COLORS.chalk;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, cx + cw * 0.5, cy + ch * 0.52);

        const availLine = Math.max(0, (cw - textW) * 0.5 - pad - gutter * 1.5);
        const lineProgress = easeInOutQuart(clamp((p - 0.14) / 0.68, 0, 1));
        const lineW = availLine * lineProgress;
        const lineH = minSide * 0.005;
        const lineY = cy + ch * 0.5 - lineH * 0.5;
        if (lineW > 1) {
          fillRoundRect(cx + pad, lineY, lineW, lineH, lineH * 0.5, COLORS.volt);
          fillRoundRect(cx + cw - pad - lineW, lineY, lineW, lineH, lineH * 0.5, COLORS.volt);
        }
      });
      ctx.restore();
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const sceneIdx = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const safeLoopT = loopT < 0 ? loopT + duration : loopT;

  const PALETTE = {
    bg: '#F4EFE6',
    ink: '#121212',
    vermilion: '#FF3B1D',
    stone: '#DFD7C8',
    stoneMuted: '#C7BEB0',
    charcoal: '#59544C'
  };

  const FONT_FAMILY = "'Segoe UI', 'Helvetica Neue', Arial, sans-serif";

  function clamp(v, min, max) {
    return v < min ? min : v > max ? max : v;
  }

  function lerp(a, b, u) {
    return a + (b - a) * u;
  }

  function easeOutCubic(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 3);
  }

  function easeInCubic(u) {
    const x = clamp(u, 0, 1);
    return x * x * x;
  }

  function easeOutQuint(u) {
    const x = clamp(u, 0, 1);
    return 1 - Math.pow(1 - x, 5);
  }

  function easeInOutQuart(u) {
    const x = clamp(u, 0, 1);
    return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
  }

  function roundRectPath(x, y, w, h, r) {
    const rad = Math.max(0, Math.min(r, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function fillRoundRect(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    roundRectPath(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function fitFontSize(text, maxW, maxH, targetSize, weight) {
    let size = Math.min(targetSize, maxH);
    ctx.font = weight + ' ' + size + 'px ' + FONT_FAMILY;
    const measured = ctx.measureText(text).width;
    if (measured > maxW && measured > 0) {
      size = size * (maxW / measured);
    }
    return Math.max(8, size);
  }

  function drawChevron(cx, cy, size, strokeW, dir, color, vertical) {
    ctx.save();
    ctx.translate(cx, cy);
    if (vertical) {
      ctx.rotate(-Math.PI * 0.5 * dir);
    } else {
      ctx.scale(dir, 1);
    }
    ctx.beginPath();
    ctx.moveTo(-size * 0.4, -size * 0.72);
    ctx.lineTo(size * 0.4, 0);
    ctx.lineTo(-size * 0.4, size * 0.72);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();
  }

  function drawSwissAsterisk(cx, cy, radius, spokes, strokeW, angle, color) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.strokeStyle = color;
    ctx.lineWidth = strokeW;
    ctx.lineCap = 'round';
    for (let i = 0; i < spokes; i++) {
      const a = (i * Math.PI) / spokes;
      const dx = Math.cos(a) * radius;
      const dy = Math.sin(a) * radius;
      ctx.beginPath();
      ctx.moveTo(-dx, -dy);
      ctx.lineTo(dx, dy);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawMarqueeInRect(x, y, w, h, text, dir, speedCycles, fontSize, weight, textColor, dotColor) {
    if (w <= 2 || h <= 2) return;
    ctx.save();
    ctx.beginPath();
    ctx.rect(x, y, w, h);
    ctx.clip();

    ctx.font = weight + ' ' + fontSize + 'px ' + FONT_FAMILY;
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    const tileW = ctx.measureText(text).width;
    if (tileW > 0) {
      const shift = (safeLoopT / duration) * tileW * speedCycles * dir;
      let curStart = ((shift % tileW) + tileW) % tileW - tileW;
      const cy = y + h * 0.52;
      const dotR = Math.max(2, fontSize * 0.14);

      while (curStart < x + w + tileW) {
        const parts = text.split('•');
        let cx = curStart;
        for (let i = 0; i < parts.length; i++) {
          const seg = parts[i];
          ctx.fillStyle = textColor;
          ctx.fillText(seg, cx, cy);
          cx += ctx.measureText(seg).width;
          if (i < parts.length - 1) {
            const dw = ctx.measureText('•').width;
            ctx.fillStyle = dotColor;
            ctx.beginPath();
            ctx.arc(cx + dw * 0.5, y + h * 0.5, dotR, 0, Math.PI * 2);
            ctx.fill();
            cx += dw;
          }
        }
        curStart += tileW;
      }
    }
    ctx.restore();
  }

  // Smooth content reveal envelope: enters [0..0.18], steady [0.18..0.76], exits [0.76..0.88]
  // Color wipes run cleanly in [0.85..0.99] after content has exited!
  const p = sceneProgress;
  const contentIn = easeOutQuint(clamp(p / 0.18, 0, 1));
  const contentOut = easeInCubic(clamp((p - 0.76) / 0.12, 0, 1));
  const contentVis = contentIn * (1 - contentOut);
  const contentSlide = (1 - contentIn) - contentOut;

  // 1. Crisp Flat Warm Alabaster Background (Zero glow, zero outer edge strokes)
  ctx.fillStyle = PALETTE.bg;
  ctx.fillRect(0, 0, width, height);

  // 2. Continuous Parametric 3x3 Grid Interpolation Across Scene Boundaries
  const boundaryCols = [
    [0.24, 0.52, 0.24],
    [0.27, 0.48, 0.25],
    [0.25, 0.50, 0.25]
  ];
  const midCols = [
    [0.21, 0.57, 0.22],
    [0.20, 0.60, 0.20],
    [0.29, 0.47, 0.24]
  ];
  const boundaryRows = [
    [0.20, 0.58, 0.22],
    [0.21, 0.57, 0.22],
    [0.20, 0.58, 0.22]
  ];
  const midRows = [
    [0.19, 0.60, 0.21],
    [0.18, 0.64, 0.18],
    [0.19, 0.59, 0.22]
  ];

  const nextIdx = (sceneIdx + 1) % sceneCount;
  let colRatios;
  let rowRatios;
  if (p < 0.5) {
    const u = easeInOutQuart(p * 2);
    colRatios = [
      lerp(boundaryCols[sceneIdx][0], midCols[sceneIdx][0], u),
      lerp(boundaryCols[sceneIdx][1], midCols[sceneIdx][1], u),
      lerp(boundaryCols[sceneIdx][2], midCols[sceneIdx][2], u)
    ];
    rowRatios = [
      lerp(boundaryRows[sceneIdx][0], midRows[sceneIdx][0], u),
      lerp(boundaryRows[sceneIdx][1], midRows[sceneIdx][1], u),
      lerp(boundaryRows[sceneIdx][2], midRows[sceneIdx][2], u)
    ];
  } else {
    const u = easeInOutQuart((p - 0.5) * 2);
    colRatios = [
      lerp(midCols[sceneIdx][0], boundaryCols[nextIdx][0], u),
      lerp(midCols[sceneIdx][1], boundaryCols[nextIdx][1], u),
      lerp(midCols[sceneIdx][2], boundaryCols[nextIdx][2], u)
    ];
    rowRatios = [
      lerp(midRows[sceneIdx][0], boundaryRows[nextIdx][0], u),
      lerp(midRows[sceneIdx][1], boundaryRows[nextIdx][1], u),
      lerp(midRows[sceneIdx][2], boundaryRows[nextIdx][2], u)
    ];
  }

  const marginX = width * 0.04;
  const marginY = height * 0.055;
  const gutter = minSide * 0.018;
  const usableW = width - marginX * 2 - gutter * 2;
  const usableH = height - marginY * 2 - gutter * 2;
  const cellR = minSide * 0.012;

  const colW = [usableW * colRatios[0], usableW * colRatios[1], usableW * colRatios[2]];
  const rowH = [usableH * rowRatios[0], usableH * rowRatios[1], usableH * rowRatios[2]];
  const colX = [marginX, marginX + colW[0] + gutter, marginX + colW[0] + colW[1] + gutter * 2];
  const rowY = [marginY, marginY + rowH[0] + gutter, marginY + rowH[0] + rowH[1] + gutter * 2];

  // Cell color matrices [scene][row][col]
  const SCENE_COLORS = [
    [
      [PALETTE.stone, PALETTE.ink, PALETTE.vermilion],
      [PALETTE.ink, PALETTE.stone, PALETTE.vermilion],
      [PALETTE.stone, PALETTE.ink, PALETTE.stone]
    ],
    [
      [PALETTE.ink, PALETTE.vermilion, PALETTE.stone],
      [PALETTE.stone, PALETTE.ink, PALETTE.stone],
      [PALETTE.vermilion, PALETTE.stone, PALETTE.ink]
    ],
    [
      [PALETTE.stone, PALETTE.ink, PALETTE.vermilion],
      [PALETTE.vermilion, PALETTE.stone, PALETTE.ink],
      [PALETTE.ink, PALETTE.vermilion, PALETTE.stone]
    ]
  ];

  // Draw all 9 strictly separated cells with smooth staggered transition wipes at p=[0.85..0.99]
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const cx = colX[c];
      const cy = rowY[r];
      const cw = colW[c];
      const ch = rowH[r];
      const baseColor = SCENE_COLORS[sceneIdx][r][c];
      const nextColor = SCENE_COLORS[nextIdx][r][c];

      ctx.save();
      roundRectPath(cx, cy, cw, ch, cellR);
      ctx.fillStyle = baseColor;
      ctx.fill();
      ctx.clip();

      // Staggered color wipe for seamless transition into next scene
      const wipeDelay = (r * 0.25 + c * 0.25) * 0.04;
      const wipeU = easeInOutQuart(clamp((p - (0.85 + wipeDelay)) / 0.1, 0, 1));
      if (wipeU > 0.001 && nextColor !== baseColor) {
        ctx.fillStyle = nextColor;
        if ((r + c) % 2 === 0) {
          ctx.fillRect(cx, cy, cw, ch * wipeU);
        } else {
          ctx.fillRect(cx, cy, cw * wipeU, ch);
        }
      }

      // Render cell content inside strict safe inset padding
      if (contentVis > 0.002) {
        const padX = Math.min(cw * 0.1, minSide * 0.032);
        const padY = Math.min(ch * 0.12, minSide * 0.026);
        const ix = cx + padX;
        const iy = cy + padY;
        const iw = Math.max(4, cw - padX * 2);
        const ih = Math.max(4, ch - padY * 2);

        ctx.save();
        ctx.beginPath();
        ctx.rect(cx, iy, cw, ih);
        ctx.clip();

        const slideY = contentSlide * ih * 0.22;
        const slideX = contentSlide * iw * 0.18;
        ctx.globalAlpha = contentVis;

        if (sceneIdx === 0) {
          // SCENE 0: MEGA DROP
          if (r === 0 && c === 0) {
            const dotR = minSide * 0.009;
            const fs = fitFontSize('01 / DROP', iw - dotR * 3.5, ih * 0.58, minSide * 0.032, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('01 / DROP', ix, iy + ih * 0.52 + slideY);

            ctx.beginPath();
            ctx.arc(ix + iw - dotR, iy + ih * 0.5 + slideY, dotR, 0, Math.PI * 2);
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fill();
          } else if (r === 0 && c === 1) {
            const mfs = fitFontSize('NEW SEASON', iw * 0.35, ih * 0.48, minSide * 0.028, '700');
            drawMarqueeInRect(
              cx,
              iy + slideY * 0.4,
              cw,
              ih,
              'NEW SEASON   •   ARCHIVE EDIT   •   LIMITED RELEASE   •   ',
              -1,
              4,
              mfs,
              '700',
              PALETTE.bg,
              PALETTE.vermilion
            );
          } else if (r === 0 && c === 2) {
            const rad = Math.min(iw, ih) * 0.36;
            const rot = easeInOutQuart(clamp(p / 0.85, 0, 1)) * Math.PI;
            drawSwissAsterisk(ix + iw * 0.5, iy + ih * 0.5, rad, 4, minSide * 0.008, rot, PALETTE.bg);
          } else if (r === 1 && c === 0) {
            const topY = iy + ih * 0.24 + slideY;
            const midY = iy + ih * 0.56 + slideY;
            const fs1 = fitFontSize('NEW', iw * 0.85, ih * 0.24, minSide * 0.068, '900');
            ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('NEW', ix, topY);

            const fs2 = fitFontSize('2026', iw * 0.85, ih * 0.24, minSide * 0.068, '900');
            ctx.font = '900 ' + fs2 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fillText('2026', ix, midY);

            const barY = iy + ih * 0.84;
            const barH = minSide * 0.012;
            const fillU = easeInOutQuart(clamp((p - 0.14) / 0.6, 0, 1));
            fillRoundRect(ix, barY, iw, barH, barH * 0.5, PALETTE.charcoal);
            fillRoundRect(ix, barY, iw * fillU, barH, barH * 0.5, PALETTE.bg);
          } else if (r === 1 && c === 1) {
            const megaY = iy + ih * 0.27 - slideY * 0.6;
            const dropY = iy + ih * 0.64 + slideY * 0.6;
            const fsMega = fitFontSize('MEGA', iw * 0.94, ih * 0.34, minSide * 0.165, '900');
            const fsDrop = fitFontSize('DROP', iw * 0.94, ih * 0.34, minSide * 0.165, '900');

            ctx.font = '900 ' + fsMega + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('MEGA', ix + iw * 0.5, megaY);

            ctx.font = '900 ' + fsDrop + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fillText('DROP', ix + iw * 0.5, dropY);

            const ruleY = iy + ih * 0.9;
            const ruleH = minSide * 0.011;
            const ruleU = easeOutCubic(clamp((p - 0.12) / 0.24, 0, 1));
            const ruleW = iw * 0.72 * ruleU;
            fillRoundRect(ix + (iw - ruleW) * 0.5, ruleY, ruleW, ruleH, ruleH * 0.5, PALETTE.ink);
          } else if (r === 1 && c === 2) {
            const fs = fitFontSize('HOT', iw * 0.8, ih * 0.18, minSide * 0.056, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('HOT', ix + iw * 0.5, iy + ih * 0.14 + slideY);

            const chanY = iy + ih * 0.3;
            const chanH = ih * 0.64;
            ctx.save();
            ctx.beginPath();
            ctx.rect(ix, chanY, iw, chanH);
            ctx.clip();
            const step = chanH * 0.28;
            const flow = (p * 2.1) % 1;
            const cs = Math.min(iw * 0.28, minSide * 0.044);
            const fadeMargin = chanH * 0.18;
            for (let k = -1; k <= 4; k++) {
              const py = chanY + chanH - (k + flow) * step;
              const distEdge = Math.min(py - chanY, chanY + chanH - py);
              const alpha = clamp(distEdge / fadeMargin, 0, 1);
              if (alpha > 0.01) {
                ctx.save();
                ctx.globalAlpha *= alpha;
                drawChevron(ix + iw * 0.5, py, cs, minSide * 0.009, 1, PALETTE.bg, true);
                ctx.restore();
              }
            }
            ctx.restore();
          } else if (r === 2 && c === 0) {
            const fs = fitFontSize('UP TO 50%', iw * 0.92, ih * 0.54, minSide * 0.036, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('UP TO 50%', ix + iw * 0.5, iy + ih * 0.52 + slideY);
          } else if (r === 2 && c === 1) {
            const meterW = minSide * 0.11;
            const gapM = minSide * 0.028;
            const bars = 5;
            const bGap = minSide * 0.009;
            const bw = (meterW - bGap * (bars - 1)) / bars;
            const maxTW = iw - meterW - gapM;
            const fs = fitFontSize('EXCLUSIVE ONLINE ACCESS', maxTW, ih * 0.48, minSide * 0.028, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            const tw = ctx.measureText('EXCLUSIVE ONLINE ACCESS').width;
            const groupW = meterW + gapM + tw;
            const startX = ix + (iw - groupW) * 0.5;

            for (let b = 0; b < bars; b++) {
              const wave = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - b * 0.8));
              const bh = ih * 0.48 * wave;
              fillRoundRect(
                startX + b * (bw + bGap),
                iy + ih * 0.5 - bh * 0.5,
                bw,
                bh,
                bw * 0.5,
                b % 2 === 0 ? PALETTE.vermilion : PALETTE.bg
              );
            }
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('EXCLUSIVE ONLINE ACCESS', startX + meterW + gapM, iy + ih * 0.52 + slideY);
          } else if (r === 2 && c === 2) {
            const pillH = Math.min(ih * 0.66, minSide * 0.068);
            const pillW = Math.min(iw * 0.92, minSide * 0.24);
            const px = ix + (iw - pillW) * 0.5;
            const py = iy + (ih - pillH) * 0.5 + slideY;
            fillRoundRect(px, py, pillW, pillH, pillH * 0.5, PALETTE.ink);

            const arrowSlot = pillH * 0.55;
            const fs = fitFontSize('EXPLORE', pillW - arrowSlot - minSide * 0.03, pillH * 0.46, minSide * 0.024, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('EXPLORE', px + pillH * 0.38, py + pillH * 0.52);

            const arrowDrift = Math.sin(p * Math.PI * 4) * minSide * 0.005;
            drawChevron(
              px + pillW - pillH * 0.42 + arrowDrift,
              py + pillH * 0.5,
              pillH * 0.22,
              minSide * 0.0045,
              1,
              PALETTE.vermilion,
              false
            );
          }
        } else if (sceneIdx === 1) {
          // SCENE 1: 50% OFF — BEST OFFER (Color-Inverted Centerpiece)
          if (r === 0 && c === 0) {
            const dotR = minSide * 0.009;
            const fs = fitFontSize('02 / OFFER', iw - dotR * 3.5, ih * 0.58, minSide * 0.03, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('02 / OFFER', ix, iy + ih * 0.52 + slideY);

            ctx.beginPath();
            ctx.arc(ix + iw - dotR, iy + ih * 0.5 + slideY, dotR, 0, Math.PI * 2);
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fill();
          } else if (r === 0 && c === 1) {
            const mfs = fitFontSize('BEST OFFER', iw * 0.35, ih * 0.48, minSide * 0.028, '800');
            drawMarqueeInRect(
              cx,
              iy + slideY * 0.4,
              cw,
              ih,
              'BEST OFFER   •   SPECIAL PRICE   •   LIMITED STOCK   •   ',
              -1,
              4,
              mfs,
              '800',
              PALETTE.bg,
              PALETTE.ink
            );
          } else if (r === 0 && c === 2) {
            const barH = minSide * 0.016;
            const barY = iy + (ih - barH) * 0.5;
            const fillU = easeInOutQuart(clamp((p - 0.12) / 0.62, 0, 1));
            fillRoundRect(ix, barY, iw, barH, barH * 0.5, PALETTE.stoneMuted);
            fillRoundRect(ix, barY, iw * fillU, barH, barH * 0.5, PALETTE.ink);
          } else if (r === 1 && c === 0) {
            const bars = 5;
            const bGap = ih * 0.08;
            const bh = (ih - bGap * (bars - 1)) / bars;
            for (let b = 0; b < bars; b++) {
              const wave = 0.42 + 0.58 * (0.5 + 0.5 * Math.sin(p * Math.PI * 4 - b * 0.7));
              const bw = iw * wave;
              fillRoundRect(
                ix,
                iy + b * (bh + bGap),
                bw,
                Math.min(bh, minSide * 0.02),
                minSide * 0.01,
                b % 2 === 0 ? PALETTE.ink : PALETTE.vermilion
              );
            }
          } else if (r === 1 && c === 1) {
            // Top internal marquee strip (full cell width)
            const stripH = ih * 0.13;
            const mfs = fitFontSize('CLEARANCE', iw * 0.32, stripH * 0.78, minSide * 0.022, '700');
            drawMarqueeInRect(
              cx,
              iy,
              cw,
              stripH,
              'CLEARANCE   •   SPECIAL DROP   •   LIMITED TIME   •   ',
              1,
              3,
              mfs,
              '700',
              PALETTE.stone,
              PALETTE.vermilion
            );

            // Center giant "50%" + Vermilion pill "OFF" strictly separated
            const numY = iy + ih * 0.41 + slideY * 0.5;
            const nfs = fitFontSize('50%', iw * 0.9, ih * 0.38, minSide * 0.2, '900');
            ctx.font = '900 ' + nfs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('50%', ix + iw * 0.5, numY);

            const pillW = Math.min(iw * 0.44, minSide * 0.24);
            const pillH = ih * 0.16;
            const px = ix + (iw - pillW) * 0.5;
            const py = iy + ih * 0.64 + slideY * 0.3;
            fillRoundRect(px, py, pillW, pillH, pillH * 0.5, PALETTE.vermilion);
            const pfs = fitFontSize('OFF', pillW * 0.72, pillH * 0.62, minSide * 0.048, '900');
            ctx.font = '900 ' + pfs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.fillText('OFF', px + pillW * 0.5, py + pillH * 0.53);

            // Bottom internal marquee strip (full cell width, opposite direction)
            drawMarqueeInRect(
              cx,
              iy + ih - stripH,
              cw,
              stripH,
              'BEST OFFER   •   ONLINE EXCLUSIVE   •   FLASH PRICE   •   ',
              -1,
              3,
              mfs,
              '700',
              PALETTE.vermilion,
              PALETTE.bg
            );
          } else if (r === 1 && c === 2) {
            const fs1 = fitFontSize('SAVE', iw * 0.85, ih * 0.2, minSide * 0.056, '900');
            ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('SAVE', ix + iw * 0.5, iy + ih * 0.2 + slideY);

            const fs2 = fitFontSize('NOW', iw * 0.85, ih * 0.2, minSide * 0.056, '900');
            ctx.font = '900 ' + fs2 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fillText('NOW', ix + iw * 0.5, iy + ih * 0.42 + slideY);

            const dialR = Math.min(iw, ih) * 0.16;
            const dialCX = ix + iw * 0.5;
            const dialCY = iy + ih * 0.76;
            const rot = p * Math.PI * 2;
            ctx.beginPath();
            ctx.arc(dialCX, dialCY, dialR, 0, Math.PI * 2);
            ctx.strokeStyle = PALETTE.stoneMuted;
            ctx.lineWidth = minSide * 0.008;
            ctx.stroke();

            ctx.beginPath();
            ctx.arc(dialCX, dialCY, dialR, rot, rot + Math.PI * 1.25);
            ctx.strokeStyle = PALETTE.ink;
            ctx.lineWidth = minSide * 0.008;
            ctx.lineCap = 'round';
            ctx.stroke();
          } else if (r === 2 && c === 0) {
            const step = iw * 0.34;
            const flow = (p * 1.8) % 1;
            const cs = Math.min(ih * 0.36, minSide * 0.036);
            const fadeMargin = iw * 0.18;
            ctx.save();
            ctx.beginPath();
            ctx.rect(ix, iy, iw, ih);
            ctx.clip();
            for (let k = -1; k <= 3; k++) {
              const px = ix + (k + flow) * step;
              const distEdge = Math.min(px - ix, ix + iw - px);
              const alpha = clamp(distEdge / fadeMargin, 0, 1);
              if (alpha > 0.01) {
                ctx.save();
                ctx.globalAlpha *= alpha;
                drawChevron(px, iy + ih * 0.5, cs, minSide * 0.008, 1, PALETTE.bg, false);
                ctx.restore();
              }
            }
            ctx.restore();
          } else if (r === 2 && c === 1) {
            const fs = fitFontSize('ALL CATEGORIES  •  CURATED DEALS', iw * 0.92, ih * 0.52, minSide * 0.028, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('ALL CATEGORIES  •  CURATED DEALS', ix + iw * 0.5, iy + ih * 0.52 + slideY);
          } else if (r === 2 && c === 2) {
            const ringR = Math.min(iw, ih) * 0.34;
            const gapR = minSide * 0.024;
            const fs = fitFontSize('24H', iw - ringR * 2 - gapR, ih * 0.52, minSide * 0.034, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            const tw = ctx.measureText('24H').width;
            const groupW = ringR * 2 + gapR + tw;
            const rcx = ix + (iw - groupW) * 0.5 + ringR;
            const rcy = iy + ih * 0.5;

            ctx.beginPath();
            ctx.arc(rcx, rcy, ringR, 0, Math.PI * 2);
            ctx.strokeStyle = PALETTE.charcoal;
            ctx.lineWidth = minSide * 0.007;
            ctx.stroke();

            const arcSweep = easeInOutQuart(clamp((p - 0.1) / 0.65, 0, 1)) * Math.PI * 2;
            if (arcSweep > 0.01) {
              ctx.beginPath();
              ctx.arc(rcx, rcy, ringR, -Math.PI * 0.5, -Math.PI * 0.5 + arcSweep);
              ctx.strokeStyle = PALETTE.vermilion;
              ctx.lineWidth = minSide * 0.007;
              ctx.lineCap = 'round';
              ctx.stroke();
            }

            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('24H', rcx + ringR + gapR, rcy + minSide * 0.002 + slideY);
          }
        } else {
          // SCENE 2: GET YOURS — CLEARANCE FINALE
          if (r === 0 && c === 0) {
            const dotR = minSide * 0.009;
            const fs = fitFontSize('03 / FINAL', iw - dotR * 3.5, ih * 0.58, minSide * 0.03, '800');
            ctx.font = '800 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('03 / FINAL', ix, iy + ih * 0.52 + slideY);

            ctx.beginPath();
            ctx.arc(ix + iw - dotR, iy + ih * 0.5 + slideY, dotR, 0, Math.PI * 2);
            ctx.fillStyle = PALETTE.vermilion;
            ctx.fill();
          } else if (r === 0 && c === 1) {
            const mfs = fitFontSize('FINAL CALL', iw * 0.35, ih * 0.48, minSide * 0.028, '700');
            drawMarqueeInRect(
              cx,
              iy + slideY * 0.4,
              cw,
              ih,
              'FINAL CALL   •   CLEARANCE EVENT   •   SHOP TODAY   •   ',
              1,
              4,
              mfs,
              '700',
              PALETTE.bg,
              PALETTE.vermilion
            );
          } else if (r === 0 && c === 2) {
            const orbitR = Math.min(iw, ih) * 0.28;
            const dotR = minSide * 0.008;
            const baseA = easeInOutQuart(clamp(p / 0.85, 0, 1)) * Math.PI * 2;
            for (let d = 0; d < 4; d++) {
              const a = baseA + (d * Math.PI) * 0.5;
              ctx.beginPath();
              ctx.arc(
                ix + iw * 0.5 + Math.cos(a) * orbitR,
                iy + ih * 0.5 + Math.sin(a) * orbitR,
                dotR,
                0,
                Math.PI * 2
              );
              ctx.fillStyle = PALETTE.bg;
              ctx.fill();
            }
          } else if (r === 1 && c === 0) {
            const fs = fitFontSize('GET', iw * 0.9, ih * 0.38, minSide * 0.12, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('GET', ix + iw * 0.5 - slideX, iy + ih * 0.44);

            const ruleU = easeOutCubic(clamp((p - 0.12) / 0.24, 0, 1));
            const ruleH = minSide * 0.011;
            const ruleW = iw * 0.68 * ruleU;
            fillRoundRect(ix + (iw - ruleW) * 0.5, iy + ih * 0.72, ruleW, ruleH, ruleH * 0.5, PALETTE.ink);
          } else if (r === 1 && c === 1) {
            const fs = fitFontSize('YOURS', iw * 0.92, ih * 0.42, minSide * 0.155, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.ink;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('YOURS', ix + iw * 0.5, iy + ih * 0.34 - slideY * 0.5);

            const pillW = Math.min(iw * 0.72, minSide * 0.38);
            const pillH = ih * 0.2;
            const px = ix + (iw - pillW) * 0.5;
            const py = iy + ih * 0.62 + slideY * 0.4;
            fillRoundRect(px, py, pillW, pillH, pillH * 0.5, PALETTE.vermilion);
            const pfs = fitFontSize('CLEARANCE', pillW * 0.78, pillH * 0.54, minSide * 0.036, '900');
            ctx.font = '900 ' + pfs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.fillText('CLEARANCE', px + pillW * 0.5, py + pillH * 0.52);

            const ruleU = easeOutCubic(clamp((p - 0.12) / 0.24, 0, 1));
            const ruleH = minSide * 0.01;
            const ruleW = iw * 0.72 * ruleU;
            fillRoundRect(ix + (iw - ruleW) * 0.5, iy + ih * 0.91, ruleW, ruleH, ruleH * 0.5, PALETTE.ink);
          } else if (r === 1 && c === 2) {
            const fs1 = fitFontSize('50%', iw * 0.84, ih * 0.24, minSide * 0.072, '900');
            ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.vermilion;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('50%', ix + iw * 0.5, iy + ih * 0.24 + slideY);

            const fs2 = fitFontSize('FINAL', iw * 0.84, ih * 0.18, minSide * 0.044, '800');
            ctx.font = '800 ' + fs2 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.fillText('FINAL', ix + iw * 0.5, iy + ih * 0.48 + slideY);

            const step = iw * 0.3;
            const flow = (p * 1.8) % 1;
            const cs = Math.min(iw * 0.18, minSide * 0.03);
            const fadeMargin = iw * 0.18;
            ctx.save();
            ctx.beginPath();
            ctx.rect(ix, iy + ih * 0.64, iw, ih * 0.28);
            ctx.clip();
            for (let k = -1; k <= 4; k++) {
              const px = ix + (k + flow) * step;
              const distEdge = Math.min(px - ix, ix + iw - px);
              const alpha = clamp(distEdge / fadeMargin, 0, 1);
              if (alpha > 0.01) {
                ctx.save();
                ctx.globalAlpha *= alpha;
                drawChevron(px, iy + ih * 0.78, cs, minSide * 0.007, 1, PALETTE.bg, false);
                ctx.restore();
              }
            }
            ctx.restore();
          } else if (r === 2 && c === 0) {
            const fs1 = fitFontSize('100% ONLINE', iw * 0.9, ih * 0.52, minSide * 0.032, '900');
            ctx.font = '900 ' + fs1 + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('100% ONLINE', ix + iw * 0.5, iy + ih * 0.52 + slideY);
          } else if (r === 2 && c === 1) {
            const label = 'SHOP NOW';
            const chevZone = iw * 0.18;
            const maxTW = iw - chevZone * 2 - minSide * 0.03;
            const fs = fitFontSize(label, maxTW, ih * 0.58, minSide * 0.056, '900');
            ctx.font = '900 ' + fs + 'px ' + FONT_FAMILY;
            ctx.fillStyle = PALETTE.bg;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(label, ix + iw * 0.5, iy + ih * 0.52 + slideY);

            const cs = Math.min(ih * 0.34, minSide * 0.028);
            const drift = Math.sin(p * Math.PI * 4) * minSide * 0.01;
            drawChevron(ix + chevZone * 0.45 + drift, iy + ih * 0.5, cs, minSide * 0.007, 1, PALETTE.ink, false);
            drawChevron(ix + iw - chevZone * 0.45 - drift, iy + ih * 0.5, cs, minSide * 0.007, -1, PALETTE.ink, false);
          } else if (r === 2 && c === 2) {
            const rad = Math.min(iw, ih) * 0.34;
            const rot = -easeInOutQuart(clamp(p / 0.85, 0, 1)) * Math.PI;
            drawSwissAsterisk(ix + iw * 0.5, iy + ih * 0.5, rad, 4, minSide * 0.008, rot, PALETTE.ink);
          }
        }
        ctx.restore();
      }
      ctx.restore();
    }
  }
}
